window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["N3"]={"deck":"N3","slides":[{"p":1,"title":"표지: 3강 Neural NLP Foundations","terms":["Natural Language Processing (NLP)","Neural Network"],"pass1":[{"kind":"say","lines":["3주차 강의 제목은 'Neural NLP Foundations' 예요.","뜻은 '신경망으로 하는 **NLP(자연어처리)**의 기초' 예요.","과목 주문 기억하죠? 글을 토큰으로 자르고, 토큰을 벡터로 바꾸고, 벡터로 다음 토큰을 맞혀요.","오늘은 벡터를 받아 먹는 기계, **신경망(Neural Network)**을 만들어요."]}],"pass2":[],"pass3":[],"pass4":[]},{"p":2,"title":"Reminder: 자료 배포 금지","terms":["Natural Language Processing (NLP)"],"pass1":[{"kind":"say","lines":["안내 쪽이에요. 저작권이 있는 자료라 밖으로 퍼뜨리면 안 돼요.","**NLP(자연어처리)** 수업 자료 전체에 똑같이 적용돼요.","영상이나 소리에 문제가 있으면 바로 말해 달라는 부탁도 있어요."]}],"pass2":[],"pass3":[],"pass4":[]},{"p":3,"title":"목차: 오늘 배울 네 부분","terms":["Neural Network","Backpropagation","Language Model (LM)","Recurrent Neural Network (RNN)"],"pass1":[{"kind":"points","head":"오늘 배울 네 부분","items":["1. Neural Network Foundations: **뉴런(Neuron)** 하나에서 깊은 **신경망(Neural Network)**까지 (이 파일)","2. Backpropagation: **역전파(Backpropagation)**, 신경망이 배우는 방법","3. Language Modeling, the n-gram Era: 다음 단어를 세어서 맞히던 **언어 모델(Language Model)**","4. Neural Language Models and RNNs: 기억을 가진 **RNN(순환 신경망)**"]}],"pass2":[],"pass3":[],"pass4":[]},{"p":4,"title":"Recap: 지난주와 오늘","terms":["Byte Pair Encoding (BPE)","word2vec","Word Vector","Neural Network","Language Model (LM)","Backpropagation"],"pass1":[{"kind":"say","lines":["지난주에는 글을 **토큰(Token)**으로 자르고(**BPE(바이트 쌍 인코딩)**), **word2vec**로 벡터를 만들었어요.","그런데 벡터를 만들어 놓고 끝이 아니에요. 그 벡터를 먹고 답을 내는 기계가 필요해요.","그 기계가 오늘의 **신경망(Neural Network)**이에요."]},{"kind":"figure","head":"지금까지의 흐름과 오늘 채울 칸","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect x=\"10\" y=\"100\" width=\"80\" height=\"44\" rx=\"2\" class=\"box\"/><text x=\"50.0\" y=\"127.6\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">글<\/text><line x1=\"92\" y1=\"122\" x2=\"111.6\" y2=\"122.0\" class=\"e2\"/><polygon points=\"118,122 110.0,118.0 110.0,126.0\" class=\"arrow\"/><rect x=\"120\" y=\"100\" width=\"80\" height=\"44\" rx=\"2\" class=\"box\"/><text x=\"160.0\" y=\"127.6\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">토큰<\/text><line x1=\"202\" y1=\"122\" x2=\"221.6\" y2=\"122.0\" class=\"e2\"/><polygon points=\"228,122 220.0,118.0 220.0,126.0\" class=\"arrow\"/><rect x=\"230\" y=\"100\" width=\"80\" height=\"44\" rx=\"2\" class=\"box2\"/><text x=\"270.0\" y=\"127.6\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">벡터<\/text><line x1=\"312\" y1=\"122\" x2=\"331.6\" y2=\"122.0\" class=\"e2 b1\"/><polygon points=\"338,122 330.0,118.0 330.0,126.0\" class=\"arrow b1\"/><rect x=\"340\" y=\"100\" width=\"130\" height=\"44\" rx=\"2\" class=\"box2 b1\"/><text x=\"405.0\" y=\"128.3\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b1\">???<\/text><text x=\"270\" y=\"60\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">지난주(2주차)까지<\/text><text x=\"405\" y=\"186\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b2\">오늘: 신경망<\/text><text x=\"405\" y=\"210\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">벡터를 먹는 기계<\/text><text x=\"240\" y=\"250\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">다음 목표: 다음 토큰 맞히기(언어 모델)<\/text><\/svg>","caption":"글 → 토큰 → 벡터 → ??? 의 빈칸을 **신경망(Neural Network)**으로 채워요.","builds":3}],"pass2":[{"kind":"compare","head":"슬라이드 영어 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["meaning as vectors, learned by predicting neighbors","뜻을 벡터로, 이웃 단어를 맞히며 배워요(**word2vec**)"],["something has to consume those vectors","그 벡터를 받아 먹을 무언가가 필요해요"],["the machine that eats vectors","벡터를 먹는 기계 = **신경망(Neural Network)**"],["the task that will carry us to GPT","GPT 까지 데려갈 과제 = 언어 모델링(**언어 모델(Language Model)**)"],["how does a network compute? how does it learn?","신경망은 어떻게 계산하나? 어떻게 배우나?"]]},{"kind":"points","head":"오늘의 두 질문","items":["계산: **신경망(Neural Network)**은 벡터를 받아 어떻게 답을 내나요? (Part 1, 이 파일)","학습: 좋은 **가중치(Weight)**는 어떻게 찾나요? (**역전파(Backpropagation)**, Part 2)"]},{"kind":"check","q":"오늘 신경망이 입력으로 받는 것은 무엇인가요?","choices":["글자 그대로의 문장","지난주에 만든 단어 벡터","정답 레이블만"],"a":1,"why":"**word2vec** 등으로 만든 **단어 벡터(Word Vector)**가 **신경망(Neural Network)**의 입력이에요. 모델은 글을 직접 읽지 못해요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.06,"y":0.195,"w":0.8,"h":0.045,"say":"'Last week': 지난주는 **BPE(바이트 쌍 인코딩)** 토큰화와 **word2vec** 였어요."},{"x":0.06,"y":0.255,"w":0.74,"h":0.045,"say":"'text → tokens → vectors → ???': 벡터 다음 칸이 아직 비어 있어요."},{"x":0.06,"y":0.315,"w":0.9,"h":0.045,"say":"'Today': 벡터를 먹는 기계(**신경망(Neural Network)**)와, GPT 까지 이어질 과제 언어 모델링(**언어 모델(Language Model)**)."},{"x":0.06,"y":0.375,"w":0.47,"h":0.045,"say":"'New format': 이제부터 이론 2시간(쉬는 시간 포함) + 실습 1시간."},{"x":0.06,"y":0.435,"w":0.8,"h":0.045,"say":"'Assignment 2 goes out': 과제 2가 나가요. 15%, word2vec 기울기 + 구현, 7주차 마감."}]},{"kind":"prof","when":"3주차 월요일 1교시","lines":["오늘은 이론을 2시간 정도, 실습을 1시간 정도 해요.","오늘 좀 큰 과제가 하나 나가고, 한 달쯤 뒤 10월 7일까지 내면 돼요.","과제 2에 **역전파(Backpropagation)** 부분이 있어서 수업을 잘 들으면 어렵지 않게 할 수 있을 거예요."]}],"pass4":[{"kind":"warn","head":"헷갈리기 쉬운 점","items":["과제 2 마감을 슬라이드는 'due W7'(7주차), 교수님은 '10월 7일' 이라고 말했어요. 공지를 꼭 확인해요.","과제 2는 **word2vec**의 **기울기(Gradient)** 계산과 구현이에요. 오늘 Part 2 **역전파(Backpropagation)**와 이어지는 부분이에요.","지난주 **BPE(바이트 쌍 인코딩)**는 토큰을 만드는 쪽, **word2vec**는 벡터를 만드는 쪽이에요. 둘을 섞지 않아요."]}]},{"p":5,"title":"Part 1: Neural Network Foundations","terms":["Neural Network","Neuron"],"pass1":[{"kind":"say","lines":["Part 1 시작이에요. 부제는 'from a single neuron to deep networks' 예요.","뜻: **뉴런(Neuron)** 하나에서 시작해 깊은 **신경망(Neural Network)**까지 가 봐요."]}],"pass2":[],"pass3":[],"pass4":[]},{"p":6,"title":"붙잡을 과제: NER","terms":["Named Entity Recognition (NER)","Classification","Window","Center Word","Word Vector"],"pass1":[{"kind":"say","lines":["기계를 만들기 전에 붙잡고 갈 예제 과제를 하나 정해요. **NER(개체명 인식)**이에요.","글 속에서 사람, 기관, 장소 같은 이름을 찾아 종류를 붙이는 일이에요.","예: 'Busan' 을 보면 '이건 장소(LOCATION)' 라고 붙여요."]},{"kind":"figure","head":"가운데 단어를 양옆 단어와 함께 보기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"24\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">윈도우 m=2: 가운데 단어 앞 2개 + 뒤 2개<\/text><rect x=\"6\" y=\"40\" width=\"54\" height=\"34\" rx=\"2\" class=\"n\"/><text x=\"33\" y=\"62\" font-size=\"13\" text-anchor=\"middle\" class=\"tl\">the<\/text><rect x=\"65\" y=\"40\" width=\"54\" height=\"34\" rx=\"2\" class=\"n\"/><text x=\"92\" y=\"62\" font-size=\"13\" text-anchor=\"middle\" class=\"tl\">launch<\/text><rect x=\"124\" y=\"40\" width=\"54\" height=\"34\" rx=\"2\" class=\"n3 b1\"/><text x=\"151\" y=\"62\" font-size=\"13\" text-anchor=\"middle\" class=\"tl\">event<\/text><rect x=\"183\" y=\"40\" width=\"54\" height=\"34\" rx=\"2\" class=\"n3 b1\"/><text x=\"210\" y=\"62\" font-size=\"13\" text-anchor=\"middle\" class=\"tl\">in<\/text><rect x=\"242\" y=\"40\" width=\"54\" height=\"34\" rx=\"2\" class=\"n4\"/><text x=\"269\" y=\"62\" font-size=\"13\" text-anchor=\"middle\" class=\"tl\">Busan<\/text><rect x=\"301\" y=\"40\" width=\"54\" height=\"34\" rx=\"2\" class=\"n3 b1\"/><text x=\"328\" y=\"62\" font-size=\"13\" text-anchor=\"middle\" class=\"tl\">drew<\/text><rect x=\"360\" y=\"40\" width=\"54\" height=\"34\" rx=\"2\" class=\"n3 b1\"/><text x=\"387\" y=\"62\" font-size=\"13\" text-anchor=\"middle\" class=\"tl\">big<\/text><rect x=\"419\" y=\"40\" width=\"54\" height=\"34\" rx=\"2\" class=\"n\"/><text x=\"446\" y=\"62\" font-size=\"13\" text-anchor=\"middle\" class=\"tl\">crowds<\/text><line x1=\"151\" y1=\"76\" x2=\"240\" y2=\"140\" class=\"e b1\"/><line x1=\"210\" y1=\"76\" x2=\"240\" y2=\"140\" class=\"e b1\"/><line x1=\"269\" y1=\"76\" x2=\"240\" y2=\"140\" class=\"e b1\"/><line x1=\"328\" y1=\"76\" x2=\"240\" y2=\"140\" class=\"e b1\"/><line x1=\"387\" y1=\"76\" x2=\"240\" y2=\"140\" class=\"e b1\"/><rect x=\"80\" y=\"142\" width=\"320\" height=\"40\" rx=\"2\" class=\"box2 b2\"/><text x=\"240.0\" y=\"166.9\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b2\">event, in, Busan, drew, big 벡터 이어 붙이기<\/text><line x1=\"240\" y1=\"184\" x2=\"240.0\" y2=\"207.6\" class=\"e2 b3\"/><polygon points=\"240,214 244.0,206.0 236.0,206.0\" class=\"arrow b3\"/><rect x=\"110\" y=\"216\" width=\"260\" height=\"40\" rx=\"2\" class=\"box b3\"/><text x=\"240.0\" y=\"240.9\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b3\">분류기: Busan 은 장소일 확률?<\/text><\/svg>","caption":"**중심 단어(Center Word)** Busan 과 양옆 두 단어씩, 모두 다섯 단어의 **단어 벡터(Word Vector)**를 이어 붙여 분류기에 넣어요.","builds":3}],"pass2":[{"kind":"compare","head":"슬라이드 영어 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["A Task to Hold Onto","(설명하는 동안) 붙잡고 갈 과제"],["find and classify names in text","글에서 이름을 찾아 종류를 가르기"],["classify each word using its context window","단어마다 주변 **윈도우(Window)**를 보고 **분류(Classification)**하기"],["Concatenated word vectors in, a decision out","이어 붙인 단어 벡터가 들어가고, 판정 하나가 나와요"],["now we need the classifier","이제 분류기(가운데 상자)를 만들어야 해요"]]},{"kind":"points","head":"이 쪽 용어 하나하나","items":["**NER(개체명 인식)**: 이름을 찾아 사람, 기관, 장소 같은 종류를 붙이는 일","**분류(Classification)**: 정해진 여러 칸(클래스) 중 하나를 고르는 일. **NER(개체명 인식)**도 단어마다 **분류(Classification)**해요.","**윈도우(Window)**: **중심 단어(Center Word)** 양옆으로 몇 단어씩 함께 보는 창. m=2 면 양쪽 2개씩이에요.","**중심 단어(Center Word)**: 지금 판단하려는 가운데 단어(여기서는 Busan)"]},{"kind":"steps","head":"창 분류가 흘러가는 순서","steps":["문장에서 판단할 단어(Busan)를 고르고 양옆 두 단어씩 잡아요","다섯 단어 각각의 **단어 벡터(Word Vector)**(길이 d)를 꺼내요","다섯 벡터를 옆으로 이어 붙여 길이 5d 벡터 하나를 만들어요","분류기가 'Busan 이 장소일 확률' 을 내요"],"answer":"단어 벡터 이어 붙이기 → 분류기 → 확률 하나"},{"kind":"check","q":"**NER(개체명 인식)**에서 'Busan' 에 붙을 알맞은 종류는?","choices":["PERSON(사람)","LOCATION(장소)","ORGANIZATION(기관)"],"a":1,"why":"부산은 장소 이름이라 LOCATION 이에요. 사람 이름이면 PERSON 을 붙여요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.06,"y":0.195,"w":0.64,"h":0.045,"say":"'named entity recognition (NER)': 오늘 계속 쓸 예제 과제 **NER(개체명 인식)**."},{"x":0.32,"y":0.38,"w":0.27,"h":0.045,"say":"'window (m = 2) around the center word': 가운데 단어 둘레 창, 양쪽 2단어씩."},{"x":0.452,"y":0.44,"w":0.07,"h":0.078,"say":"Busan: 판단할 **중심 단어(Center Word)**. 주황색으로 칠해져 있어요."},{"x":0.275,"y":0.615,"w":0.36,"h":0.083,"say":"x_window: 다섯 단어 벡터를 이어 붙인 것. 길이가 5d 예요."},{"x":0.34,"y":0.76,"w":0.32,"h":0.045,"say":"'P(center word is a LOCATION)': 가운데 단어가 장소일 확률."}]},{"kind":"formula","head":"창 벡터의 모양","tex":"x_{\\text{window}} = [\\,x_{\\text{event}}\\;\\; x_{\\text{in}}\\;\\; x_{\\text{Busan}}\\;\\; x_{\\text{drew}}\\;\\; x_{\\text{big}}\\,] \\in \\mathbb{R}^{5d}","parts":[{"sym":"x_{\\text{Busan}}","say":"Busan 의 **단어 벡터(Word Vector)**. 길이 d"},{"sym":"[\\;\\cdots\\;]","say":"다섯 벡터를 옆으로 줄 세워 이어 붙이기"},{"sym":"\\mathbb{R}^{5d}","say":"숫자 5d 개짜리 벡터라는 뜻. d=100 이면 500개"}],"whole":"창 안 다섯 단어의 벡터를 이어 붙여 긴 벡터 하나로 만들어요."},{"kind":"prof","when":"3주차 월요일 1교시","lines":["부산이 나오면 위치구나, 사람 이름이 나오면 사람 이름이구나, 이렇게 태그를 달아 주는 게 NER 이에요.","한 단어만 보고 바로 맞히는 게 아니라 주변 컨텍스트 윈도우와 함께 봐요.","지난주에 만든 워드 벡터가 여기서 입력으로 쓰여요."]},{"kind":"bg","src":"기초 다지기 1단원","lines":["벡터는 숫자를 줄 세운 것이고, 줄 선 숫자 개수가 차원이에요.","길이 d 벡터 다섯 개를 이어 붙이면 길이 5d 벡터가 돼요."]}],"pass4":[{"kind":"check","q":"단어 벡터가 d=50 차원이고 윈도우 m=2 일 때 x_window 의 길이는?","choices":["50","100","250","500"],"a":2,"why":"가운데 단어 + 양쪽 2개씩 = 5단어, 5 × 50 = 250이에요."},{"kind":"english","head":"외워 쓸 답안 문장","en":"창 기반 **NER(개체명 인식)**은 **중심 단어(Center Word)**와 양옆 단어의 벡터를 이어 붙여 분류기로 종류를 **분류(Classification)**한다.","ko":"창(window) → 이어 붙이기(concatenate) → 분류기 → 확률.","tip":"'창, 이어 붙이기, 분류기' 세 낱말을 순서대로 외워요."}]},{"p":7,"title":"분류의 기본 세팅","terms":["Supervised Learning","Label","Softmax","Logit","Cross-Entropy","Loss Function","Logistic Regression","Matrix","Classification"],"pass1":[{"kind":"say","lines":["분류기의 가장 단순한 모양부터 봐요. 이건 **지도 학습(Supervised Learning)**이에요.","문제(입력)와 정답(**레이블(Label)**)을 짝으로 잔뜩 주고 배우게 해요."]},{"kind":"analogy","head":"점수를 확률로, 틀리면 벌점","scene":"모델이 칸마다 점수를 매기면 **소프트맥스(Softmax)**가 확률 파이로 나눠요. 정답 칸 조각이 작으면 벌점을 크게 받아요.","map":[["칸마다 매긴 점수","**로짓(Logit)**"],["모두 더해 1인 확률 파이","**소프트맥스(Softmax)**"],["틀린 만큼 받는 벌점","**손실 함수(Loss Function)**(**교차 엔트로피(Cross-Entropy)**)"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["Supervised learning: pairs {x, y}","**지도 학습(Supervised Learning)**: (입력, 정답) 짝으로 배우기"],["scores for every class, squashed into probabilities","클래스마다 점수를 매겨 확률로 눌러 담기"],["Train by making the true class likely","정답 클래스의 확률이 커지도록 학습"],["softmax + NLL, week 2's friend","**소프트맥스(Softmax)** + 음의 로그 우도(NLL), 2주차에 본 친구"],["just logistic regression, a LINEAR machine","그냥 **로지스틱 회귀(Logistic Regression)**, 즉 선형 기계예요"]]},{"kind":"points","head":"이 쪽 용어 하나하나","items":["**지도 학습(Supervised Learning)**: 입력 x 와 정답 **레이블(Label)** y 를 짝으로 주고 배우게 하는 방법","**로짓(Logit)**: Wx 로 얻은 날것 점수. 음수도 될 수 있고 확률이 아니에요.","**소프트맥스(Softmax)**: **로짓(Logit)**을 0~1 사이, 합이 1인 확률로 바꿔요.","**교차 엔트로피(Cross-Entropy)**: 정답 칸 확률의 -log 를 평균 낸 **손실 함수(Loss Function)**예요."]},{"kind":"steps","head":"분류기 한 번 돌리기","steps":["입력 x 에 **행렬(Matrix)** W 를 곱해 클래스마다 **로짓(Logit)**(점수)을 얻어요","**소프트맥스(Softmax)**로 점수를 확률로 바꿔요","정답 클래스의 확률을 봐요","그 확률의 -log 가 벌점, 즉 **교차 엔트로피(Cross-Entropy)** **손실 함수(Loss Function)**예요","벌점이 줄어드는 쪽으로 W 를 고쳐요"],"answer":"점수 → 확률 → 벌점 → W 고치기"},{"kind":"check","q":"**로짓(Logit)**(점수)에 대한 설명으로 맞는 것은?","choices":["항상 0과 1 사이다","음수도 나올 수 있고 확률이 아니다","다 더하면 1이다"],"a":1,"why":"**로짓(Logit)**은 Wx 라서 음수도 나와요. 0~1, 합 1 은 **소프트맥스(Softmax)**를 통과한 뒤의 성질이에요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.06,"y":0.195,"w":0.56,"h":0.045,"say":"'a training set of pairs {x_i, y_i}': 입력과 정답 **레이블(Label)**의 짝 모음."},{"x":0.245,"y":0.335,"w":0.465,"h":0.165,"say":"**소프트맥스(Softmax)** 분류기 식. 정답 칸 점수의 exp 를 모든 칸 exp 합으로 나눠요."},{"x":0.06,"y":0.56,"w":0.64,"h":0.045,"say":"'cross-entropy loss (softmax + NLL)': **교차 엔트로피(Cross-Entropy)**는 **소프트맥스(Softmax)** 뒤에 음의 로그를 붙인 것."},{"x":0.29,"y":0.67,"w":0.4,"h":0.12,"say":"J(θ): 학습 자료 N개에서 정답 확률의 -log 를 평균 낸 값."},{"x":0.32,"y":0.855,"w":0.37,"h":0.045,"say":"'just logistic regression, a LINEAR machine': 아직은 선형인 **로지스틱 회귀(Logistic Regression)**."}]},{"kind":"formula","head":"**소프트맥스(Softmax)** 분류기","tex":"P(y \\mid x) = \\mathrm{softmax}(Wx)_y = \\frac{\\exp(W_y x)}{\\sum_c \\exp(W_c x)}","parts":[{"sym":"W","say":"가중치 **행렬(Matrix)**. 한 줄(행)이 클래스 하나를 맡아요"},{"sym":"W_y x","say":"정답 후보 y 칸의 점수(**로짓(Logit)**)"},{"sym":"\\exp(\\cdot)","say":"점수를 늘 양수로 바꾸는 지수 함수"},{"sym":"\\sum_c","say":"모든 클래스 c 의 값을 다 더하기"},{"sym":"P(y \\mid x)","say":"x 를 봤을 때 답이 y 일 확률"}],"whole":"점수에 exp 를 씌우고 전체 합으로 나누면 합이 1인 확률이 돼요."},{"kind":"formula","head":"**교차 엔트로피(Cross-Entropy)** **손실 함수(Loss Function)**","tex":"J(\\theta) = \\frac{1}{N}\\sum_{i=1}^{N} -\\log P(y_i \\mid x_i)","parts":[{"sym":"\\theta","say":"모든 **파라미터(Parameter)**(여기서는 W)"},{"sym":"P(y_i \\mid x_i)","say":"i번째 문제에서 정답 **레이블(Label)**에 준 확률"},{"sym":"-\\log","say":"확률이 작을수록 크게 커지는 벌점"},{"sym":"\\frac{1}{N}\\sum","say":"문제 N개의 벌점 평균"}],"whole":"정답에 준 확률의 -log 를 평균 내요. 이 값을 줄이는 게 학습이에요."},{"kind":"steps","head":"손계산: **소프트맥스(Softmax)**와 **교차 엔트로피(Cross-Entropy)**","given":"로그는 자연로그(ln) 예요.","steps":["점수: PERSON 1, LOCATION 3, ORG 0 (정답은 LOCATION)","exp: e¹ ≈ 2.72, e³ ≈ 20.09, e⁰ = 1, 합 ≈ 23.80","확률: 2.72/23.80 ≈ 0.11, 20.09/23.80 ≈ 0.84, 1/23.80 ≈ 0.04","벌점: -log(0.84) ≈ 0.17","비교: 정답에 0.9 를 주면 -log 0.9 ≈ 0.11, 0.01 을 주면 -log 0.01 ≈ 4.61"],"answer":"정답 확률 0.84 → 벌점 약 0.17. 정답 확률이 작을수록 벌점이 크게 뛰어요."},{"kind":"prof","when":"3주차 월요일 1교시","lines":["Wx 로 얻은 값을 로짓 혹은 스코어라고 해요. 이 점수 자체는 확률이 아니고 음수도 나올 수 있어요.","정답이 로케이션일 때 로케이션에 0.9 를 주면 잘한 것, 0.01 을 주면 굉장히 잘못한 거예요.","소프트맥스와 NLL 을 같이 한 걸 크로스 엔트로피 로스라고 해요.","중요한 건 W 가 단 하나의 행렬로 표현된다는 것, 즉 모델이 선형이라는 거예요."]},{"kind":"bg","src":"기초 다지기 6단원","lines":["**소프트맥스(Softmax)**는 점수 → 확률, **교차 엔트로피(Cross-Entropy)**는 정답 확률의 -log 를 벌점으로 쓰는 것이에요.","로그와 exp 가 낯설면 기초 다지기 4단원을 먼저 봐요."]}],"pass4":[{"kind":"check","q":"정답 클래스에 준 확률이 0.01 에서 0.9 로 올라가면 **교차 엔트로피(Cross-Entropy)**는?","choices":["커진다","작아진다","변하지 않는다"],"a":1,"why":"-log 0.01 ≈ 4.61, -log 0.9 ≈ 0.11 이라 벌점이 작아져요."},{"kind":"english","head":"외워 쓸 답안 문장","en":"**소프트맥스(Softmax)** 분류기는 **로짓(Logit)**(Wx)을 확률로 바꾸고, **교차 엔트로피(Cross-Entropy)** **손실 함수(Loss Function)**는 정답 클래스 확률의 음의 로그를 평균 낸 값이다.","ko":"W 가 **행렬(Matrix)** 하나뿐이라 이 분류기는 선형(**로지스틱 회귀(Logistic Regression)**)이다.","tip":"점수 → 확률 → -log 평균, 세 단계로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**소프트맥스(Softmax)**가 곧 **교차 엔트로피(Cross-Entropy)**는 아니에요. **소프트맥스(Softmax)** + NLL(-log) = **교차 엔트로피(Cross-Entropy)**예요.","**로지스틱 회귀(Logistic Regression)**는 이름에 '회귀' 가 있지만 **분류(Classification)** 모델이에요."]}]},{"p":8,"title":"선형의 한계","terms":["Linear Classifier","Hyperplane","Decision Boundary","Nonlinearity"],"pass1":[{"kind":"say","lines":["지금까지 만든 분류기는 **선형 분류기(Linear Classifier)**예요. 곧은 선 하나로만 무리를 갈라요.","그런데 곧은 선 하나로는 못 가르는 모양이 있어요."]},{"kind":"figure","head":"곧은 선으로는 못 가르는 배치","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect x=\"20\" y=\"20\" width=\"440\" height=\"230\" rx=\"2\" class=\"box\"/><circle cx=\"96\" cy=\"74\" r=\"5\" class=\"n4\"/><circle cx=\"110\" cy=\"68\" r=\"5\" class=\"n4\"/><circle cx=\"122\" cy=\"76\" r=\"5\" class=\"n4\"/><circle cx=\"104\" cy=\"88\" r=\"5\" class=\"n4\"/><circle cx=\"120\" cy=\"90\" r=\"5\" class=\"n4\"/><circle cx=\"110\" cy=\"80\" r=\"5\" class=\"n4\"/><circle cx=\"356\" cy=\"74\" r=\"5\" class=\"n2\"/><circle cx=\"370\" cy=\"68\" r=\"5\" class=\"n2\"/><circle cx=\"382\" cy=\"76\" r=\"5\" class=\"n2\"/><circle cx=\"364\" cy=\"88\" r=\"5\" class=\"n2\"/><circle cx=\"380\" cy=\"90\" r=\"5\" class=\"n2\"/><circle cx=\"370\" cy=\"80\" r=\"5\" class=\"n2\"/><circle cx=\"96\" cy=\"189\" r=\"5\" class=\"n2\"/><circle cx=\"110\" cy=\"183\" r=\"5\" class=\"n2\"/><circle cx=\"122\" cy=\"191\" r=\"5\" class=\"n2\"/><circle cx=\"104\" cy=\"203\" r=\"5\" class=\"n2\"/><circle cx=\"120\" cy=\"205\" r=\"5\" class=\"n2\"/><circle cx=\"110\" cy=\"195\" r=\"5\" class=\"n2\"/><circle cx=\"356\" cy=\"189\" r=\"5\" class=\"n4\"/><circle cx=\"370\" cy=\"183\" r=\"5\" class=\"n4\"/><circle cx=\"382\" cy=\"191\" r=\"5\" class=\"n4\"/><circle cx=\"364\" cy=\"203\" r=\"5\" class=\"n4\"/><circle cx=\"380\" cy=\"205\" r=\"5\" class=\"n4\"/><circle cx=\"370\" cy=\"195\" r=\"5\" class=\"n4\"/><text x=\"240\" y=\"140\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">빨강 두 무리, 파랑 두 무리가 엇갈려 있어요<\/text><line x1=\"30\" y1=\"60\" x2=\"450\" y2=\"215\" class=\"e2 b1\"/><text x=\"430\" y=\"245\" font-size=\"14\" text-anchor=\"end\" class=\"tb b1\">직선: 어떻게 그어도 실패<\/text><polyline points=\"30,140 90,125 160,140 200,110 240,60 280,110 330,140 400,125 450,140\" fill=\"none\" class=\"hl b2\"/><text x=\"40\" y=\"40\" font-size=\"14\" text-anchor=\"start\" class=\"tb b2\">곡선이면 가를 수 있어요<\/text><\/svg>","caption":"빨강 두 무리와 파랑 두 무리가 엇갈려 있으면 직선은 실패해요. 휘어진 **결정 경계(Decision Boundary)**가 필요해요.","builds":2}],"pass2":[{"kind":"compare","head":"슬라이드 영어 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["The Limit of Linear","선형의 한계"],["can only draw a straight line (hyperplane)","곧은 선(**초평면(Hyperplane)**)만 그을 수 있어요"],["a LINE cannot separate these","선 하나로는 이것들을 못 갈라요"],["a CURVED boundary can, we need nonlinearity","휘어진 경계면 돼요, **비선형성(Nonlinearity)**이 필요해요"],["\"not bad\" is not the sum of \"not\" and \"bad\"","'not bad' 는 'not' 과 'bad' 를 그냥 더한 뜻이 아니에요"]]},{"kind":"points","head":"이 쪽 용어 하나하나","items":["**선형 분류기(Linear Classifier)**: **행렬(Matrix)** W 하나만 곱하는 분류기. 경계가 곧아요.","**결정 경계(Decision Boundary)**: 'A 쪽, B 쪽' 을 가르는 경계선","**초평면(Hyperplane)**: 곧은 경계. 2차원이면 선, 3차원이면 면이에요.","**비선형성(Nonlinearity)**: 경계를 휘게 만드는 성질"]},{"kind":"check","q":"**선형 분류기(Linear Classifier)**의 **결정 경계(Decision Boundary)** 모양은?","choices":["항상 곧은 선(평면)","원하는 대로 휘어진 곡선","점 하나"],"a":0,"why":"**선형 분류기(Linear Classifier)**는 **초평면(Hyperplane)**, 즉 곧은 경계만 그을 수 있어요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.06,"y":0.195,"w":0.55,"h":0.045,"say":"'only draw a straight line (hyperplane)': **선형 분류기(Linear Classifier)**는 **초평면(Hyperplane)**만 그어요."},{"x":0.115,"y":0.285,"w":0.385,"h":0.45,"say":"왼쪽: 빨강이 왼위, 오른아래, 파랑이 오른위, 왼아래. 빨간 점선 하나로는 못 갈라요."},{"x":0.53,"y":0.285,"w":0.39,"h":0.45,"say":"오른쪽: 초록 곡선이면 갈라져요. 그래서 **비선형성(Nonlinearity)**이 필요해요."},{"x":0.22,"y":0.855,"w":0.57,"h":0.045,"say":"'not bad': 'not' 이 뒤 단어에 따라 역할이 바뀌는 상호작용이에요."}]},{"kind":"prof","when":"3주차 월요일 1교시","lines":["왼쪽 그림은 XOR 같은 패턴이에요. 어떻게 직선을 그어도 파란색과 빨간색을 완벽히 못 갈라요.","good 은 긍정, bad 는 부정인데 not 이 붙으면 not good 은 부정, not bad 는 오히려 긍정이 돼요.","not 이 늘 같은 값을 더하는 게 아니라 뒤 단어에 따라 역할이 달라져요.","이런 피처 사이 상호작용을 표현하게 해 주는 게 비선형 활성화를 가진 뉴런이에요."]},{"kind":"points","head":"말과 그림을 짝지으면","items":["왼쪽 그림처럼, 'not' 과 'bad' 를 따로 더해서는 'not bad' 의 긍정을 못 맞혀요.","두 특징이 함께 있을 때 뜻이 뒤집히는 걸 상호작용(interaction)이라고 해요.","상호작용을 잡으려면 휘어진 **결정 경계(Decision Boundary)**, 즉 **비선형성(Nonlinearity)**이 필요해요."]}],"pass4":[{"kind":"check","q":"'not bad' 가 선형 모델에게 어려운 까닭은?","choices":["단어가 너무 길어서","두 단어가 합쳐질 때 뜻이 뒤집히는 상호작용이라서","사전에 없는 단어라서"],"a":1,"why":"'not' 이 뒤 단어에 따라 역할이 바뀌어요. 효과를 따로 더하는 **선형 분류기(Linear Classifier)**로는 못 잡아요."},{"kind":"english","head":"외워 쓸 답안 문장","en":"**선형 분류기(Linear Classifier)**는 **초평면(Hyperplane)**만 그어서 XOR 배치나 'not bad' 같은 상호작용을 못 잡으므로 **비선형성(Nonlinearity)**이 필요하다.","ko":"곧은 선의 한계 → 휘어진 경계 → 비선형성."}]},{"p":9,"title":"뉴런 하나","terms":["Neuron","Weight","Weighted Sum","Bias Term","Activation Function","Nonlinearity","ReLU","Sigmoid"],"pass1":[{"kind":"say","lines":["**신경망(Neural Network)**의 벽돌 한 장이 **뉴런(Neuron)**이에요.","**뉴런(Neuron)**은 입력마다 중요도를 곱해 더하고, 마지막에 한 번 휘어서 내보내요.","슬라이드 말로는 '작고 배울 수 있는 패턴 탐지기' 예요."]},{"kind":"figure","head":"**뉴런(Neuron)** 하나가 하는 일","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><circle cx=\"40\" cy=\"60\" r=\"18\" class=\"n\"/><text x=\"40\" y=\"64.9\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">x1<\/text><circle cx=\"40\" cy=\"130\" r=\"18\" class=\"n\"/><text x=\"40\" y=\"134.9\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">x2<\/text><circle cx=\"40\" cy=\"200\" r=\"18\" class=\"n\"/><text x=\"40\" y=\"204.9\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">x3<\/text><line x1=\"58\" y1=\"64\" x2=\"172\" y2=\"124\" class=\"e b1\"/><line x1=\"58\" y1=\"130\" x2=\"172\" y2=\"132\" class=\"e b1\"/><line x1=\"58\" y1=\"196\" x2=\"172\" y2=\"140\" class=\"e b1\"/><text x=\"115\" y=\"80\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">w1<\/text><text x=\"115\" y=\"124\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">w2<\/text><text x=\"115\" y=\"186\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">w3<\/text><circle cx=\"210\" cy=\"132\" r=\"38\" class=\"n2 b1\"/><text x=\"210\" y=\"137.25\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">합 + b<\/text><circle cx=\"210\" cy=\"232\" r=\"14\" class=\"n3 b2\"/><text x=\"210\" y=\"236.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b2\">1<\/text><line x1=\"210\" y1=\"218\" x2=\"210\" y2=\"170\" class=\"e b2\"/><text x=\"222\" y=\"200\" font-size=\"14\" text-anchor=\"start\" class=\"tm b2\">b<\/text><line x1=\"248\" y1=\"132\" x2=\"293.6\" y2=\"132.0\" class=\"e2 b3\"/><polygon points=\"300,132 292.0,128.0 292.0,136.0\" class=\"arrow b3\"/><text x=\"274\" y=\"122\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">z<\/text><rect x=\"302\" y=\"110\" width=\"60\" height=\"44\" rx=\"2\" class=\"box2 b3\"/><text x=\"332.0\" y=\"138.3\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b3\">f<\/text><line x1=\"364\" y1=\"132\" x2=\"403.6\" y2=\"132.0\" class=\"e2 b4\"/><polygon points=\"410,132 402.0,128.0 402.0,136.0\" class=\"arrow b4\"/><text x=\"440\" y=\"138\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b4\">h<\/text><text x=\"210\" y=\"30\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">가중합 + 편향 항<\/text><text x=\"332\" y=\"196\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b3\">활성화 함수<\/text><\/svg>","caption":"입력 × **가중치(Weight)**를 더하고(**가중합(Weighted Sum)**) **편향 항(Bias Term)** b 를 더한 z 를 **활성화 함수(Activation Function)** f 에 통과시켜 h 를 내요.","builds":4}],"pass2":[{"kind":"compare","head":"슬라이드 영어 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["weighted sum + bias, passed through a nonlinearity","**가중합(Weighted Sum)** + **편향 항(Bias Term)**, 그다음 **비선형성(Nonlinearity)** 통과"],["weighted sum (affine transform)","**가중합(Weighted Sum)**(아핀 변환): wᵀx + b"],["loosely inspired by biology","생물의 신경세포에서 느슨하게 따온 이름"],["a tiny, learnable feature detector","작고, 배울 수 있는 특징 탐지기"],["One neuron = one learned pattern detector","**뉴런(Neuron)** 하나 = 학습된 패턴 탐지기 하나"]]},{"kind":"points","head":"이 쪽 용어 하나하나","items":["**가중치(Weight)**: 입력마다 얼마나 중요하게 볼지 곱하는 숫자 w","**가중합(Weighted Sum)**: 입력 × **가중치(Weight)**를 모두 더한 값","**편향 항(Bias Term)**: 더해 주는 숫자 b. 켜지는 기준을 옮겨요.","**활성화 함수(Activation Function)**: z 를 휘어진 값 f(z) 로 바꾸는 함수. **비선형성(Nonlinearity)**을 넣는 부품이에요."]},{"kind":"steps","head":"**뉴런(Neuron)** 안의 순서","steps":["입력 x₁, x₂, ..., x_d 가 들어와요","각 입력에 **가중치(Weight)** w 를 곱해요","모두 더하고 **편향 항(Bias Term)** b 를 더해 z 를 얻어요","z 를 **활성화 함수(Activation Function)** f 에 넣어 h = f(z) 를 내보내요"],"answer":"곱하고 → 더하고 → b 더하고 → 휘기"},{"kind":"check","q":"**뉴런(Neuron)**에서 **편향 항(Bias Term)** b 는 언제 더하나요?","choices":["**활성화 함수(Activation Function)**를 통과한 뒤","**가중합(Weighted Sum)**에 더한 뒤 **활성화 함수(Activation Function)**에 넣기 전","입력에 곱하기 전"],"a":1,"why":"z = wᵀx + b 를 먼저 만들고, 그 z 를 **활성화 함수(Activation Function)**에 넣어요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.19,"y":0.26,"w":0.05,"h":0.37,"say":"x₁ ... x_d: 입력 벡터의 숫자들. 선마다 w₁ ... w_d 가 붙어 있어요."},{"x":0.36,"y":0.33,"w":0.125,"h":0.19,"say":"Σ wᵢxᵢ + b: **가중합(Weighted Sum)**에 **편향 항(Bias Term)**를 더한 것. 아래 'weighted sum (affine transform)'."},{"x":0.4,"y":0.54,"w":0.045,"h":0.105,"say":"아래 '1' 과 b: 늘 1인 입력에 b 를 곱해 더한다고 그린 **편향 항(Bias Term)**."},{"x":0.535,"y":0.375,"w":0.105,"h":0.1,"say":"f( ): **활성화 함수(Activation Function)**. 아래에 'nonlinearity' 라고 적혀 있어요."},{"x":0.69,"y":0.395,"w":0.145,"h":0.1,"say":"h = f(wᵀx + b): 뉴런의 출력(output)."},{"x":0.69,"y":0.515,"w":0.25,"h":0.345,"say":"생물 신경세포 그림. 이름만 따왔고 실제로는 작은 특징 탐지기예요."}]},{"kind":"formula","head":"**뉴런(Neuron)**의 식","tex":"h = f(\\mathbf{w}^{\\top}\\mathbf{x} + b) = f\\Big(\\sum_{i=1}^{d} w_i x_i + b\\Big)","parts":[{"sym":"\\mathbf{x}","say":"입력 벡터 (숫자 d 개)"},{"sym":"\\mathbf{w}","say":"**가중치(Weight)** 벡터 (입력마다 하나)"},{"sym":"\\mathbf{w}^{\\top}\\mathbf{x}","say":"**가중합(Weighted Sum)**: 짝끼리 곱해서 더하기(내적)"},{"sym":"b","say":"**편향 항(Bias Term)**"},{"sym":"f","say":"**활성화 함수(Activation Function)**"},{"sym":"h","say":"뉴런의 출력"}],"whole":"곱해서 더하고 b 를 더한 뒤 f 로 휘면 **뉴런(Neuron)** 하나의 출력이에요."},{"kind":"steps","head":"손계산: 입력 3개짜리 **뉴런(Neuron)**","given":"x = [1, 2, 3], w = [0.5, -1, 0.5], b = 0.5","steps":["z = 0.5×1 + (-1)×2 + 0.5×3 + 0.5","= 0.5 - 2 + 1.5 + 0.5 = 0.5","**ReLU(렐루)**: max(0.5, 0) = 0.5","**시그모이드(Sigmoid)**: 1/(1+e^(-0.5)) ≈ 0.62","입력이 x = [1, 3, 1] 이면 z = -1.5 → ReLU 0 (꺼짐), 시그모이드 ≈ 0.18"],"answer":"z = 0.5, ReLU 출력 0.5, 시그모이드 출력 약 0.62"},{"kind":"prof","when":"3주차 월요일 1교시","lines":["입력마다 가중치를 곱하는데, 어떤 입력은 중요하게 보고 어떤 입력은 덜 중요하게 봐요.","w 를 곱하고 b 를 더하는 건 아핀 변환이라고도 부르는 선형 계산 하나예요.","뉴런 하나가 하는 일은 입력을 적절히 조합해 패턴 하나를 찾는 거예요.","여러 뉴런의 w 를 모아 놓은 게 앞에서 본 큰 행렬 W 예요."]},{"kind":"bg","src":"기초 다지기 9단원","lines":["**뉴런(Neuron)** = **가중합(Weighted Sum)** + **편향 항(Bias Term)** + **활성화 함수(Activation Function)**. 층, 순전파 이야기가 이어져요.","wᵀx 는 내적이에요. 곱해서 더하기가 낯설면 기초 다지기 2단원을 봐요."]}],"pass4":[{"kind":"check","q":"x = [2, 1], w = [1, -3], b = 0 인 **뉴런(Neuron)**에 **ReLU(렐루)**를 쓰면 출력은?","choices":["-1","0","1","5"],"a":1,"why":"z = 1×2 + (-3)×1 + 0 = -1. 음수라서 ReLU 는 0으로 꺼요."},{"kind":"english","head":"외워 쓸 답안 문장","en":"**뉴런(Neuron)**은 **가중합(Weighted Sum)**에 **편향 항(Bias Term)**를 더한 z 를 **활성화 함수(Activation Function)**에 통과시켜 h = f(wᵀx + b) 를 낸다.","ko":"곱하기 → 더하기 → b → f.","tip":"식 h = f(wᵀx + b) 하나로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["여기의 **편향 항(Bias Term)**(b)는 사회적 편향(Bias)과 전혀 다른 말이에요.","**활성화 함수(Activation Function)**를 빼면 **뉴런(Neuron)**은 그냥 선형 계산이에요. 비선형은 f 에서만 생겨요."]}]},{"p":10,"title":"비선형 함수 메뉴","terms":["Activation Function","Sigmoid","tanh","ReLU","GELU","Transformer","Vanishing Gradient","Gradient","Nonlinearity"],"pass1":[{"kind":"say","lines":["**뉴런(Neuron)** 끝의 f 자리에 넣을 **활성화 함수(Activation Function)**의 메뉴판이에요.","옛날부터 쓰던 S자 **시그모이드(Sigmoid)**, 요즘 기본인 **ReLU(렐루)**, **트랜스포머(Transformer)**가 쓰는 **GELU(겔루)**가 있어요."]},{"kind":"figure","head":"두 대표 선수의 모양","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"120\" y=\"24\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">시그모이드<\/text><text x=\"360\" y=\"24\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b1\">ReLU<\/text><line x1=\"20\" y1=\"150\" x2=\"220\" y2=\"150\" class=\"e\"/><line x1=\"120\" y1=\"50\" x2=\"120\" y2=\"240\" class=\"e\"/><text x=\"128\" y=\"66\" font-size=\"14\" text-anchor=\"start\" class=\"tm\">1<\/text><text x=\"128\" y=\"148\" font-size=\"14\" text-anchor=\"start\" class=\"tm\">0<\/text><line x1=\"20\" y1=\"70\" x2=\"220\" y2=\"70\" class=\"e\"/><polyline points=\"20,149 60,147 90,138 105,125 120,110 135,95 150,82 180,73 220,71\" fill=\"none\" class=\"e2\"/><text x=\"120\" y=\"262\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">0과 1 사이로 눌러요<\/text><line x1=\"260\" y1=\"200\" x2=\"460\" y2=\"200\" class=\"e b1\"/><line x1=\"360\" y1=\"50\" x2=\"360\" y2=\"240\" class=\"e b1\"/><polyline points=\"260,200 360,200 450,70\" fill=\"none\" class=\"e2 b1\"/><text x=\"300\" y=\"190\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">음수는 0<\/text><text x=\"300\" y=\"100\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">양수는 그대로<\/text><text x=\"360\" y=\"262\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">max(z, 0)<\/text><\/svg>","caption":"**시그모이드(Sigmoid)**는 0~1 로 눌러 주고, **ReLU(렐루)**는 음수를 0으로 끄고 양수는 그대로 보내요.","builds":2}],"pass2":[{"kind":"compare","head":"슬라이드 영어 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["sigmoid/tanh: classic, squashing","**시그모이드(Sigmoid)**, **하이퍼볼릭 탄젠트(tanh)**: 오래된 S자, 값을 눌러 담아요"],["still used for probabilities and gates","지금도 확률과 게이트(LSTM)에 써요"],["ReLU: max(0, x), cheap, trains fast, the workhorse","**ReLU(렐루)**: 계산이 싸고 학습이 빠른 딥러닝의 일꾼"],["GELU: smooth ReLU, what Transformers use","**GELU(겔루)**: 부드러운 ReLU, **트랜스포머(Transformer)**가 써요"],["ReLU/GELU inside, sigmoid only when you need a probability","안쪽 층은 ReLU/GELU, 확률이 필요할 때만 시그모이드"]]},{"kind":"compare","head":"네 함수 구별하기","cols":["함수","출력 범위","주로 쓰는 곳"],"rows":[["**시그모이드(Sigmoid)**","0 ~ 1","확률, 게이트"],["**하이퍼볼릭 탄젠트(tanh)**","-1 ~ 1","게이트, 실습 N3L p.3 의 h = tanh(z)"],["**ReLU(렐루)**","0 ~ 무한대","안쪽 층의 기본 선택"],["**GELU(겔루)**","대략 -0.17 ~ 무한대 (ReLU 와 비슷)","**트랜스포머(Transformer)**"]]},{"kind":"check","q":"확률처럼 0과 1 사이 값이 필요할 때 쓰는 **활성화 함수(Activation Function)**는?","choices":["**ReLU(렐루)**","**시그모이드(Sigmoid)**","**GELU(겔루)**"],"a":1,"why":"**시그모이드(Sigmoid)**의 출력은 늘 0과 1 사이라 확률이나 게이트에 딱 맞아요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.065,"y":0.4,"w":0.145,"h":0.35,"say":"Logistic('sigmoid'): f(z) = 1/(1+e^(-z)). 0~1 S자 곡선."},{"x":0.21,"y":0.4,"w":0.13,"h":0.35,"say":"tanh: -1~1 S자. **시그모이드(Sigmoid)**와 모양이 비슷해요."},{"x":0.505,"y":0.39,"w":0.14,"h":0.36,"say":"ReLU(Rectified Linear Unit): f(z) = max(z, 0). 꺾인 직선."},{"x":0.66,"y":0.385,"w":0.135,"h":0.365,"say":"Leaky / Parametric ReLU: 음수 쪽에도 작은 기울기(αz)를 남겨요."},{"x":0.8,"y":0.39,"w":0.155,"h":0.36,"say":"GELU(Gaussian Error Linear Unit): 0 근처가 부드러운 ReLU."},{"x":0.23,"y":0.855,"w":0.55,"h":0.045,"say":"'Default advice': 안쪽은 ReLU/GELU, 확률이 필요할 때만 sigmoid."}]},{"kind":"formula","head":"**시그모이드(Sigmoid)**와 **ReLU(렐루)**","tex":"\\sigma(z) = \\frac{1}{1 + e^{-z}}, \\qquad \\mathrm{ReLU}(z) = \\max(z, 0)","parts":[{"sym":"\\sigma(z)","say":"**시그모이드(Sigmoid)**. 늘 0과 1 사이"},{"sym":"e^{-z}","say":"z 가 크면 0에 가까워져서 σ 가 1에 가까워져요"},{"sym":"\\max(z, 0)","say":"z 와 0 중 큰 쪽. 음수면 0, 양수면 z 그대로"},{"sym":"z","say":"**뉴런(Neuron)**의 **가중합(Weighted Sum)** + **편향 항(Bias Term)** 값"}],"whole":"**시그모이드(Sigmoid)**는 눌러 담고, **ReLU(렐루)**는 음수만 꺼요."},{"kind":"steps","head":"손계산: 값 넣어 보기","steps":["ReLU(-2) = 0, ReLU(0) = 0, ReLU(3) = 3","σ(0) = 1/(1+1) = 0.5","σ(4) ≈ 0.98, σ(-4) ≈ 0.02","σ 는 4 에서 이미 1 가까이 붙어서, 더 커져도 거의 안 변해요(기울기 거의 0)","ReLU 는 양수 쪽 기울기가 늘 1이에요"],"answer":"양 끝에서 시그모이드는 평평해지고, ReLU 는 양수 쪽이 계속 기울어 있어요."},{"kind":"prof","when":"3주차 월요일 1교시","lines":["시그모이드는 0에서 1, tanh 는 -1에서 1 사이 값을 가져요. 시그모이드는 확률이나 LSTM 게이트에 써요.","딥러닝에서 가장 중요한 함수 중 하나가 ReLU 예요. 음수면 0으로 끄고 양수면 기울기 1로 그대로 보내요.","시그모이드, tanh 는 양 끝에서 기울기가 거의 0이라 깊이 쌓으면 기울기가 사라지는 문제가 생겨요.","ReLU 를 썼을 때 가장 성능이 좋았고, LLM 이전 대부분의 모델은 ReLU 를 썼어요."]},{"kind":"prof","when":"3주차 월요일 1교시","lines":["ReLU 는 음수에서 기울기가 0이라 계속 꺼져 버리는 현상(dying ReLU)이 있어요.","그래서 음수도 조금 보내 주는 Leaky ReLU, 부드럽게 변하는 GELU 가 나왔어요.","기억할 것: 시그모이드는 확률이나 게이트, ReLU 는 단순하고 효과적인 기본 선택, GELU 는 트랜스포머."]}],"pass4":[{"kind":"check","q":"**시그모이드(Sigmoid)**, **하이퍼볼릭 탄젠트(tanh)**를 깊게 쌓을 때 생기는 문제로 교수님이 말한 것은?","choices":["**기울기 소실(Vanishing Gradient)**","어휘가 너무 커지는 문제","토큰이 잘게 쪼개지는 문제"],"a":0,"why":"양 끝에서 **기울기(Gradient)**가 거의 0이라, 층이 깊으면 **기울기(Gradient)**가 앞쪽까지 잘 안 가요. 이것이 **기울기 소실(Vanishing Gradient)**예요."},{"kind":"check","q":"**ReLU(렐루)**의 약점으로 맞는 것은?","choices":["출력이 늘 0~1 이다","음수 입력에서 기울기가 0이라 뉴런이 꺼진 채 남을 수 있다","계산이 매우 비싸다"],"a":1,"why":"음수 쪽 기울기가 0이라 계속 꺼지는 현상이 있어요. 그래서 Leaky ReLU, GELU 가 나왔어요."},{"kind":"english","head":"외워 쓸 답안 문장","en":"**ReLU(렐루)**는 싸고 **기울기 소실(Vanishing Gradient)**가 적어 기본으로, **시그모이드(Sigmoid)**는 확률과 게이트에, **GELU(겔루)**는 **트랜스포머(Transformer)**에 쓴다.","ko":"ReLU = 기본, 시그모이드 = 확률/게이트, GELU = 트랜스포머.","tip":"교수님이 '기억해야 할 것' 이라고 짚은 세 줄이에요."}]},{"p":11,"title":"비선형성은 선택이 아니다","terms":["Nonlinearity","Matrix","Activation Function","Hyperplane","Decision Boundary","Universal Approximation Theorem","Neural Network"],"pass1":[{"kind":"say","lines":["**활성화 함수(Activation Function)**를 빼고 층만 여러 개 쌓으면 어떻게 될까요?","놀랍게도 층 여러 개가 **행렬(Matrix)** 하나와 똑같아져요. 깊게 쌓은 보람이 없어요.","그래서 **비선형성(Nonlinearity)**은 넣어도 되고 안 넣어도 되는 게 아니라 꼭 넣어야 해요."]},{"kind":"figure","head":"선형층 두 개 = 선형층 하나","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"26\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">활성화 함수 없이 쌓으면<\/text><text x=\"30\" y=\"78\" font-size=\"18\" text-anchor=\"middle\" class=\"tb\">x<\/text><line x1=\"42\" y1=\"72\" x2=\"81.6\" y2=\"72.0\" class=\"e2\"/><polygon points=\"88,72 80.0,68.0 80.0,76.0\" class=\"arrow\"/><rect x=\"90\" y=\"50\" width=\"80\" height=\"44\" rx=\"2\" class=\"box\"/><text x=\"130.0\" y=\"77.6\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">W1<\/text><line x1=\"172\" y1=\"72\" x2=\"211.6\" y2=\"72.0\" class=\"e2\"/><polygon points=\"218,72 210.0,68.0 210.0,76.0\" class=\"arrow\"/><rect x=\"220\" y=\"50\" width=\"80\" height=\"44\" rx=\"2\" class=\"box\"/><text x=\"260.0\" y=\"77.6\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">W2<\/text><line x1=\"302\" y1=\"72\" x2=\"341.6\" y2=\"72.0\" class=\"e2\"/><polygon points=\"348,72 340.0,68.0 340.0,76.0\" class=\"arrow\"/><text x=\"362\" y=\"78\" font-size=\"18\" text-anchor=\"middle\" class=\"tb\">y<\/text><text x=\"240\" y=\"126\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b1\">= 똑같아요 =<\/text><text x=\"30\" y=\"176\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b1\">x<\/text><line x1=\"42\" y1=\"170\" x2=\"121.6\" y2=\"170.0\" class=\"e2 b1\"/><polygon points=\"128,170 120.0,166.0 120.0,174.0\" class=\"arrow b1\"/><rect x=\"130\" y=\"148\" width=\"170\" height=\"44\" rx=\"2\" class=\"box2 b1\"/><text x=\"215.0\" y=\"175.25\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">W2W1 (행렬 하나)<\/text><line x1=\"302\" y1=\"170\" x2=\"341.6\" y2=\"170.0\" class=\"e2 b1\"/><polygon points=\"348,170 340.0,166.0 340.0,174.0\" class=\"arrow b1\"/><text x=\"362\" y=\"176\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b1\">y<\/text><text x=\"240\" y=\"236\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">사이에 f 를 끼우면 한 행렬로 못 합쳐요<\/text><text x=\"240\" y=\"260\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">선형 섞기 → 휘기 → 선형 섞기 → 휘기<\/text><\/svg>","caption":"W1, W2 를 이어 곱하면 W2W1 이라는 **행렬(Matrix)** 하나가 돼요. 사이에 f 를 끼워야 합쳐지지 않아요.","builds":2}],"pass2":[{"kind":"compare","head":"슬라이드 영어 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["Why Nonlinearity Is Not Optional","왜 **비선형성(Nonlinearity)**은 선택이 아닌가"],["stacked linear layers collapse into one affine map","쌓은 선형층은 변환 하나로 무너져 합쳐져요"],["depth buys nothing","깊게 쌓아도 얻는 게 없어요"],["linear mix → bend → linear mix → bend","선형으로 섞고 → 휘고 → 섞고 → 휘기"],["No f, no deep learning","f 가 없으면 딥러닝도 없어요"]]},{"kind":"points","head":"이 쪽 용어 하나하나","items":["**행렬(Matrix)**: 숫자를 표 모양으로 늘어놓은 것. 선형층 하나가 **행렬(Matrix)** 하나예요.","**비선형성(Nonlinearity)**: 곧은 변환 사이에서 공간을 휘게 하는 성질. f 가 만들어요.","**보편 근사 정리(Universal Approximation Theorem)**: 은닉 뉴런이 충분하면 웬만한 함수는 다 흉내 낼 수 있다는 정리"]},{"kind":"steps","head":"오른쪽 그림(With nonlinearity) 흐름","steps":["Input space: 곧은 격자(입력 공간)","선형층이 공간을 섞고, 돌리고, 늘이고, 줄여요","f 가 격자를 휘어요(After nonlinearity: grid is bent)","휜 공간에서는 동그란 **결정 경계(Decision Boundary)**도 만들 수 있어요"],"answer":"섞기와 휘기를 반복할수록 더 복잡한 경계를 표현해요."},{"kind":"check","q":"**활성화 함수(Activation Function)** 없이 선형층 10개를 쌓으면?","choices":["선형층 1개와 표현력이 같다","10배 강해진다","곡선 경계를 그릴 수 있다"],"a":0,"why":"모두 곱하면 **행렬(Matrix)** 하나가 돼서 선형층 1개와 같아요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.08,"y":0.2,"w":0.36,"h":0.075,"say":"'Without nonlinearity': 쌓은 선형층이 변환 하나로 합쳐져요."},{"x":0.15,"y":0.42,"w":0.21,"h":0.1,"say":"W₂(W₁x) = (W₂W₁)x, 'depth buys nothing': 깊이가 소용없어요."},{"x":0.11,"y":0.55,"w":0.33,"h":0.24,"say":"왼쪽 아래: 선형층을 여러 개 써도 결국 곧은 경계 하나."},{"x":0.53,"y":0.405,"w":0.28,"h":0.1,"say":"W₂ f(W₁x + b₁) + b₂: 가운데 f 가 끼어 있어요. 선형 섞기 → 휘기."},{"x":0.485,"y":0.54,"w":0.38,"h":0.26,"say":"격자가 휘고(After nonlinearity), 동그란 결정 경계가 생겨요."},{"x":0.21,"y":0.815,"w":0.59,"h":0.045,"say":"'Universal approximation Theorem': **보편 근사 정리(Universal Approximation Theorem)**. (슬라이드의 'funciton' 은 function 오타)"}]},{"kind":"formula","head":"층이 합쳐지는 식","tex":"W_2(W_1 x) = (W_2 W_1)\\,x = W' x","parts":[{"sym":"W_1, W_2","say":"선형층 두 개의 가중치 행렬"},{"sym":"W_2 W_1","say":"행렬끼리 먼저 곱할 수 있어요(결합 법칙)"},{"sym":"W'","say":"곱한 결과, 새 **행렬(Matrix)** 하나"},{"sym":"x","say":"입력 벡터"}],"whole":"f 없이 쌓은 층은 **행렬(Matrix)** 하나 W' 로 바꿔 쓸 수 있어요. 층 수가 의미 없어져요."},{"kind":"steps","head":"손계산: 작은 행렬로 확인하기","steps":["W1 = [[1, 2], [0, 1]], W2 = [[1, 0], [1, 1]], x = [1, 1]","한 층씩: W1x = [3, 1], 그다음 W2[3, 1] = [3, 4]","먼저 합치기: W2W1 = [[1, 2], [1, 3]], (W2W1)x = [3, 4]","두 방법의 답이 똑같아요 → 두 층 = 행렬 하나","사이에 ReLU: V1 = [[1, -2], [0, 1]] 이면 V1x = [-1, 1] → ReLU → [0, 1] → W2 → [0, 1]","ReLU 없이 합치면 (W2V1)x = [-1, 0]. 답이 달라져서 하나로 못 합쳐요"],"answer":"f 가 없으면 층이 합쳐지고, f 를 끼우면 합쳐지지 않아요."},{"kind":"prof","when":"3주차 월요일 1교시","lines":["w1 과 w2 를 먼저 곱하든 따로 곱하든, 결국 w1 과 w2 를 곱한 하나의 선형 변환이에요.","레이어를 2개 쌓았는데 큰 레이어 하나를 쌓은 것과 같은 결과가 나와요. 논리니어티가 없으면 깊게 쌓는 의미가 없어요.","직관적으로 선형층은 공간을 섞고 회전하고 늘리고 줄이고, 비선형은 그 공간을 접거나 구부려요."]},{"kind":"prof","when":"3주차 월요일 1교시","lines":["하이퍼플레인은 n차원이면 n-1차원이에요. 2차원이면 선, 3차원이면 면이에요.","2차원에서 선으로 못 가르던 점들도, 높이를 더해 빨간 점은 높이, 파란 점은 낮게 보내면 면 하나로 갈라요.","중간에 비선형을 끼는 게 이렇게 차원을 올리거나, 2차원에서 경계를 휘게 해 주는 거예요."]},{"kind":"bg","src":"기초 다지기 3단원, 9단원","lines":["행렬 곱은 앞 행렬의 행과 뒤 벡터(열)를 곱해 더하는 계산이에요.","9단원: 왜 비선형이 필요한지, **뉴런(Neuron)**과 층 이야기가 있어요."]}],"pass4":[{"kind":"check","q":"W₂(W₁x) = (W₂W₁)x 가 말해 주는 것은?","choices":["f 없이 쌓은 선형층은 행렬 하나와 같다","행렬 곱은 순서를 바꿔도 된다","층이 많을수록 늘 좋다"],"a":0,"why":"곱을 묶는 방법(결합)이 자유로워서 층 둘이 행렬 하나로 합쳐져요. 곱하는 순서(W₂W₁ ≠ W₁W₂)를 바꿔도 된다는 뜻은 아니에요."},{"kind":"english","head":"외워 쓸 답안 문장","en":"**활성화 함수(Activation Function)** 없이 선형층을 쌓으면 W₂(W₁x) = (W₂W₁)x 처럼 **행렬(Matrix)** 하나로 합쳐져 깊이의 이점이 없으므로 층 사이에 **비선형성(Nonlinearity)**이 반드시 필요하다.","ko":"No f, no deep learning.","tip":"'합쳐진다(collapse)' 한 단어로 기억해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드 오른쪽 식에는 b 가 있어요. b 가 있어도 f 가 없으면 여전히 변환 하나(affine)로 합쳐져요.","**보편 근사 정리(Universal Approximation Theorem)**은 '뉴런이 충분히 많으면' 이라는 조건이 붙어요. 아무 신경망이나 다 된다는 뜻이 아니에요."]}]},{"p":12,"title":"다층 퍼셉트론(MLP)","terms":["Multi-Layer Perceptron (MLP)","Hidden Layer","Parameter","Softmax","Named Entity Recognition (NER)","Matrix","Neuron","Weight","Bias Term"],"pass1":[{"kind":"say","lines":["**뉴런(Neuron)**을 여러 개 모아 한 층을 만들고, 그 층을 여러 겹 쌓으면 **MLP(다층 퍼셉트론)**이에요.","가운데 층은 밖에서 안 보여서 **은닉층(Hidden Layer)**이라고 불러요."]},{"kind":"figure","head":"**MLP(다층 퍼셉트론)**의 모양","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><line x1=\"74\" y1=\"60\" x2=\"166\" y2=\"60\" class=\"e b1\"/><line x1=\"74\" y1=\"60\" x2=\"166\" y2=\"106\" class=\"e b1\"/><line x1=\"74\" y1=\"60\" x2=\"166\" y2=\"152\" class=\"e b1\"/><line x1=\"74\" y1=\"60\" x2=\"166\" y2=\"198\" class=\"e b1\"/><line x1=\"74\" y1=\"106\" x2=\"166\" y2=\"60\" class=\"e b1\"/><line x1=\"74\" y1=\"106\" x2=\"166\" y2=\"106\" class=\"e b1\"/><line x1=\"74\" y1=\"106\" x2=\"166\" y2=\"152\" class=\"e b1\"/><line x1=\"74\" y1=\"106\" x2=\"166\" y2=\"198\" class=\"e b1\"/><line x1=\"74\" y1=\"152\" x2=\"166\" y2=\"60\" class=\"e b1\"/><line x1=\"74\" y1=\"152\" x2=\"166\" y2=\"106\" class=\"e b1\"/><line x1=\"74\" y1=\"152\" x2=\"166\" y2=\"152\" class=\"e b1\"/><line x1=\"74\" y1=\"152\" x2=\"166\" y2=\"198\" class=\"e b1\"/><line x1=\"74\" y1=\"198\" x2=\"166\" y2=\"60\" class=\"e b1\"/><line x1=\"74\" y1=\"198\" x2=\"166\" y2=\"106\" class=\"e b1\"/><line x1=\"74\" y1=\"198\" x2=\"166\" y2=\"152\" class=\"e b1\"/><line x1=\"74\" y1=\"198\" x2=\"166\" y2=\"198\" class=\"e b1\"/><line x1=\"194\" y1=\"60\" x2=\"286\" y2=\"60\" class=\"e b2\"/><line x1=\"194\" y1=\"60\" x2=\"286\" y2=\"106\" class=\"e b2\"/><line x1=\"194\" y1=\"60\" x2=\"286\" y2=\"152\" class=\"e b2\"/><line x1=\"194\" y1=\"60\" x2=\"286\" y2=\"198\" class=\"e b2\"/><line x1=\"194\" y1=\"106\" x2=\"286\" y2=\"60\" class=\"e b2\"/><line x1=\"194\" y1=\"106\" x2=\"286\" y2=\"106\" class=\"e b2\"/><line x1=\"194\" y1=\"106\" x2=\"286\" y2=\"152\" class=\"e b2\"/><line x1=\"194\" y1=\"106\" x2=\"286\" y2=\"198\" class=\"e b2\"/><line x1=\"194\" y1=\"152\" x2=\"286\" y2=\"60\" class=\"e b2\"/><line x1=\"194\" y1=\"152\" x2=\"286\" y2=\"106\" class=\"e b2\"/><line x1=\"194\" y1=\"152\" x2=\"286\" y2=\"152\" class=\"e b2\"/><line x1=\"194\" y1=\"152\" x2=\"286\" y2=\"198\" class=\"e b2\"/><line x1=\"194\" y1=\"198\" x2=\"286\" y2=\"60\" class=\"e b2\"/><line x1=\"194\" y1=\"198\" x2=\"286\" y2=\"106\" class=\"e b2\"/><line x1=\"194\" y1=\"198\" x2=\"286\" y2=\"152\" class=\"e b2\"/><line x1=\"194\" y1=\"198\" x2=\"286\" y2=\"198\" class=\"e b2\"/><line x1=\"314\" y1=\"60\" x2=\"406\" y2=\"83\" class=\"e b3\"/><line x1=\"314\" y1=\"60\" x2=\"406\" y2=\"129\" class=\"e b3\"/><line x1=\"314\" y1=\"60\" x2=\"406\" y2=\"175\" class=\"e b3\"/><line x1=\"314\" y1=\"106\" x2=\"406\" y2=\"83\" class=\"e b3\"/><line x1=\"314\" y1=\"106\" x2=\"406\" y2=\"129\" class=\"e b3\"/><line x1=\"314\" y1=\"106\" x2=\"406\" y2=\"175\" class=\"e b3\"/><line x1=\"314\" y1=\"152\" x2=\"406\" y2=\"83\" class=\"e b3\"/><line x1=\"314\" y1=\"152\" x2=\"406\" y2=\"129\" class=\"e b3\"/><line x1=\"314\" y1=\"152\" x2=\"406\" y2=\"175\" class=\"e b3\"/><line x1=\"314\" y1=\"198\" x2=\"406\" y2=\"83\" class=\"e b3\"/><line x1=\"314\" y1=\"198\" x2=\"406\" y2=\"129\" class=\"e b3\"/><line x1=\"314\" y1=\"198\" x2=\"406\" y2=\"175\" class=\"e b3\"/><circle cx=\"60\" cy=\"60\" r=\"14\" class=\"n\"/><circle cx=\"60\" cy=\"106\" r=\"14\" class=\"n\"/><circle cx=\"60\" cy=\"152\" r=\"14\" class=\"n\"/><circle cx=\"60\" cy=\"198\" r=\"14\" class=\"n\"/><circle cx=\"180\" cy=\"60\" r=\"14\" class=\"n4 b1\"/><circle cx=\"180\" cy=\"106\" r=\"14\" class=\"n4 b1\"/><circle cx=\"180\" cy=\"152\" r=\"14\" class=\"n4 b1\"/><circle cx=\"180\" cy=\"198\" r=\"14\" class=\"n4 b1\"/><circle cx=\"300\" cy=\"60\" r=\"14\" class=\"n4 b2\"/><circle cx=\"300\" cy=\"106\" r=\"14\" class=\"n4 b2\"/><circle cx=\"300\" cy=\"152\" r=\"14\" class=\"n4 b2\"/><circle cx=\"300\" cy=\"198\" r=\"14\" class=\"n4 b2\"/><circle cx=\"420\" cy=\"83\" r=\"14\" class=\"n2 b3\"/><circle cx=\"420\" cy=\"129\" r=\"14\" class=\"n2 b3\"/><circle cx=\"420\" cy=\"175\" r=\"14\" class=\"n2 b3\"/><text x=\"60\" y=\"250\" font-size=\"14\" text-anchor=\"middle\" class=\"tb\">입력 x<\/text><text x=\"180\" y=\"250\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">은닉 h(1)<\/text><text x=\"300\" y=\"250\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b2\">은닉 h(2)<\/text><text x=\"420\" y=\"250\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b3\">출력 ŷ<\/text><text x=\"120\" y=\"34\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">W(1), b(1)<\/text><text x=\"240\" y=\"34\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">W(2), b(2)<\/text><text x=\"360\" y=\"34\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">U<\/text><\/svg>","caption":"입력 x → **은닉층(Hidden Layer)** h(1) → **은닉층(Hidden Layer)** h(2) → 출력 ŷ. 선마다 **가중치(Weight)**가 하나씩 있어요.","builds":3}],"pass2":[{"kind":"compare","head":"슬라이드 영어 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["Stack neuron layers","**뉴런(Neuron)** 층을 쌓아요"],["input x / hidden h / output ŷ","입력 / **은닉층(Hidden Layer)** / 출력"],["word vectors → MLP → P(location), that simple","단어 벡터 → **MLP(다층 퍼셉트론)** → 장소일 확률, 그렇게 간단해요"],["How can we determine W & b? Training network!","W 와 b 는 어떻게 정하나요? 신경망을 학습시켜서요!"]]},{"kind":"points","head":"이 쪽 용어 하나하나","items":["**MLP(다층 퍼셉트론)**: **뉴런(Neuron)** 층을 여러 겹 쌓은 기본 신경망","**은닉층(Hidden Layer)**: 입력과 출력 사이의 숨은 층. 슬라이드에 두 개(h(1), h(2))","**파라미터(Parameter)**: 학습으로 정하는 숫자들. 여기서는 W(1), b(1), W(2), b(2), U"]},{"kind":"steps","head":"**MLP(다층 퍼셉트론)** 순전파 순서","steps":["h(1) = f(W(1)x + b(1)): 첫 **은닉층(Hidden Layer)**","h(2) = f(W(2)h(1) + b(2)): 둘째 **은닉층(Hidden Layer)**","ŷ = softmax(U h(2)): 출력 확률","**NER(개체명 인식)**이면 x 는 창 벡터, ŷ 에서 LOCATION 확률을 읽어요"],"answer":"선형 변환 → f → 선형 변환 → f → softmax"},{"kind":"check","q":"**MLP(다층 퍼셉트론)**에서 **은닉층(Hidden Layer)**이라는 이름이 붙은 까닭은?","choices":["숫자가 비밀번호라서","입력과 출력 사이에 있어 밖에서 안 보여서","학습하지 않아서"],"a":1,"why":"밖에서는 입력과 출력만 보여요. 가운데 계산은 숨어 있어서 hidden 이에요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.22,"y":0.195,"w":0.52,"h":0.05,"say":"맨 위 식: 층마다 f(Wx + b) 꼴을 반복하고, 마지막에 softmax(U h(2))."},{"x":0.205,"y":0.36,"w":0.06,"h":0.39,"say":"input x: 파란 입력 x₁ ... x₄"},{"x":0.385,"y":0.36,"w":0.06,"h":0.39,"say":"hidden h(1): 첫 **은닉층(Hidden Layer)**. 위에 W(1), b(1)"},{"x":0.558,"y":0.36,"w":0.06,"h":0.39,"say":"hidden h(2): 둘째 **은닉층(Hidden Layer)**. 위에 W(2), b(2)"},{"x":0.735,"y":0.37,"w":0.06,"h":0.38,"say":"output ŷ: 출력 3개. 위에 U"},{"x":0.245,"y":0.86,"w":0.51,"h":0.075,"say":"NER 창 분류기 = 단어 벡터 → MLP → P(location). W, b 는 학습으로!"}]},{"kind":"formula","head":"**MLP(다층 퍼셉트론)**의 식","tex":"h^{(1)} = f(W^{(1)}x + b^{(1)}),\\; h^{(2)} = f(W^{(2)}h^{(1)} + b^{(2)}),\\; \\hat{y} = \\mathrm{softmax}(U h^{(2)})","parts":[{"sym":"W^{(1)}, b^{(1)}","say":"첫 층의 가중치 **행렬(Matrix)**와 **편향 항(Bias Term)**"},{"sym":"f","say":"**활성화 함수(Activation Function)**(예: ReLU)"},{"sym":"h^{(1)}, h^{(2)}","say":"**은닉층(Hidden Layer)**의 출력 벡터"},{"sym":"U","say":"마지막 점수 행렬(여기서는 b 없음)"},{"sym":"\\hat{y}","say":"클래스별 확률"}],"whole":"뉴런 계산 f(Wx + b) 를 층마다 되풀이하고 끝에 **소프트맥스(Softmax)**를 붙여요."},{"kind":"steps","head":"손계산: 그림 속 파라미터 세기","given":"슬라이드 그림: 입력 4, 은닉 4, 은닉 4, 출력 3","steps":["입력 4 → 은닉 4: W(1) 은 4×4 = 16개, b(1) 4개","은닉 4 → 은닉 4: W(2) 16개, b(2) 4개","은닉 4 → 출력 3: U 는 3×4 = 12개","모두 더하면 16 + 4 + 16 + 4 + 12"],"answer":"파라미터 52개"},{"kind":"prof","when":"3주차 월요일 1교시","lines":["MLP 는 w 를 곱하고 b 를 더하고 활성화 f 를 통과시키는 뉴런 계산 하나를 계속 반복하면 돼요.","손글씨 0~9 를 분류한다면 마지막 층의 클래스 수는 10개예요.","중요한 건 W 와 b 예요. 이걸 정하는 게 학습(트레이닝) 과정이에요.","W 와 b 는 처음에 랜덤으로 시작해서 3을 넣어도 7이 나올 수 있지만, 학습으로 3이 나오게 맞춰요."]},{"kind":"points","head":"실습과 이어져요 (N3L p.3)","items":["실습에서는 N3L p.3 에서 이걸 코드로 짜고 x, W, b, z, h, s 의 shape 을 찍어 봐요.","x: (5,) 입력 5개 / W: (3, 5) 은닉 뉴런 3개, 입력 5개 / b: (3,)","z = W @ x + b: (3,) / h = tanh(z): (3,) / s = u @ h: 숫자 하나(스칼라)","W 의 shape 은 (출력 뉴런 수, 입력 수)예요. 이 규칙이 p.15 문제 2의 열쇠예요."]},{"kind":"bg","src":"기초 다지기 3단원","lines":["(3,5) 행렬 @ 길이 5 벡터 → 길이 3 벡터. 앞 행렬의 열 수와 벡터 길이가 같아야 곱할 수 있어요.","기초 다지기 10단원에 PyTorch 의 @, shape 읽는 법이 있어요."]}],"pass4":[{"kind":"check","q":"W(1) 의 shape 이 (3, 5) 일 때, 입력 x 와 첫 은닉층 h(1) 의 길이는?","choices":["x 3, h(1) 5","x 5, h(1) 3","x 15, h(1) 1"],"a":1,"why":"W(1)x 에서 W 의 열 수 5 = 입력 길이, 행 수 3 = 은닉 뉴런 수예요."},{"kind":"english","head":"외워 쓸 답안 문장","en":"**MLP(다층 퍼셉트론)**은 h = f(Wx + b) 를 층마다 반복하고 마지막에 **소프트맥스(Softmax)**로 클래스 확률을 내며, W 와 b 는 학습으로 정해지는 **파라미터(Parameter)**다.","ko":"층 = f(Wx + b), 끝 = softmax, W 와 b 는 학습."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**MLP(다층 퍼셉트론)**의 줄임말을 **NLP(자연어처리)**와 헷갈리지 않아요. 녹음 받아쓰기에도 'NLP' 로 잘못 적혀 있어요.","슬라이드 식에서 마지막 U 에는 b 가 없어요. 그림 위에도 'U' 만 적혀 있어요."]}]},{"p":13,"title":"글을 위한 CNN (1): 아이디어","terms":["Convolutional Neural Network (CNN)","Convolution Filter","Feature Map","Max-pooling","n-gram","Word Vector","Window"],"pass1":[{"kind":"say","lines":["또 하나의 신경망, **CNN(합성곱 신경망)**이에요.","작은 **합성곱 필터(Convolution Filter)**가 문장 위를 한 칸씩 미끄러지며 짧은 패턴을 찾아요.","폭 3짜리 필터라면 연속된 세 단어를 한 번에 봐요."]},{"kind":"figure","head":"필터가 미끄러지며 값을 내요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"62\" y=\"52\" font-size=\"14\" text-anchor=\"end\" class=\"t\">this<\/text><rect x=\"72\" y=\"34\" width=\"110\" height=\"28\" rx=\"2\" class=\"n\"/><text x=\"127\" y=\"53\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">0<\/text><text x=\"62\" y=\"88\" font-size=\"14\" text-anchor=\"end\" class=\"t\">movie<\/text><rect x=\"72\" y=\"70\" width=\"110\" height=\"28\" rx=\"2\" class=\"n\"/><text x=\"127\" y=\"89\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">1<\/text><text x=\"62\" y=\"124\" font-size=\"14\" text-anchor=\"end\" class=\"t\">was<\/text><rect x=\"72\" y=\"106\" width=\"110\" height=\"28\" rx=\"2\" class=\"n\"/><text x=\"127\" y=\"125\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">0<\/text><text x=\"62\" y=\"160\" font-size=\"14\" text-anchor=\"end\" class=\"t\">really<\/text><rect x=\"72\" y=\"142\" width=\"110\" height=\"28\" rx=\"2\" class=\"n\"/><text x=\"127\" y=\"161\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">2<\/text><text x=\"62\" y=\"196\" font-size=\"14\" text-anchor=\"end\" class=\"t\">great<\/text><rect x=\"72\" y=\"178\" width=\"110\" height=\"28\" rx=\"2\" class=\"n\"/><text x=\"127\" y=\"197\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">3<\/text><text x=\"62\" y=\"232\" font-size=\"14\" text-anchor=\"end\" class=\"t\">fun<\/text><rect x=\"72\" y=\"214\" width=\"110\" height=\"28\" rx=\"2\" class=\"n\"/><text x=\"127\" y=\"233\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">-1<\/text><rect x=\"66\" y=\"30\" width=\"122\" height=\"108\" rx=\"2\" class=\"hl b1\"/><text x=\"198\" y=\"88\" font-size=\"14\" text-anchor=\"start\" class=\"tb b1\">필터 폭 3<\/text><line x1=\"190\" y1=\"104\" x2=\"273.6\" y2=\"104.0\" class=\"e2 b2\"/><polygon points=\"280,104 272.0,100.0 272.0,108.0\" class=\"arrow b2\"/><rect x=\"290\" y=\"36\" width=\"60\" height=\"32\" rx=\"2\" class=\"box b2\"/><text x=\"320.0\" y=\"57.25\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">1<\/text><rect x=\"290\" y=\"76\" width=\"60\" height=\"32\" rx=\"2\" class=\"box b2\"/><text x=\"320.0\" y=\"97.25\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">3<\/text><rect x=\"290\" y=\"116\" width=\"60\" height=\"32\" rx=\"2\" class=\"box2 b2\"/><text x=\"320.0\" y=\"137.25\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">5<\/text><rect x=\"290\" y=\"156\" width=\"60\" height=\"32\" rx=\"2\" class=\"box b2\"/><text x=\"320.0\" y=\"177.25\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">4<\/text><text x=\"320\" y=\"216\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b2\">특징 맵<\/text><line x1=\"354\" y1=\"132\" x2=\"393.6\" y2=\"132.0\" class=\"e2 b3\"/><polygon points=\"400,132 392.0,128.0 392.0,136.0\" class=\"arrow b3\"/><rect x=\"404\" y=\"112\" width=\"62\" height=\"40\" rx=\"2\" class=\"box2 b3\"/><text x=\"435.0\" y=\"138.3\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b3\">5<\/text><text x=\"435\" y=\"176\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b3\">최대 풀링<\/text><text x=\"240\" y=\"262\" font-size=\"13\" text-anchor=\"middle\" class=\"tm\">단어마다 숫자 하나로 줄인 장난감이에요 (실제는 벡터)<\/text><\/svg>","caption":"창마다 값 하나 → **특징 맵(Feature Map)** → 가장 큰 값만 남기기(**최대 풀링(Max-pooling)**).","builds":3}],"pass2":[{"kind":"compare","head":"슬라이드 영어 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["A convolution filter = a small pattern detector","**합성곱 필터(Convolution Filter)** = 작은 패턴 탐지기"],["slides along the sentence","문장을 따라 미끄러져요"],["feature map (one value per window)","**특징 맵(Feature Map)**: 창마다 값 하나"],["strongest n-gram signal in the sentence","문장 안에서 가장 센 **n-gram(엔그램)** 신호"],["A filter of width 3 is a learned trigram detector","폭 3 필터 = 학습된 세 단어(trigram) 탐지기"]]},{"kind":"points","head":"이 쪽 용어 하나하나","items":["**CNN(합성곱 신경망)**: **합성곱 필터(Convolution Filter)**를 미끄러뜨려 부분 패턴을 찾는 신경망","**합성곱 필터(Convolution Filter)**: 폭(단어 수) × 단어 벡터 차원 크기의 숫자 판. 창과 곱해 값 하나를 내요.","**특징 맵(Feature Map)**: 창마다 나온 값을 줄 세운 것","**n-gram(엔그램)**: 붙어 있는 n 단어. 폭 3이면 trigram, 폭 2면 bigram"]},{"kind":"steps","head":"필터가 도는 순서","steps":["this movie was → 값 하나","한 칸 내려 movie was really → 값 하나","was really great → 값 하나 (가장 큼)","이렇게 모은 값들이 **특징 맵(Feature Map)**","**최대 풀링(Max-pooling)**: 가장 큰 값 하나만 남겨요"],"answer":"창마다 값 → 특징 맵 → 최댓값"},{"kind":"check","q":"폭 3짜리 **합성곱 필터(Convolution Filter)**가 찾는 것은?","choices":["문장 전체의 길이","연속된 세 단어의 패턴(trigram)","단어 하나의 철자"],"a":1,"why":"폭 3이면 붙어 있는 세 단어를 한 번에 봐요. 그래서 학습된 trigram(**n-gram(엔그램)**) 탐지기예요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.08,"y":0.2,"w":0.53,"h":0.04,"say":"'A convolution filter = a small pattern detector that slides along the sentence'."},{"x":0.1,"y":0.33,"w":0.08,"h":0.4,"say":"왼쪽: this ... fun 여섯 단어. 줄마다 **단어 벡터(Word Vector)**(그림은 d = 4)."},{"x":0.18,"y":0.45,"w":0.29,"h":0.17,"say":"빨간 점선: 폭 3 필터가 movie, was, really 세 줄을 덮고 있어요."},{"x":0.588,"y":0.4,"w":0.07,"h":0.32,"say":"feature map: 창마다 값 하나. 진한 칸이 가장 센 반응."},{"x":0.762,"y":0.5,"w":0.105,"h":0.215,"say":"max-pool: 가장 센 n-gram 신호 하나만 남겨요."},{"x":0.695,"y":0.18,"w":0.285,"h":0.24,"say":"Yoon Kim(2014) 'Convolutional Neural Networks for Sentence Classification'. 인용 22357회."}]},{"kind":"steps","head":"손계산: 필터 한 개 돌려 보기","given":"실제로는 단어마다 벡터이고 필터도 3 × d 숫자 판이에요. 계산 모양만 본 장난감이에요.","steps":["단어마다 숫자 하나로 줄여요: this 0, movie 1, was 0, really 2, great 3, fun -1","필터 [1, 1, 1] (세 값을 더하기)","this movie was: 0+1+0 = 1 / movie was really: 1+0+2 = 3","was really great: 0+2+3 = 5 / really great fun: 2+3-1 = 4","특징 맵 [1, 3, 5, 4], 최대 풀링 → 5"],"answer":"가장 센 곳은 'was really great' (값 5)"},{"kind":"prof","when":"3주차 월요일 1교시","lines":["컨볼루션은 정해진 필터 모양 하나가 움직이면서 값들을 얻어내는 거예요.","윈도우 3짜리면 세 단어에 곱해서 값 하나, 한 칸 내려서 또 하나, 이렇게 진행돼요.","같은 필터를 문장 전체에 반복해서 재활용한다는 게 특징이에요.","텍스트 CNN 은 한국인 Yoon Kim 의 논문이고, 교수님이 존경하는 대작이라고 소개했어요."]}],"pass4":[{"kind":"check","q":"**CNN(합성곱 신경망)**에서 같은 **합성곱 필터(Convolution Filter)**를 문장의 모든 위치에 쓰는 것에 대한 설명으로 맞는 것은?","choices":["위치마다 다른 필터를 새로 만든다","한 필터를 모든 창에 다시 써서 같은 패턴을 어디서든 찾는다","필터는 한 위치에서만 쓴다"],"a":1,"why":"같은 필터를 재활용해요. 그래서 같은 패턴이 문장 어디에 있든 똑같이 반응해요."},{"kind":"english","head":"외워 쓸 답안 문장","en":"글에 쓰는 **CNN(합성곱 신경망)**은 폭 k 의 **합성곱 필터(Convolution Filter)**를 문장 위로 미끄러뜨려 창마다 값을 내 **특징 맵(Feature Map)**을 만들며, 폭 3 필터는 학습된 trigram 탐지기다.","ko":"필터 → 특징 맵 → 최대 풀링."}]},{"p":14,"title":"글을 위한 CNN (2): 왜, 어디에","terms":["Max-pooling","Feature Map","Convolution Filter","n-gram","Classification","Convolutional Neural Network (CNN)","Recurrent Neural Network (RNN)"],"pass1":[{"kind":"say","lines":["**최대 풀링(Max-pooling)**은 '이 패턴이 문장 어디에서든 나왔나?' 만 물어요.","그래서 **CNN(합성곱 신경망)**은 빠르고 **분류(Classification)**에 강하지만, 멀리 떨어진 단어 사이 관계는 못 봐요.","그 약점을 채울 게 Part 4 의 **RNN(순환 신경망)**이에요."]},{"kind":"figure","head":"어디서 나왔든 결과는 같아요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"20\" y=\"30\" font-size=\"14\" text-anchor=\"start\" class=\"tb\">문장 앞에 패턴이 있을 때<\/text><rect x=\"40\" y=\"44\" width=\"52\" height=\"34\" rx=\"2\" class=\"box2\"/><text x=\"66.0\" y=\"66.25\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">5<\/text><rect x=\"100\" y=\"44\" width=\"52\" height=\"34\" rx=\"2\" class=\"box\"/><text x=\"126.0\" y=\"66.25\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">1<\/text><rect x=\"160\" y=\"44\" width=\"52\" height=\"34\" rx=\"2\" class=\"box\"/><text x=\"186.0\" y=\"66.25\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">0<\/text><rect x=\"220\" y=\"44\" width=\"52\" height=\"34\" rx=\"2\" class=\"box\"/><text x=\"246.0\" y=\"66.25\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">0<\/text><line x1=\"290\" y1=\"61\" x2=\"343.6\" y2=\"61.0\" class=\"e2\"/><polygon points=\"350,61 342.0,57.0 342.0,65.0\" class=\"arrow\"/><rect x=\"356\" y=\"44\" width=\"60\" height=\"34\" rx=\"2\" class=\"box2\"/><text x=\"386.0\" y=\"66.6\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">5<\/text><text x=\"20\" y=\"132\" font-size=\"14\" text-anchor=\"start\" class=\"tb b1\">문장 뒤에 패턴이 있을 때<\/text><rect x=\"40\" y=\"146\" width=\"52\" height=\"34\" rx=\"2\" class=\"box b1\"/><text x=\"66.0\" y=\"168.25\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">0<\/text><rect x=\"100\" y=\"146\" width=\"52\" height=\"34\" rx=\"2\" class=\"box b1\"/><text x=\"126.0\" y=\"168.25\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">0<\/text><rect x=\"160\" y=\"146\" width=\"52\" height=\"34\" rx=\"2\" class=\"box b1\"/><text x=\"186.0\" y=\"168.25\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">1<\/text><rect x=\"220\" y=\"146\" width=\"52\" height=\"34\" rx=\"2\" class=\"box2 b1\"/><text x=\"246.0\" y=\"168.25\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">5<\/text><line x1=\"290\" y1=\"163\" x2=\"343.6\" y2=\"163.0\" class=\"e2 b1\"/><polygon points=\"350,163 342.0,159.0 342.0,167.0\" class=\"arrow b1\"/><rect x=\"356\" y=\"146\" width=\"60\" height=\"34\" rx=\"2\" class=\"box2 b1\"/><text x=\"386.0\" y=\"168.6\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b1\">5<\/text><text x=\"240\" y=\"236\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b2\">최대 풀링 결과가 똑같이 5: 어디서 나왔는지는 버려요<\/text><text x=\"240\" y=\"260\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">'어디서든 나왔나?' 만 남아요<\/text><\/svg>","caption":"패턴이 앞에 있든 뒤에 있든 **최대 풀링(Max-pooling)** 결과는 5로 같아요.","builds":2}],"pass2":[{"kind":"compare","head":"슬라이드 영어 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["did this pattern appear ANYWHERE?","이 패턴이 어디에서든 나왔나?"],["a bank of learned n-gram detectors","학습된 **n-gram(엔그램)** 탐지기 묶음"],["fast, position-independent, great for classification","빠르고, 위치에 상관없고, **분류(Classification)**에 좋아요"],["local view only, no long-range order","가까운 곳만 봐요, 먼 순서는 못 봐요"],["CNN = parallel n-gram detectors, RNN = a reader with memory","**CNN(합성곱 신경망)** = 병렬 n-gram 탐지기, **RNN(순환 신경망)** = 기억을 가진 독자"]]},{"kind":"compare","head":"**CNN(합성곱 신경망)**의 장점과 한계","cols":["","내용"],"rows":[["장점","모든 창을 동시에 계산해서 빨라요(병렬)"],["장점","위치와 상관없이 패턴을 잡아요(**최대 풀링(Max-pooling)** 덕분)"],["장점","감정, 주제 같은 **분류(Classification)**에 좋아요"],["한계","창 안(가까운 곳)만 봐서 먼 단어 사이 순서와 관계를 못 봐요"]]},{"kind":"check","q":"**CNN(합성곱 신경망)**의 한계로 슬라이드가 든 것은?","choices":["계산이 너무 느리다","가까운 곳만 봐서 먼 거리 순서를 못 잡는다","**분류(Classification)**에 쓸 수 없다"],"a":1,"why":"'local view only, no long-range order'. 그래서 순서가 중요한 일에는 **RNN(순환 신경망)**(recurrence)을 쓰려고 해요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.06,"y":0.505,"w":0.65,"h":0.045,"say":"'Max-pooling: keep the strongest response': 가장 센 반응만 남겨요."},{"x":0.06,"y":0.56,"w":0.63,"h":0.045,"say":"'filters of widths 2-5': 폭 2~5 필터 여러 개 = **n-gram(엔그램)** 탐지기 묶음 → 그 위에 분류기."},{"x":0.06,"y":0.615,"w":0.66,"h":0.045,"say":"'Strengths': 빠름(모든 창 병렬), 위치 무관, 분류에 강함."},{"x":0.06,"y":0.67,"w":0.7,"h":0.045,"say":"'Limits': 가까운 곳만, 먼 순서 못 봄. 순서에는 recurrence(**RNN(순환 신경망)**, Part 4)."},{"x":0.06,"y":0.725,"w":0.79,"h":0.045,"say":"'used in production for years': 감정, 주제 분류에 몇 년간 실제로 쓰였어요."},{"x":0.255,"y":0.855,"w":0.5,"h":0.045,"say":"'CNN = parallel n-gram detectors, RNN = a reader with memory'."}]},{"kind":"prof","when":"3주차 월요일 1교시","lines":["필터는 숫자들의 모음이라 여러 개가 있을 수 있고, 필터마다 값이 하나씩 나와요.","이미지로 치면 엣지만 남기는 필터처럼, 필터마다 맡은 역할이 달라요.","폭이 3이면 트리그램, 2면 바이그램. 이 필터 뱅크로 여러 피처를 얻어 판단해요.","단점은 윈도우만 봐서 로컬 컨텍스트만 본다는 것. 멀리 떨어진 두 단어의 관계는 거의 못 잡아요."]},{"kind":"prof","when":"3주차 월요일 1교시","lines":["문장을 왼쪽부터 읽으며 지금까지 본 정보를 계속 기억할 수 있느냐가 중요한 이슈예요.","그 아이디어가 리커런스(recurrence), 반복된다, 재귀적이라는 뜻이에요. 뒤에서 RNN 으로 배워요."]},{"kind":"steps","head":"필터 뱅크로 분류하기","steps":["폭 2, 3, 4, 5 필터를 여러 개 준비해요","필터마다 문장을 훑어 **특징 맵(Feature Map)**을 만들어요","필터마다 **최대 풀링(Max-pooling)**으로 숫자 하나씩 남겨요","그 숫자들을 모아 벡터 하나로 만들고, 그 위의 분류기가 감정이나 주제를 골라요"],"answer":"필터 개수만큼 숫자가 모여 분류기의 입력이 돼요."}],"pass4":[{"kind":"check","q":"**최대 풀링(Max-pooling)** 때문에 **CNN(합성곱 신경망)**이 구절의 위치에 둔감해지는 까닭은?","choices":["위치 정보를 따로 더해서","가장 큰 값 하나만 남기고 그 값이 어디서 나왔는지는 버려서","필터 폭이 넓어서"],"a":1,"why":"최댓값만 남으니 문장 앞에서 나왔든 뒤에서 나왔든 결과가 같아요."},{"kind":"english","head":"외워 쓸 답안 문장","en":"**CNN(합성곱 신경망)**은 **합성곱 필터(Convolution Filter)**로 **n-gram(엔그램)** 패턴을 병렬로 찾아 **분류(Classification)**에 강하지만 먼 거리 순서는 못 잡는다.","ko":"장점 셋(빠름, 위치 무관, 분류) + 한계 하나(로컬만)."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'위치에 둔감' 은 장점이자 단점이에요. 어디서 나왔는지 필요할 때는 정보가 사라져요.","**CNN(합성곱 신경망)** = 병렬 n-gram 탐지기, **RNN(순환 신경망)** = 기억을 가진 독자. 두 줄을 짝으로 외워요."]}]},{"p":15,"title":"Check Yourself: Part 1 확인 문제","terms":["Activation Function","Matrix","Hidden Layer","Convolution Filter","Max-pooling","n-gram","Parameter"],"pass1":[{"kind":"say","lines":["Part 1 을 스스로 확인하는 교수님의 문제 네 개예요.","60초 생각하고 옆 사람과 이야기해 보라는 쪽이에요.","슬라이드 아래: 'Q1, Q2 가 바로 풀리면 Part 2 로 갈 준비가 된 거예요.'"]}],"pass2":[{"kind":"compare","head":"네 문제 우리말 뜻","cols":["문제","우리말 뜻"],"rows":[["Q1","**활성화 함수(Activation Function)** 없이 선형층 10개를 쌓으면 표현력이 어떤가?"],["Q2","**은닉층(Hidden Layer)** 300개, 입력 창이 5단어 × 100차원이면 W(1) 의 shape 은?"],["Q3","폭 3 **합성곱 필터(Convolution Filter)**가 강하게 반응했다. 어떤 패턴을 잡은 걸까?"],["Q4","**최대 풀링(Max-pooling)**이 왜 구절의 위치(WHERE)에 둔감하게 만드나?"]]},{"kind":"points","head":"어느 쪽을 다시 보면 되나","items":["Q1 → p.11 (층이 합쳐짐)","Q2 → p.6 (창 벡터 5d), p.12 (W 의 shape)","Q3 → p.13 (trigram 탐지기)","Q4 → p.14 (최대 풀링)"]}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.075,"y":0.2,"w":0.64,"h":0.045,"say":"Q1: 'stack 10 linear layers with no activation', 'How expressive?'"},{"x":0.075,"y":0.265,"w":0.8,"h":0.045,"say":"Q2: '300 units', '5 words × 100 dims', 'shape of W(1)?'"},{"x":0.075,"y":0.33,"w":0.58,"h":0.045,"say":"Q3: 'A width-3 CNN filter fires strongly': 세게 반응했다."},{"x":0.075,"y":0.395,"w":0.6,"h":0.045,"say":"Q4: 'insensitive to WHERE a phrase occurs': 위치에 둔감."},{"x":0.34,"y":0.855,"w":0.32,"h":0.045,"say":"'If Q1 and Q2 feel instant, you are ready for part 2'."}]},{"kind":"prof","when":"3주차 월요일 1교시","lines":["1번: 선형층을 쌓아도 활성화가 없으면 하나의 선형 변환으로 합쳐져요. 깊어졌지만 표현력은 선형 모델이에요.","2번: 5단어 × 100차원이면 입력 x 는 500개 숫자, 히든 300개와 모두 이으려면 500 곱하기 300 만큼 필요해요.","3번: 연속된 세 단어의 특정 패턴, 학습된 트리그램 패턴을 감지한 거예요.","4번: 맥스 풀링은 가장 큰 값 하나만 남기고 나머지 정보는 다 버려요."]},{"kind":"steps","head":"Q2 shape 차근차근","given":"실습 N3L p.3 의 W (3, 5) 도 같은 규칙(은닉 3, 입력 5)이에요.","steps":["입력 x: 5단어 × 100차원 = 500 → x 의 shape (500,)","은닉 h(1): 300개 → (300,)","h(1) = f(W(1)x + b(1)) 이므로 W(1) 은 (300, 500): 행 = 출력 수, 열 = 입력 수","가중치 개수 300 × 500 = 150,000, 편향 항 b(1) 은 (300,) 300개"],"answer":"W(1) 의 shape (300, 500)"},{"kind":"bg","src":"기초 다지기 3단원","lines":["(300, 500) 행렬 @ (500,) 벡터 → (300,) 벡터. 가운데 500 끼리 맞아야 곱할 수 있어요.","'shape 을 맞춘다' 는 생각은 Part 2 역전파에서도 계속 써요."]}],"pass4":[{"kind":"exam","src":"N3 Check Yourself 1","q":"Q1. I stack 10 linear layers with no activation in between. How expressive is the result?","qko":"**활성화 함수(Activation Function)** 없이 선형층 10개를 쌓으면 얼마나 표현력이 있나?","solve":["선형층 하나는 행렬 곱 W 하나예요","W₁₀(...(W₂(W₁x))) = (W₁₀...W₂W₁)x 로 묶을 수 있어요","결국 **행렬(Matrix)** 하나(선형 변환 하나)와 같아요","그래서 곧은 경계만 그릴 수 있어요"],"answer":"선형층 하나와 같은 표현력(여전히 선형 모델). 깊이가 아무 이득이 없다."},{"kind":"exam","src":"N3 Check Yourself 1","q":"Q2. My hidden layer has 300 units and the input window is 5 words × 100 dims. What is the shape of W(1)?","qko":"**은닉층(Hidden Layer)** 300개, 입력 창 5단어 × 100차원일 때 W(1) 의 shape 은?","solve":["입력 x 길이 = 5 × 100 = 500","h(1) 길이 = 300","h(1) = f(W(1)x + b(1)) 에서 W(1)x 가 길이 300이 되려면 W(1) 은 300행 500열","가중치 수는 300 × 500 = 150,000개 (교수님은 '500 곱하기 300' 이라고 개수로 설명)"],"answer":"W(1) ∈ ℝ^(300×500), 즉 shape (300, 500)"},{"kind":"exam","src":"N3 Check Yourself 1","q":"Q3. A width-3 CNN filter fires strongly. What kind of pattern did it just detect?","qko":"폭 3 **합성곱 필터(Convolution Filter)**가 강하게 반응했다. 무엇을 찾은 걸까?","solve":["폭 3 = 연속된 세 단어를 한 번에 봐요","필터 값과 세 단어 벡터가 잘 맞으면 큰 값이 나와요","그러니 필터가 배운 세 단어 **n-gram(엔그램)**(trigram) 패턴이 거기 있다는 뜻이에요"],"answer":"학습된 trigram 패턴(연속된 세 단어의 특정 패턴, 예: 'was really great')"},{"kind":"exam","src":"N3 Check Yourself 1","q":"Q4. Why does max-pooling make the CNN insensitive to WHERE a phrase occurs?","qko":"**최대 풀링(Max-pooling)**이 왜 구절이 나온 위치에 둔감하게 만드나?","solve":["필터가 모든 위치에서 같은 값으로 계산해 특징 맵을 만들어요","**최대 풀링(Max-pooling)**은 그중 가장 큰 값 하나만 남겨요","그 값이 몇 번째 창에서 나왔는지는 버려요","그래서 구절이 앞에 있든 뒤에 있든 결과가 같아요"],"answer":"최댓값 하나만 남기고 위치 정보를 버리기 때문('어디서든 나왔나?' 만 묻는다)"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["Q2 에서 교수님은 '500 곱하기 300' 이라고 연결선 개수로 말했어요. shape 을 쓸 때는 식 W(1)x 에 맞춰 (300, 500) 으로 써요.","편향 항 b(1) 의 shape 은 (300,) 이에요. W(1) 과 헷갈리지 않아요."]}]},{"p":16,"title":"Part 2: Backpropagation","terms":["Backpropagation","Gradient"],"pass1":[{"kind":"say","lines":["Part 2 시작이에요. 제목은 **역전파(Backpropagation)**이에요.","부제 'how the gradients actually get computed' 는 '**기울기(Gradient)**를 실제로 어떻게 계산하나' 예요.","Part 1 에서 남은 질문, 'W 와 b 는 어떻게 정하나?' 의 답이 여기서 나와요."]}],"pass2":[],"pass3":[],"pass4":[]},{"p":17,"title":"계획: SGD 에는 기울기가 필요해요","terms":["Backpropagation","Forward Pass","Gradient","Gradient Descent","Stochastic Gradient Descent (SGD)","Learning Rate","Parameter","Loss Function","Word Vector","Matrix Calculus"],"pass1":[{"kind":"say","lines":["2부의 주제는 신경망이 '어떻게 배우는가'예요.","배우는 방법은 2주차와 똑같이 **경사 하강법(Gradient Descent)**, 산을 한 걸음씩 내려가기예요.","새로운 문제는 딱 하나, 층이 여러 개일 때 발밑 **기울기(Gradient)**를 어떻게 계산하느냐예요.","그 계산법이 오늘 배울 **역전파(Backpropagation)**예요."]},{"kind":"analogy","head":"안개 낀 산 내려가기","scene":"안개 낀 산에서 발밑 기울기만 보고 한 걸음씩 내려가요. 그런데 이번 산은 손잡이(조절 나사)가 수만 개예요.","map":[["산의 높이","**손실 함수(Loss Function)**"],["발밑 기울기","**기울기(Gradient)**"],["보폭","**학습률(Learning Rate)**"],["수만 개의 조절 나사","W, b, 그리고 **단어 벡터(Word Vector)**까지 모든 **파라미터(Parameter)**"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["The Plan: SGD Needs Gradients","계획: **확률적 경사 하강법(Stochastic Gradient Descent (SGD))**에는 기울기가 필요해요"],["learning = walk downhill on the loss","학습 = 손실이라는 산을 걸어 내려가기"],["θ now holds EVERYTHING","이제 θ(세타)에 모든 것이 들어가요: W, b, 단어 벡터까지"],["The missing piece: how do we COMPUTE ∇J?","빠진 조각: 여러 층 신경망에서 ∇J 를 어떻게 계산할까?"],["answer in two acts","답은 두 막: 손으로 **행렬 미적분(Matrix Calculus)** → 알고리즘으로 **역전파(Backpropagation)**"]]},{"kind":"points","head":"용어 하나씩","items":["**파라미터(Parameter)**: 모델이 스스로 고치는 숫자들. 기호 θ 하나로 몽땅 묶어 불러요.","**손실 함수(Loss Function)**: 틀린 정도를 매기는 벌점. J(θ)로 써요.","**기울기(Gradient)**: ∇(나블라) 기호. 벌점이 가장 빨리 커지는 방향이라, 반대로 가면 내려가요.","**학습률(Learning Rate)**: α(알파). 한 걸음의 보폭이에요."]},{"kind":"steps","head":"무엇이 무엇으로 이어지나","steps":["**순전파(Forward Pass)**: 입력으로 점수와 벌점 J 를 계산해요.","**역전파(Backpropagation)**: J 에 대한 모든 파라미터의 기울기 ∇J 를 구해요.","업데이트: θ 에서 α × ∇J 를 빼요.","다시 처음으로. 이걸 수없이 반복하면 벌점이 줄어요."],"answer":"2부는 이 중 두 번째 칸, '기울기를 어떻게 계산하나'를 다뤄요."},{"kind":"check","q":"이 슬라이드가 말하는 '새로운 문제'는 무엇일까요?","choices":["산을 내려가는 방법(SGD)을 새로 만드는 것","여러 층 신경망에서 기울기를 계산하는 것","단어 벡터를 새로 만드는 것"],"a":1,"why":"SGD 는 word2vec 때와 같아요. 새 문제는 화살표(∇J)를 계산하는 것이고, 답이 **역전파(Backpropagation)**예요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.279,"y":0.254,"w":0.379,"h":0.108,"say":"업데이트 식이에요. 새 θ = 옛 θ - α × 기울기. 2주차 word2vec 과 같은 식이에요."},{"x":0.061,"y":0.412,"w":0.629,"h":0.044,"say":"\"θ now holds EVERYTHING\": θ 안에 W 들, b 들, 그리고 단어 벡터 자체까지 들어가요."},{"x":0.079,"y":0.459,"w":0.564,"h":0.036,"say":"딥러닝은 입력 표현(단어 벡터)까지 스스로 다듬어요. 이것이 'deep' 의 거래라고 해요."},{"x":0.061,"y":0.508,"w":0.546,"h":0.044,"say":"빠진 조각: 여러 층 신경망에서 ∇J 를 어떻게 계산하느냐예요."},{"x":0.061,"y":0.565,"w":0.6,"h":0.042,"say":"답은 두 막이에요. 먼저 손으로 행렬 미분, 그다음 알고리즘인 역전파."}]},{"kind":"formula","head":"업데이트 식","tex":"\\theta^{new} = \\theta^{old} - \\alpha \\nabla_{\\theta} J(\\theta)","parts":[{"sym":"\\theta^{old}","say":"지금 가진 파라미터 전부(W, b, 단어 벡터)"},{"sym":"\\alpha","say":"**학습률(Learning Rate)**, 한 걸음의 보폭"},{"sym":"\\nabla_{\\theta} J(\\theta)","say":"벌점 J 를 θ 로 미분한 **기울기(Gradient)**. 오르막 방향이에요"},{"sym":"-","say":"빼기라서 오르막의 반대, 즉 내리막으로 가요"},{"sym":"\\theta^{new}","say":"한 걸음 내려간 새 파라미터"}],"whole":"지금 자리에서 기울기 반대 방향으로 보폭 α 만큼 한 걸음 가요."},{"kind":"steps","head":"한 걸음 손계산","given":"J(θ) = θ², θ = 3, α = 0.1","steps":["J(θ) = θ², 지금 θ = 3, α = 0.1 이라고 해 봐요.","기울기: J 를 θ 로 미분하면 2θ, θ = 3 에서 6 이에요.","업데이트: 3 - 0.1 × 6 = 3 - 0.6 = 2.4","벌점: 3² = 9 에서 2.4² = 5.76 으로 줄었어요."],"answer":"θ = 2.4, 벌점 9 → 5.76. 기울기만 알면 한 걸음은 쉬워요."},{"kind":"prof","when":"3주차 월요일 1교시","lines":["학습의 기본 원리는 지난주에 배운 것과 똑같아요.","W, b 들을 모두 합쳐서 그냥 θ 라고 표현해요.","word2vec 으로 만든 단어 벡터도 학습할 수 있어요. GloVe 처럼 이미 잘 학습된 게 있으면 얼려(freeze) 둘 수도 있고, 그건 선택이에요.","과제 2 에 역전파가 있어서, 수업을 잘 들으면 어렵지 않게 할 수 있을 거예요."]},{"kind":"bg","src":"기초 다지기 8단원 (wb-8 경사 하강법과 손실)","lines":["**경사 하강법(Gradient Descent)**의 한 걸음 계산과 **학습률(Learning Rate)**는 기초 다지기 8단원에 있어요.","미니배치로 자주 걷는 **확률적 경사 하강법(Stochastic Gradient Descent (SGD))**도 거기서 한 번 더 봐요."]}],"pass4":[{"kind":"check","q":"θ 안에 들어가지 않는 것은?","choices":["은닉층의 W 와 b","입력 단어 벡터 x","학습률 α"],"a":2,"why":"α 는 사람이 정하는 보폭이에요. θ 는 모델이 스스로 고치는 **파라미터(Parameter)**이고, 단어 벡터도 들어갈 수 있어요."},{"kind":"english","head":"답안 문장","en":"신경망 학습은 **확률적 경사 하강법(Stochastic Gradient Descent (SGD))**로 θ ← θ - α∇J 를 반복하는 것이고, 여러 층 신경망의 기울기 ∇J 는 **역전파(Backpropagation)**로 계산한다.","ko":"업데이트 방법은 word2vec 과 같고, 새로 배우는 것은 기울기 계산법이에요.","tip":"'방법은 같고, 화살표 계산이 새롭다' 로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**역전파(Backpropagation)**는 '기울기를 계산하는 방법'이에요. 파라미터를 고치는 것은 그 기울기로 하는 **경사 하강법(Gradient Descent)** 쪽이에요.","여기서 J 는 벌점(손실)이에요. 뒤 p.19 의 야코비안 J 와 글자가 같지만 다른 것이에요."]}]},{"p":18,"title":"미분, 한 걸음씩","terms":["Gradient","Derivative"],"pass1":[{"kind":"say","lines":["**미분(Derivative)**은 딱 한 가지 질문이에요.","\"x 를 살짝 밀면, f 는 얼마나 움직일까?\"","그 답이 그래프의 기울기예요. 뒤의 모든 행렬 식도 이 생각을 키운 것뿐이에요."]},{"kind":"figure","head":"x = 2 에서 살짝 밀어 보기","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"60\" y1=\"245\" x2=\"440\" y2=\"245\" class=\"e\"/><line x1=\"60\" y1=\"245\" x2=\"60\" y2=\"20\" class=\"e\"/><text x=\"445\" y=\"262\" font-size=\"14\" text-anchor=\"end\" class=\"tm\">x<\/text><text x=\"70\" y=\"30\" font-size=\"15\" text-anchor=\"start\" class=\"tb\">f(x) = x³<\/text><polyline points=\"60,240 67,240 74,240 82,240 89,240 96,240 103,240 110,239 118,239 125,239 132,238 139,238 146,237 154,236 161,235 168,234 175,233 182,232 190,230 197,228 204,227 211,224 218,222 226,220 233,217 240,214 247,210 254,207 262,203 269,199 276,195 283,190 290,185 298,180 305,174 312,168 319,162 326,155 334,148 341,140 348,132 355,124 362,116 370,106 377,97 384,87 391,76 398,66 406,54 413,42 420,30\" fill=\"none\" class=\"e2\"/><line x1=\"268\" y1=\"222\" x2=\"430\" y2=\"41\" class=\"e b1\"/><circle cx=\"348\" cy=\"132\" r=\"6\" class=\"n2 b1\"/><text x=\"240\" y=\"130\" font-size=\"15\" text-anchor=\"end\" class=\"tb b1\">x = 2 에서 기울기 12<\/text><text x=\"250\" y=\"190\" font-size=\"14\" text-anchor=\"start\" class=\"t b2\">x를 0.001 밀면<\/text><text x=\"250\" y=\"212\" font-size=\"14\" text-anchor=\"start\" class=\"t b2\">f는 약 0.012 움직여요<\/text><\/svg>","caption":"f(x) = x³ 의 x = 2 에서 기울기는 12예요. x 를 0.001 밀면 f 는 약 0.012 움직여요.","builds":2}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["Derivatives, One Step at a Time","미분, 한 걸음씩 차근차근"],["the derivative is the slope","미분은 기울기예요"],["nudge x, how much does f move?","x 를 살짝 밀면 f 는 얼마나 움직이나?"],["scaled up to vectors and matrices","이 생각을 벡터와 행렬로 키울 뿐이에요"],["Hold onto the nudge intuition","'살짝 밀기' 느낌을 꼭 붙잡고 가세요"]]},{"kind":"points","head":"용어 뜻","items":["**미분(Derivative)**: 입력 하나, 출력 하나일 때의 기울기. f'(x) 로 써요.","도함수: x 자리마다 기울기를 알려 주는 식. x³ 의 도함수는 3x² 이에요.","**기울기(Gradient)**: 입력이 여러 개로 늘면 미분이 여러 개가 모인 것(다음 쪽)."]},{"kind":"check","q":"f(x) = x³ 일 때, x = 2 에서 기울기는?","choices":["6","8","12"],"a":2,"why":"f'(x) = 3x² 이니 3 × 2² = 12 예요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.589,"h":0.038,"say":"입력 1개, 출력 1개: 미분은 기울기(slope)예요."},{"x":0.357,"y":0.26,"w":0.207,"h":0.051,"say":"예시 함수 f(x) = x³ 과 그 도함수 f'(x) = 3x² 이에요."},{"x":0.546,"y":0.489,"w":0.161,"h":0.06,"say":"빨간 점에서 기울기 = f'(x₀). 'x 를 밀면 f 가 얼마나 움직이나' 와 같은 말이에요."},{"x":0.061,"y":0.692,"w":0.489,"h":0.042,"say":"뒤에 나올 모든 것은 이 생각을 벡터, 행렬로 키운 것이에요."}]},{"kind":"formula","head":"x³ 의 미분","tex":"f(x) = x^3, \\quad f'(x) = 3x^2","parts":[{"sym":"f(x) = x^3","say":"x 를 세 번 곱하는 함수"},{"sym":"f'(x)","say":"f 의 미분(도함수). 프라임(') 이라고 읽어요"},{"sym":"3x^2","say":"지수 3 을 앞으로 내리고 지수는 하나 줄여요"},{"sym":"f'(x_0)","say":"특정한 점 x₀ 에서의 기울기 값"}],"whole":"x³ 을 미분하면 3x², x = 2 에서 12 예요."},{"kind":"steps","head":"살짝 밀어서 확인하기","steps":["x = 2 에서 f = 2³ = 8","x 를 0.001 밀어 2.001 로: f = 2.001³ = 8.012006001","움직인 양: 8.012006001 - 8 = 0.012006001","밀어 준 양으로 나누기: 0.012006001 ÷ 0.001 = 12.006"],"answer":"12.006 ≈ 12. 공식 3x² = 12 와 거의 같아요. 이것이 '살짝 밀기' 의 뜻이에요."},{"kind":"prof","when":"3주차 월요일 1교시","lines":["f(x) 가 x³ 이면 도함수는 3x² 이 되죠.","어떤 점을 딱 찍으면 그 값이 그 점에서의 순간 기울기예요.","그 기울기만큼 살짝 이동하면 아래로 내려갈 수 있고, 이것이 경사 하강법의 개념이에요."]},{"kind":"bg","src":"기초 다지기 7단원 (wb-7 함수, 기울기, 미분)","lines":["기울기, 도함수, x² 과 x³ 의 미분 규칙은 기초 다지기 7단원에 있어요.","처음이면 7단원을 먼저 보고 오면 이 뒤가 훨씬 쉬워요."]},{"kind":"say","lines":["실습에서는 N3L p.4 에서 f(x) = x³ + 2x 를 PyTorch 로 미분해,","손으로 구한 3x² + 2 와 같은지(x = 2 에서 둘 다 14) 확인해요."]}],"pass4":[{"kind":"check","q":"f(x) = x³ + 2x 의 x = 2 에서 기울기는? (실습 N3L p.4 의 예)","choices":["12","14","16"],"a":1,"why":"f'(x) = 3x² + 2, x = 2 에서 12 + 2 = 14 예요."},{"kind":"english","head":"답안 문장","en":"**미분(Derivative)**은 입력을 조금 바꿨을 때 출력이 얼마나 변하는지를 나타내는 기울기이다.","ko":"'nudge x, how much does f move?' 를 그대로 옮긴 문장이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드의 '밀기' 로 얻은 12.006 은 어림값이에요. 미는 양을 더 작게 할수록 진짜 기울기 12 에 가까워져요."]}]},{"p":19,"title":"기울기와 야코비안","terms":["Jacobian","Gradient","Partial Derivative"],"pass1":[{"kind":"say","lines":["입력이 여러 개가 되면, '살짝 밀기' 도 입력마다 한 번씩 해야 해요.","출력이 하나면 그 결과들을 한 줄로 모은 것이 **기울기(Gradient)** 벡터예요.","출력도 여러 개면 표로 모아요. 그 표가 **야코비안(Jacobian)**이에요."]},{"kind":"figure","head":"숫자 하나 → 벡터 → 행렬","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"80\" y=\"60\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">숫자 하나<\/text><rect x=\"65\" y=\"95\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2\"/><text x=\"80.0\" y=\"115.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">12<\/text><text x=\"80\" y=\"170\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">입력 1, 출력 1<\/text><text x=\"80\" y=\"192\" font-size=\"14\" text-anchor=\"middle\" class=\"t\">미분<\/text><text x=\"225\" y=\"60\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">기울기 벡터<\/text><rect x=\"195\" y=\"95\" width=\"30\" height=\"30\" rx=\"2\" class=\"n3 b1\"/><text x=\"210.0\" y=\"115.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b1\">2<\/text><rect x=\"225\" y=\"95\" width=\"30\" height=\"30\" rx=\"2\" class=\"n3 b1\"/><text x=\"240.0\" y=\"115.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b1\">3<\/text><text x=\"225\" y=\"170\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">입력 2, 출력 1<\/text><text x=\"225\" y=\"192\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">기울기<\/text><text x=\"390\" y=\"60\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">야코비안 행렬<\/text><rect x=\"345\" y=\"80\" width=\"30\" height=\"30\" rx=\"2\" class=\"n b2\"/><text x=\"360.0\" y=\"100.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b2\">1<\/text><rect x=\"375\" y=\"80\" width=\"30\" height=\"30\" rx=\"2\" class=\"n b2\"/><text x=\"390.0\" y=\"100.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b2\">2<\/text><rect x=\"405\" y=\"80\" width=\"30\" height=\"30\" rx=\"2\" class=\"n b2\"/><text x=\"420.0\" y=\"100.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b2\">0<\/text><rect x=\"345\" y=\"110\" width=\"30\" height=\"30\" rx=\"2\" class=\"n b2\"/><text x=\"360.0\" y=\"130.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b2\">0<\/text><rect x=\"375\" y=\"110\" width=\"30\" height=\"30\" rx=\"2\" class=\"n b2\"/><text x=\"390.0\" y=\"130.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b2\">0<\/text><rect x=\"405\" y=\"110\" width=\"30\" height=\"30\" rx=\"2\" class=\"n b2\"/><text x=\"420.0\" y=\"130.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b2\">3<\/text><text x=\"390\" y=\"170\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">입력 3, 출력 2<\/text><text x=\"390\" y=\"192\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">2×3 표<\/text><text x=\"240\" y=\"245\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">같은 생각이 자라는 중이에요<\/text><\/svg>","caption":"미분(숫자 하나)이 기울기(한 줄)로, 다시 야코비안(표)으로 자라요. 생각은 같아요.","builds":3}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["n inputs, 1 output: gradient","입력 n 개, 출력 1 개: 기울기(벡터)"],["a vector of partial derivatives","편미분들을 모은 벡터"],["n inputs, m outputs: Jacobian, an m×n matrix","입력 n 개, 출력 m 개: 야코비안, m×n 행렬"],["entry (i, j) = how output i responds to input j","(i, j) 칸 = 입력 j 를 밀 때 출력 i 가 얼마나 반응하나"],["its derivative IS a Jacobian","신경망 층의 미분은 바로 야코비안이에요"]]},{"kind":"points","head":"용어 뜻","items":["**편미분(Partial Derivative)**: 입력 여럿 중 하나만 살짝 밀고 나머지는 그대로 둔 미분. ∂ 기호를 써요.","**기울기(Gradient)**: 출력 하나에 대한 편미분을 입력마다 모은 한 줄.","**야코비안(Jacobian)**: 출력마다 기울기 한 줄씩, 줄을 쌓은 표. 행 = 출력, 열 = 입력."]},{"kind":"compare","head":"셋을 나란히","cols":["","입력","출력","미분의 생김새"],"rows":[["미분","1 개","1 개","숫자 하나"],["기울기","n 개","1 개","숫자 n 개짜리 벡터"],["야코비안","n 개","m 개","m×n 행렬(표)"]]},{"kind":"check","q":"입력이 3 개, 출력이 2 개인 함수의 야코비안 크기는?","choices":["3×2","2×3","3×3"],"a":1,"why":"행은 출력 수(m = 2), 열은 입력 수(n = 3)라서 2×3 이에요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.436,"h":0.038,"say":"입력 n 개, 출력 1 개: 기울기, 편미분들의 벡터예요."},{"x":0.061,"y":0.25,"w":0.661,"h":0.039,"say":"입력 n 개, 출력 m 개: 야코비안, m×n 행렬이에요. (i, j) 칸은 출력 i 가 입력 j 에 반응하는 정도예요."},{"x":0.139,"y":0.355,"w":0.296,"h":0.152,"say":"기울기 벡터 식: 입력 x₁ 부터 xₙ 까지 하나씩 편미분해 늘어놓아요."},{"x":0.486,"y":0.355,"w":0.296,"h":0.152,"say":"야코비안 식: m×n 실수 행렬이고, i 행 j 열에 ∂fᵢ/∂xⱼ 가 들어가요."},{"x":0.061,"y":0.586,"w":0.486,"h":0.039,"say":"신경망 층은 벡터를 벡터로 바꿔요. 그래서 층의 미분은 야코비안이에요."}]},{"kind":"formula","head":"기울기 벡터","tex":"\\nabla f = \\left[\\frac{\\partial f}{\\partial x_1}, \\ldots, \\frac{\\partial f}{\\partial x_n}\\right]","parts":[{"sym":"\\nabla f","say":"f 의 기울기. ∇ 는 '나블라' 라고 읽어요"},{"sym":"\\frac{\\partial f}{\\partial x_1}","say":"x₁ 만 살짝 밀 때 f 가 움직이는 정도(편미분)"},{"sym":"\\ldots","say":"x₂, x₃ 처럼 중간 것들도 똑같이"},{"sym":"\\frac{\\partial f}{\\partial x_n}","say":"마지막 입력 xₙ 에 대한 편미분"}],"whole":"입력마다 따로 밀어 본 결과를 한 줄로 모은 것이 기울기예요."},{"kind":"formula","head":"야코비안 행렬","tex":"J \\in \\mathbb{R}^{m \\times n}, \\quad J_{ij} = \\frac{\\partial f_i}{\\partial x_j}","parts":[{"sym":"J","say":"**야코비안(Jacobian)** 행렬"},{"sym":"\\mathbb{R}^{m \\times n}","say":"실수가 m 행 n 열로 놓인 표"},{"sym":"J_{ij}","say":"i 번째 행, j 번째 열의 칸"},{"sym":"\\frac{\\partial f_i}{\\partial x_j}","say":"입력 j 를 밀 때 출력 i 가 움직이는 정도"}],"whole":"행은 출력, 열은 입력. 표 한 칸이 편미분 하나예요."},{"kind":"steps","head":"기울기 손계산","steps":["f(x₁, x₂) = x₁² + 3x₂, 점 (1, 2) 에서 구해요.","x₁ 만 밀기: x₂ 는 상수 취급. x₁² 의 미분 2x₁ = 2 × 1 = 2","x₂ 만 밀기: x₁ 은 상수 취급. 3x₂ 의 미분 = 3","모으기: ∇f = [2, 3]"],"answer":"∇f = [2, 3]. 입력 2 개라서 숫자 2 개짜리 벡터예요."},{"kind":"steps","head":"야코비안 손계산","steps":["F(x₁, x₂, x₃) = (x₁ + 2x₂, 3x₃). 입력 3 개, 출력 2 개예요.","1행(출력 f₁ = x₁ + 2x₂): x₁ 로 1, x₂ 로 2, x₃ 로 0","2행(출력 f₂ = 3x₃): x₁ 로 0, x₂ 로 0, x₃ 로 3","표로 쌓기: J = [[1, 2, 0], [0, 0, 3]]"],"answer":"2×3 야코비안. 출력 수 × 입력 수 크기예요."},{"kind":"prof","when":"3주차 월요일 1교시","lines":["입력이 500 개, 출력이 300 개면 500 곱하기 300 만큼의 파라미터가 있어요.","기울기 벡터는 각 입력이 조금씩 바뀔 때 출력이 어떻게 변하는지 모아 놓은 거예요.","한마디로 가중치 행렬의 크기만큼 기울기가 생겨요. 그 기울기의 행렬을 야코비안이라고 해요."]},{"kind":"bg","src":"기초 다지기 7단원 (wb-7 함수, 기울기, 미분)","lines":["편미분은 '다른 변수는 숫자처럼 얼려 두고' 한 변수로만 미분하는 거예요.","미분 규칙(x², 상수배, 합)은 기초 다지기 7단원에서 연습해요."]}],"pass4":[{"kind":"check","q":"f(x₁, x₂) = x₁ × x₂ 의 점 (3, 2) 에서 기울기는?","choices":["[3, 2]","[2, 3]","[6, 6]"],"a":1,"why":"x₁ 로 편미분하면 x₂ = 2, x₂ 로 편미분하면 x₁ = 3. 그래서 [2, 3] 이에요."},{"kind":"english","head":"답안 문장","en":"**야코비안(Jacobian)**은 입력 n 개, 출력 m 개인 함수의 편미분을 모은 m×n 행렬로, (i, j) 성분은 j 번째 입력에 대한 i 번째 출력의 변화율이다.","ko":"행 = 출력, 열 = 입력만 기억하면 돼요.","tip":"'출력이 먼저(행), 입력이 나중(열)'."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["기울기(출력 1 개)와 야코비안(출력 여러 개)을 구별해요. 야코비안의 한 행이 곧 그 출력의 기울기예요.","J 는 여기서 야코비안이지만, 손실 함수 J(θ) 에도 같은 글자를 써요. 문맥으로 구별해요."]}]},{"p":20,"title":"연쇄 법칙, 벡터 버전","terms":["Backpropagation","Chain Rule","Jacobian","Activation Function","Nonlinearity","Local Gradient","Hidden Layer"],"pass1":[{"kind":"say","lines":["**연쇄 법칙(Chain Rule)**은 오늘 가장 중요한 한 가지예요.","여러 단계를 거친 계산은, 단계마다의 미분을 곱하면 전체 미분이 나와요.","맞물린 톱니바퀴처럼, 3배 돌리고 8배 돌리면 모두 합쳐 24배 돌아가요."]},{"kind":"figure","head":"톱니바퀴 두 개","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"60\" cy=\"120\" r=\"26\" class=\"n3\"/><text x=\"60\" y=\"126\" font-size=\"16\" text-anchor=\"middle\" class=\"tl\">x<\/text><circle cx=\"240\" cy=\"120\" r=\"26\" class=\"n3\"/><text x=\"240\" y=\"126\" font-size=\"16\" text-anchor=\"middle\" class=\"tl\">z<\/text><circle cx=\"420\" cy=\"120\" r=\"26\" class=\"n2\"/><text x=\"420\" y=\"126\" font-size=\"16\" text-anchor=\"middle\" class=\"tl\">h<\/text><text x=\"60\" y=\"172\" font-size=\"14\" text-anchor=\"middle\" class=\"t\">x = 1<\/text><text x=\"240\" y=\"172\" font-size=\"14\" text-anchor=\"middle\" class=\"t\">z = 3x + 1 = 4<\/text><text x=\"420\" y=\"172\" font-size=\"14\" text-anchor=\"middle\" class=\"t\">h = z² = 16<\/text><line x1=\"88\" y1=\"120\" x2=\"203\" y2=\"120\" class=\"e2 b1\"/><polygon points=\"212,120 203,125 203,115\" class=\"arrow b1\"/><text x=\"150\" y=\"105\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b1\">× 3<\/text><text x=\"150\" y=\"145\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">dz/dx = 3<\/text><line x1=\"268\" y1=\"120\" x2=\"383\" y2=\"120\" class=\"e2 b2\"/><polygon points=\"392,120 383,125 383,115\" class=\"arrow b2\"/><text x=\"330\" y=\"105\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b2\">× 8<\/text><text x=\"330\" y=\"145\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">dh/dz = 2z = 8<\/text><rect x=\"130\" y=\"210\" width=\"220\" height=\"36\" rx=\"2\" class=\"box2 b3\"/><text x=\"240.0\" y=\"234.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b3\">dh/dx = 3 × 8 = 24<\/text><\/svg>","caption":"x 가 z 를 3배로, z 가 h 를 8배로 돌려요. 그러면 x 는 h 를 3 × 8 = 24배로 돌려요.","builds":3},{"kind":"analogy","head":"맞물린 톱니바퀴","scene":"첫 바퀴를 한 칸 돌리면 둘째가 3칸, 둘째가 한 칸 돌면 셋째가 8칸 돌아요.","map":[["바퀴 하나의 회전비","한 단계의 미분(**국소 기울기(Local Gradient)**)"],["회전비를 곱하기","**연쇄 법칙(Chain Rule)**"],["첫 바퀴에서 끝 바퀴까지 비","전체 미분 dh/dx"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["One-variable chain rule: multiply derivatives","한 변수 연쇄 법칙: 미분을 곱해요"],["Vector version: multiply Jacobians","벡터 버전: 야코비안(행렬)을 곱해요"],["order matters, shapes must chain","곱하는 순서가 중요하고, 크기가 사슬처럼 이어져야 해요"],["this single rule + bookkeeping = ALL of backpropagation","이 규칙 하나 + 장부 정리 = 역전파의 전부"],["If you can multiply matrices, you can differentiate a neural network","행렬을 곱할 줄 알면 신경망을 미분할 수 있어요"]]},{"kind":"points","head":"용어 뜻","items":["**연쇄 법칙(Chain Rule)**: 합성 함수의 미분 = 단계별 미분의 곱.","z = Wx + b: **은닉층(Hidden Layer)**의 첫 단계, 곱하고 더하기예요.","h = f(z): **활성화 함수(Activation Function)**를 씌워 **비선형성(Nonlinearity)**을 넣는 둘째 단계.","**역전파(Backpropagation)**: 이 규칙을 신경망 전체에 체계적으로 적용한 것."]},{"kind":"steps","head":"x 에서 h 까지 두 계단","steps":["x 가 들어와요.","z = Wx + b 를 계산해요(1 계단).","h = f(z) 를 계산해요(2 계단).","그래서 h 를 x 로 미분하려면 두 계단의 미분을 곱해요: ∂h/∂z × ∂z/∂x"],"answer":"한 번에 가지 않고 z 를 거쳐 왔으니, 거쳐 온 만큼 곱해요."},{"kind":"check","q":"h = f(z), z = g(x) 일 때 dh/dx 는?","choices":["dh/dz + dz/dx","dh/dz × dz/dx","dh/dz ÷ dz/dx"],"a":1,"why":"**연쇄 법칙(Chain Rule)**은 단계별 미분을 곱해요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.568,"h":0.038,"say":"한 변수에서는 미분을 곱하고, 벡터에서는 야코비안을 곱해요."},{"x":0.114,"y":0.33,"w":0.282,"h":0.07,"say":"두 계단: h = f(z), 그리고 z = Wx + b."},{"x":0.429,"y":0.33,"w":0.164,"h":0.074,"say":"그래서 ∂h/∂x = ∂h/∂z × ∂z/∂x. 가운데 z 가 약분되는 것처럼 보이죠."},{"x":0.061,"y":0.508,"w":0.682,"h":0.038,"say":"층을 이어 붙이면 야코비안의 곱이 돼요. 순서가 중요하고 크기가 이어져야 해요."},{"x":0.061,"y":0.562,"w":0.429,"h":0.041,"say":"이 규칙 하나와 장부 정리가 역전파의 전부예요."}]},{"kind":"formula","head":"연쇄 법칙(벡터)","tex":"h = f(z), \\quad z = Wx + b \\;\\Rightarrow\\; \\frac{\\partial h}{\\partial x} = \\frac{\\partial h}{\\partial z}\\frac{\\partial z}{\\partial x}","parts":[{"sym":"z = Wx + b","say":"입력 x 에 W 를 곱하고 b 를 더한 중간값"},{"sym":"h = f(z)","say":"z 에 **활성화 함수(Activation Function)** f 를 씌운 값"},{"sym":"\\frac{\\partial h}{\\partial z}","say":"둘째 계단의 야코비안"},{"sym":"\\frac{\\partial z}{\\partial x}","say":"첫째 계단의 야코비안"},{"sym":"\\frac{\\partial h}{\\partial x}","say":"둘을 곱한 전체 야코비안"}],"whole":"거쳐 온 계단의 야코비안을 순서대로 곱하면 전체 미분이에요."},{"kind":"steps","head":"숫자로 연쇄 법칙","steps":["z = 3x + 1, h = z², x = 1 이라고 해요(숫자 하나짜리 버전).","순서대로 계산: z = 3 × 1 + 1 = 4, h = 4² = 16","첫 계단 dz/dx = 3","둘째 계단 dh/dz = 2z = 2 × 4 = 8","곱하기: dh/dx = 8 × 3 = 24","확인: x 를 1.001 로 밀면 h = 4.003² = 16.024009, 늘어난 양 ÷ 0.001 = 24.009"],"answer":"dh/dx = 24. 살짝 밀어 본 값 24.009 와 거의 같아요."},{"kind":"prof","when":"3주차 월요일 1교시","lines":["고등학교 때 합성 함수를 미분하면서 이런 체인 룰을 배웠을 텐데, 이것도 하나의 합성 함수예요.","z 를 g(x) 라는 함수로 생각하면 h 는 f(g(x)) 가 되죠.","체인 룰이 가장 중요하다고 보시면 돼요. x 가 z 에, z 가 h 에 미치는 영향을 이어서 곱하면 돼요.","이렇게 체인 룰을 신경망 전체에 체계적으로 적용하는 게 역전파예요."]},{"kind":"bg","src":"기초 다지기 7단원 (wb-7 함수, 기울기, 미분)","lines":["연쇄 법칙 맛보기는 기초 다지기 7단원 끝에 있어요.","(3x + 1)² 을 전개하지 않고 미분하는 연습을 해 보세요."]}],"pass4":[{"kind":"check","q":"z = 2x, h = z³, x = 1 일 때 dh/dx 는?","choices":["6","12","24"],"a":2,"why":"z = 2, dh/dz = 3z² = 12, dz/dx = 2, 곱하면 24 예요."},{"kind":"english","head":"답안 문장","en":"**연쇄 법칙(Chain Rule)**에 따르면 합성 함수의 미분은 각 단계 미분의 곱이며, 벡터 함수에서는 각 층의 **야코비안(Jacobian)**을 곱한다. 이를 신경망 전체에 적용한 것이 **역전파(Backpropagation)**이다.","ko":"교수님이 가장 중요하다고 한 규칙이에요.","tip":"'단계마다 미분, 그리고 곱하기'."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["미분끼리 더하는 게 아니라 곱해요. 한 경로 위의 단계는 곱하고, 여러 경로가 만나면 그때 더해요(p.30).","행렬 곱은 순서를 바꾸면 안 돼요. ∂h/∂z 가 앞, ∂z/∂x 가 뒤예요."]}]},{"p":21,"title":"주머니 속 야코비안 네 개","terms":["Chain Rule","Jacobian","Activation Function","ReLU","Transpose","Hadamard Product","Diagonal Matrix","Identity Matrix"],"pass1":[{"kind":"say","lines":["복잡한 신경망도 사실은 레고 블록 몇 종류를 이어 붙인 것이에요.","블록은 네 가지: 곱하기(W), 더하기(b), 활성화(f), 점수 내기(u)예요.","블록마다 미분 하나씩만 알면, **연쇄 법칙(Chain Rule)**으로 곱해서 전체 미분이 나와요."]},{"kind":"figure","head":"레고 블록 네 개","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240\" y=\"30\" font-size=\"14\" text-anchor=\"middle\" class=\"tm\">순전파: 왼쪽 → 오른쪽<\/text><rect x=\"10\" y=\"55\" width=\"100\" height=\"44\" rx=\"2\" class=\"n3\"/><text x=\"60.0\" y=\"82.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">× W 곱하기<\/text><line x1=\"110\" y1=\"77\" x2=\"119\" y2=\"77\" class=\"e\"/><polygon points=\"128,77 119,82 119,72\" class=\"arrow\"/><rect x=\"128\" y=\"55\" width=\"100\" height=\"44\" rx=\"2\" class=\"n3\"/><text x=\"178.0\" y=\"82.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">+ b 더하기<\/text><line x1=\"228\" y1=\"77\" x2=\"237\" y2=\"77\" class=\"e\"/><polygon points=\"246,77 237,82 237,72\" class=\"arrow\"/><rect x=\"246\" y=\"55\" width=\"100\" height=\"44\" rx=\"2\" class=\"n3\"/><text x=\"296.0\" y=\"82.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">f 활성화<\/text><line x1=\"346\" y1=\"77\" x2=\"355\" y2=\"77\" class=\"e\"/><polygon points=\"364,77 355,82 355,72\" class=\"arrow\"/><rect x=\"364\" y=\"55\" width=\"106\" height=\"44\" rx=\"2\" class=\"n3\"/><text x=\"417.0\" y=\"82.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">u 와 점수<\/text><text x=\"60\" y=\"140\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">x로 미분: W<\/text><text x=\"178\" y=\"140\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">b로 미분: I<\/text><text x=\"296\" y=\"140\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">diag(f'(z))<\/text><text x=\"417\" y=\"140\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">h로 미분: uᵀ<\/text><text x=\"240\" y=\"200\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">블록마다 미분 하나씩 외워 두면<\/text><text x=\"240\" y=\"225\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">곱하기만으로 전체 기울기가 나와요<\/text><\/svg>","caption":"왼쪽에서 오른쪽으로 계산이 흐르고, 블록마다 자기 미분(야코비안)을 하나씩 갖고 있어요.","builds":2}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["A Pocketful of Jacobians","주머니에 넣어 다닐 야코비안 몇 개"],["Four building blocks cover almost every network","블록 네 개로 거의 모든 신경망을 다뤄요"],["Complex nets are LEGO","복잡한 신경망도 레고예요"],["Identity matrix","**단위 행렬(Identity Matrix)**: 곱해도 그대로인 행렬"]]},{"kind":"compare","head":"블록 네 개와 그 미분","cols":["블록","계산","무엇으로 미분","결과"],"rows":[["곱하기","Wx","x","W"],["더하기","Wx + b","b","I (**단위 행렬(Identity Matrix)**)"],["활성화","h = f(z)","z","diag(f'(z)) (**대각 행렬(Diagonal Matrix)**)"],["점수","s = uᵀh","h","uᵀ (**전치(Transpose)**된 u)"]]},{"kind":"points","head":"용어 뜻","items":["**대각 행렬(Diagonal Matrix)**: 대각선 칸에만 숫자가 있고 나머지는 0인 표.","**단위 행렬(Identity Matrix)**: 대각선이 모두 1인 대각 행렬. 숫자 1처럼 곱해도 그대로예요.","**전치(Transpose)**: 행과 열을 뒤바꾸기. 세로 벡터 u 가 가로 벡터 uᵀ 가 돼요."]},{"kind":"check","q":"h = f(z) 에서 ∂h/∂z 가 대각 행렬인 이유는?","choices":["hᵢ 는 zᵢ 하나에만 영향을 받아서","f 가 항상 직선이라서","W 가 정사각 행렬이라서"],"a":0,"why":"**활성화 함수(Activation Function)**는 칸마다 따로 씌워요. 그래서 다른 칸의 영향은 0 이고 대각선만 남아요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.204,"y":0.165,"w":0.468,"h":0.247,"say":"레고 그림: x(n×1)와 W(m×n)를 곱해 z, b 를 더하고, f 를 씌워 h, u 와 점곱해 점수 s(숫자 하나)."},{"x":0.207,"y":0.47,"w":0.25,"h":0.406,"say":"활성화의 야코비안: i = j 일 때만 f'(zᵢ), 나머지 칸은 0. 그래서 diag(f'(z))."},{"x":0.507,"y":0.482,"w":0.193,"h":0.095,"say":"Wx + b 를 x 로 미분하면 W."},{"x":0.507,"y":0.609,"w":0.193,"h":0.114,"say":"Wx + b 를 b 로 미분하면 단위 행렬 I."},{"x":0.507,"y":0.749,"w":0.193,"h":0.102,"say":"uᵀh 를 h 로 미분하면 uᵀ."}]},{"kind":"formula","head":"활성화 블록의 야코비안","tex":"\\left(\\frac{\\partial h}{\\partial z}\\right)_{ij} = \\begin{cases} f'(z_i) & i = j \\\\ 0 & \\text{otherwise} \\end{cases} \\;\\Rightarrow\\; \\frac{\\partial h}{\\partial z} = \\mathrm{diag}(f'(z))","parts":[{"sym":"h_i = f(z_i)","say":"h 의 i 번째 칸은 z 의 i 번째 칸에만 f 를 씌운 것"},{"sym":"i = j","say":"자기 칸끼리면 기울기 f'(zᵢ)"},{"sym":"0","say":"남의 칸끼리면 영향이 없어 0"},{"sym":"\\mathrm{diag}(f'(z))","say":"대각선에 f'(z₁) ... f'(zₙ) 이 놓인 **대각 행렬(Diagonal Matrix)**"}],"whole":"칸마다 따로 씌우는 함수라 대각선만 살아남아요."},{"kind":"formula","head":"나머지 세 블록","tex":"\\frac{\\partial}{\\partial x}(Wx + b) = W, \\quad \\frac{\\partial}{\\partial b}(Wx + b) = I, \\quad \\frac{\\partial}{\\partial h}(u^T h) = u^T","parts":[{"sym":"\\frac{\\partial}{\\partial x}(Wx + b) = W","say":"3x 를 x 로 미분하면 3 인 것처럼, Wx 를 x 로 미분하면 W"},{"sym":"\\frac{\\partial}{\\partial b}(Wx + b) = I","say":"b 를 b 로 미분하면 1, 벡터라서 **단위 행렬(Identity Matrix)** I"},{"sym":"\\frac{\\partial}{\\partial h}(u^T h) = u^T","say":"2h 를 h 로 미분하면 2 인 것처럼, uᵀh 를 h 로 미분하면 uᵀ"}],"whole":"모두 '숫자 한 개짜리 미분' 을 벡터로 옮긴 것이에요."},{"kind":"steps","head":"ReLU 로 대각 행렬 만들기","steps":["z = [2, -1], 활성화는 **ReLU** 라고 해요.","ReLU 의 미분: 양수면 1, 음수면 0. 그래서 f'(z) = [1, 0]","대각 행렬: diag(f'(z)) = [[1, 0], [0, 0]]","u = [2, 3] 이면 uᵀ diag(f'(z)) = [2×1 + 3×0, 2×0 + 3×0] = [2, 0]","같은 자리끼리 곱한 [2×1, 3×0] = [2, 0] 과 같아요. 이것이 **원소별 곱(Hadamard Product)**예요."],"answer":"대각 행렬 곱하기 = 원소별 곱. 결과 [2, 0]."},{"kind":"prof","when":"3주차 월요일 1교시","lines":["앞으로 쓸 야코비안 4가지는 암기할 필요는 없어요. PyTorch 같은 것에서 이 기울기들이 다 계산돼요.","그래도 수식을 이해하기 위해서 이 네 가지를 암기하시면 좋아요.","활성화에서 h₁ 은 z₁ 의 영향만 받고 다른 뉴런의 영향은 받지 않아요. 그래서 대각선에만 값이 있어요."]},{"kind":"prof","when":"3주차 월요일 2교시","lines":["동그라미 기호는 하다마드 곱(Hadamard product), 원소별 곱이라고 생각하시면 돼요.","대각 행렬을 곱하면 나머지가 다 0 이라서, 결국 같은 자리 원소끼리만 곱한 것과 같아요."]},{"kind":"bg","src":"기초 다지기 3단원 (wb-3 행렬과 행렬 곱, shape)","lines":["행렬 곱, 전치(T), shape 은 기초 다지기 3단원에 있어요.","(1×2) 가로 벡터 × (2×2) 행렬 = (1×2) 가로 벡터. 가운데 2 가 같아야 곱할 수 있어요."]}],"pass4":[{"kind":"check","q":"z = [3, -2], f = ReLU, u = [1, 5] 일 때 uᵀ diag(f'(z)) 는?","choices":["[1, 5]","[3, 0]","[1, 0]"],"a":2,"why":"f'(z) = [1, 0] 이니 원소별 곱 [1×1, 5×0] = [1, 0] 이에요."},{"kind":"english","head":"답안 문장","en":"활성화 함수 h = f(z) 의 **야코비안(Jacobian)**은 대각 행렬 diag(f'(z)) 이다. hᵢ 가 zᵢ 에만 의존하기 때문이며, 이 대각 행렬과의 곱은 **원소별 곱(Hadamard Product)**와 같다.","ko":"네 블록 가운데 설명형 문제로 가장 나오기 좋은 것이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["Wx + b 를 x 로 미분하면 W, W 로 미분하면 x 쪽이 나와요. 무엇으로 미분하는지 먼저 확인해요.","슬라이드 왼쪽 칸은 h, z 를 n 칸으로, 레고 그림은 m 칸(m×1)으로 적었어요. 글자만 다를 뿐 같은 이야기예요."]}]},{"p":22,"title":"풀이 예: 준비","terms":["Word Vector","Embedding","Named Entity Recognition (NER)","Activation Function","Nonlinearity","Hidden Layer"],"pass1":[{"kind":"say","lines":["이제 실제로 한 번 풀어 봐요. 1부의 **개체명 인식(Named Entity Recognition (NER))** 점수기를 아주 작게 줄인 것이에요.","순서는 x → z → h → s, 네 칸이에요.","미분하기 전에 먼저 할 일은 조각마다 이름과 크기를 적는 것이에요."]},{"kind":"points","head":"네 칸 흐름","items":["x: 단어 창을 이어 붙인 입력 벡터(**단어 벡터(Word Vector)**, 곧 **임베딩(Embedding)**들)","z = Wx + b: 곱하고 더하기","h = f(z): **활성화 함수(Activation Function)** 씌우기, 곧 **비선형성(Nonlinearity)** 넣기","s = uᵀh: 숫자 하나짜리 점수"]}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["Our NER scorer, stripped to essentials","우리 NER 점수기의 뼈대만 남긴 것"],["Break the network into simple pieces","신경망을 단순한 조각으로 나눠요"],["define every variable, track every shape","변수마다 이름을 붙이고, 크기를 빠짐없이 적어요"],["same story with the loss J","손실 J 로 해도 같은 이야기예요"],["name the pieces before touching the calculus","미분에 손대기 전에 조각 이름부터"]]},{"kind":"compare","head":"조각과 크기","cols":["기호","뜻","크기(shape)"],"rows":[["x","창 벡터(입력)","n×1"],["W","**은닉층(Hidden Layer)** 가중치","m×n"],["b","편향 항","m×1"],["z, h","중간값, 활성화 뒤 값","m×1"],["u","점수 가중치","m×1"],["s","점수","1×1 (숫자 하나)"]]},{"kind":"steps","head":"목표: 기울기 세 개","steps":["∂s/∂b: 점수가 b 에 얼마나 민감한가","∂s/∂W: 점수가 W 에 얼마나 민감한가","∂s/∂x: 점수가 입력 **단어 벡터(Word Vector)**에 얼마나 민감한가"],"answer":"이 셋을 구하면 b, W, 그리고 단어 벡터까지 고칠 수 있어요."},{"kind":"check","q":"이 예에서 점수 s 의 크기는?","choices":["m×1","1×1, 숫자 하나","m×n"],"a":1,"why":"s = uᵀh 는 (1×m)(m×1) = 1×1, 숫자 하나예요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.204,"y":0.165,"w":0.468,"h":0.247,"say":"레고 그림 아래에 z = Wx (m×1), z = Wx + b (m×1), h = f(z) (m×1), s = uᵀh (1×1) 가 적혀 있어요."},{"x":0.232,"y":0.533,"w":0.532,"h":0.076,"say":"세 식: s = uᵀh, h = f(z), z = Wx + b."},{"x":0.061,"y":0.685,"w":0.696,"h":0.041,"say":"x 는 창 벡터, W 와 b 는 은닉층, f 는 비선형 함수, u 는 점수 가중치, s 는 점수예요."},{"x":0.061,"y":0.744,"w":0.539,"h":0.039,"say":"목표는 ∂s/∂b, ∂s/∂W, ∂s/∂x. 변수와 크기를 모두 적어요."},{"x":0.061,"y":0.796,"w":0.536,"h":0.039,"say":"간단히 하려고 점수 s 를 미분해요. 손실 J 로 해도 같아요."}]},{"kind":"formula","head":"풀이 예의 세 식","tex":"s = u^T h, \\quad h = f(z), \\quad z = Wx + b","parts":[{"sym":"z = Wx + b","say":"입력 x 에 W 를 곱하고 b 를 더해요"},{"sym":"h = f(z)","say":"z 에 **활성화 함수(Activation Function)**를 칸마다 씌워요"},{"sym":"u^T h","say":"h 의 칸마다 u 를 곱해 모두 더한 점곱(내적)"},{"sym":"s","say":"마지막 점수, 숫자 하나"}],"whole":"x 에서 시작해 z, h 를 거쳐 **개체명 인식(Named Entity Recognition (NER))** 점수 s 가 나와요. f 는 **비선형성(Nonlinearity)**을 넣어요."},{"kind":"steps","head":"작은 숫자로 순전파","given":"n = 3 (입력 칸), m = 2 (은닉 칸)","steps":["x = [1, 2, 3], W = [[1, 0, 1], [-1, 1, -2]], b = [0, 1], u = [2, 3], f = ReLU","Wx: 1행 1×1 + 0×2 + 1×3 = 4, 2행 -1×1 + 1×2 + (-2)×3 = -5 → [4, -5]","z = Wx + b = [4 + 0, -5 + 1] = [4, -4]","h = ReLU(z) = [4, 0] (음수는 0)","s = uᵀh = 2×4 + 3×0 = 8"],"answer":"s = 8. 크기는 x (3×1), W (2×3), z, h, b, u (2×1), s 는 숫자 하나."},{"kind":"prof","when":"3주차 월요일 1교시","lines":["입력 x 에 W 를 곱하고 b 를 더해 z 가 나오고, 활성화를 씌워 h, 여기에 u 를 한 번 더 곱해 점수 s 가 나와요.","목표는 x, W, b 가 점수 s 에 각각 얼마나 영향을 줬는지 구하는 거예요.","x 가 단어 벡터라면 x 에 대한 미분도 구해야 하는데, 얼릴지 말지는 마음대로예요.","x → z → h → s 이 흐름을 기억하면 뒤의 역전파를 쉽게 볼 수 있어요."]},{"kind":"say","lines":["실습에서는 N3L p.5~6 에서 바로 이 네트워크(x 5칸, W 3×5, f = tanh)를","손 계산식과 autograd 로 각각 미분해 결과가 같은지 비교해요."]}],"pass4":[{"kind":"check","q":"x 가 5칸(5×1), 은닉 칸이 3개일 때 W 의 크기는? (실습 N3L p.3)","choices":["5×3","3×5","3×1"],"a":1,"why":"z = Wx 가 3칸이 되려면 (3×5)(5×1) = (3×1). W 는 3×5 예요."},{"kind":"english","head":"답안 문장","en":"미분을 시작하기 전에 s = uᵀh, h = f(z), z = Wx + b 처럼 계산을 단순한 조각으로 나누고 각 변수의 shape 을 적는다.","ko":"슬라이드의 'Step 1 of every derivation' 이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["여기서는 편하게 점수 s 를 미분하지만, 실제 학습에서는 손실 J 를 미분해요. 방법은 똑같아요.","h 는 은닉층 값이에요. p.32 의 수치 기울기 식에 나오는 h(아주 작은 수)와 다른 것이에요."]}]},{"p":23,"title":"풀이 예: 사슬로 풀고, 다시 쓰기","terms":["Backpropagation","Chain Rule","Outer Product","Hadamard Product","Error Signal","Upstream Gradient"],"pass1":[{"kind":"say","lines":["점수 s 가 b 에 얼마나 민감한지는 **연쇄 법칙(Chain Rule)**으로 세 조각을 곱하면 나와요.","그다음 W 에 대한 미분을 구하면, 앞의 두 조각이 똑같아요.","그 똑같은 부분에 이름을 붙여요. δ(델타), **오차 신호(Error Signal)**예요.","한 번 구해서 계속 다시 쓰는 것, 이것이 **역전파(Backpropagation)**의 씨앗이에요."]},{"kind":"analogy","head":"틀린 책임 나눠 주기","scene":"반 전체 점수가 낮게 나왔어요. 담임이 조장에게 책임 몫을 한 번 알려 주면, 조장은 그 몫으로 조원들에게 다시 나눠 줘요.","map":[["담임이 조장에게 알려 준 책임 몫","δ (**오차 신호(Error Signal)**)"],["조장이 같은 몫을 여러 조원에게 다시 씀","δ 를 b, W 에 다시 쓰기"],["뒤에서 앞으로 책임 전달","**역전파(Backpropagation)**"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["Chain, then Reuse","사슬(연쇄 법칙)로 풀고, 그다음 다시 쓰기"],["three Jacobians from our pocket, multiplied","주머니 속 야코비안 세 개를 곱해요"],["the first two factors are IDENTICAL","앞의 두 조각이 똑같아요"],["the upstream gradient / error signal","**상류 기울기(Upstream Gradient)** / **오차 신호(Error Signal)**"],["compute δ once, reuse it everywhere","δ 를 한 번 구해 어디서나 다시 써요"]]},{"kind":"points","head":"용어 뜻","items":["**오차 신호(Error Signal)** δ: 출력 쪽에서 z 까지 흘러온 기울기, 즉 ∂s/∂z.","**상류 기울기(Upstream Gradient)**: 위(출력 쪽)에서 내려온 기울기. δ 가 바로 그것이에요.","**원소별 곱(Hadamard Product)** ⊙: 같은 자리끼리 곱하기.","**외적(Outer Product)**: 세로 벡터 × 가로 벡터로 표를 만드는 곱. ∂s/∂W 가 이 모양이에요."]},{"kind":"steps","head":"b 와 W 의 미분이 어떻게 겹치나","steps":["∂s/∂b = ∂s/∂h × ∂h/∂z × ∂z/∂b","∂s/∂W = ∂s/∂h × ∂h/∂z × ∂z/∂W","앞의 두 조각 ∂s/∂h × ∂h/∂z 가 같아요. 이것이 δ = ∂s/∂z","그래서 ∂s/∂b = δ × (b 조각), ∂s/∂W = δ × (W 조각)"],"answer":"마지막 조각만 다르고, 앞부분 δ 는 공유해요."},{"kind":"check","q":"δ(델타)는 무엇의 미분일까요?","choices":["s 를 z 로 미분한 것","s 를 b 로 미분한 것","h 를 x 로 미분한 것"],"a":0,"why":"δ = ∂s/∂h × ∂h/∂z = ∂s/∂z 예요. z 까지 흘러온 기울기예요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.071,"y":0.19,"w":0.539,"h":0.095,"say":"세 식에 색이 칠해져 있어요. 파랑 h, 주황 z, 빨강 W, 초록 b."},{"x":0.071,"y":0.4,"w":0.55,"h":0.155,"say":"∂s/∂b = 파랑 × 주황 × 초록 = uᵀ × diag(f'(z)) × I = uᵀ ⊙ f'(z)ᵀ, 이것을 δ 라 불러요."},{"x":0.696,"y":0.171,"w":0.261,"h":0.451,"say":"오른쪽 상자는 p.21 의 주머니 속 야코비안이에요. 같은 색끼리 짝이에요."},{"x":0.132,"y":0.654,"w":0.393,"h":0.042,"say":"앞의 두 조각을 δ, 상류 기울기 또는 오차 신호라고 불러요."},{"x":0.275,"y":0.761,"w":0.45,"h":0.082,"say":"∂s/∂W = δᵀxᵀ. 세로 × 가로의 외적이에요."}]},{"kind":"formula","head":"b 에 대한 기울기","tex":"\\frac{\\partial s}{\\partial b} = \\frac{\\partial s}{\\partial h}\\frac{\\partial h}{\\partial z}\\frac{\\partial z}{\\partial b} = u^T \\mathrm{diag}(f'(z))\\, I = u^T \\odot f'(z)^T \\equiv \\delta","parts":[{"sym":"\\frac{\\partial s}{\\partial h} = u^T","say":"점수 블록의 미분"},{"sym":"\\frac{\\partial h}{\\partial z} = \\mathrm{diag}(f'(z))","say":"활성화 블록의 미분(대각 행렬)"},{"sym":"\\frac{\\partial z}{\\partial b} = I","say":"더하기 블록의 미분(단위 행렬, 곱해도 그대로)"},{"sym":"u^T \\odot f'(z)^T","say":"대각 행렬 곱 = 원소별 곱"},{"sym":"\\delta","say":"이 결과에 붙인 이름, **오차 신호(Error Signal)**"}],"whole":"b 에 대한 기울기는 δ 그 자체예요."},{"kind":"formula","head":"W 에 대한 기울기","tex":"\\frac{\\partial s}{\\partial W} = \\delta^T x^T","parts":[{"sym":"\\delta","say":"앞에서 구한 오차 신호(가로 1×m)"},{"sym":"\\delta^T","say":"세로로 세운 δ (m×1)"},{"sym":"x^T","say":"가로로 눕힌 x (1×n)"},{"sym":"\\delta^T x^T","say":"세로 × 가로 = **외적(Outer Product)**, W 와 같은 m×n"}],"whole":"δ 를 다시 쓰고, 끝에 x 만 붙이면 W 의 기울기예요."},{"kind":"steps","head":"숫자로: δ, ∂s/∂b, ∂s/∂W","steps":["p.22 값: z = [4, -4], u = [2, 3], x = [1, 2, 3], f = ReLU","f'(z) = [1, 0] (z₁ 양수, z₂ 음수)","δ = u ⊙ f'(z) = [2×1, 3×0] = [2, 0]","∂s/∂b = δ = [2, 0]","∂s/∂W = δᵀxᵀ: 1행 2 × [1, 2, 3] = [2, 4, 6], 2행 0 × [1, 2, 3] = [0, 0, 0]","확인: b₁ 을 0.1 올리면 s 가 8 → 8.2, 0.2 ÷ 0.1 = 2 (맞음)"],"answer":"δ = [2, 0], ∂s/∂b = [2, 0], ∂s/∂W = [[2, 4, 6], [0, 0, 0]] (W 와 같은 2×3)."},{"kind":"prof","when":"3주차 월요일 1교시","lines":["편미분도 원래 분자, 분모처럼 생각하면 안 되지만, 우리 수학 레벨에서는 그렇게 생각해도 거의 다 맞아요.","이렇게 약분된다고 보면 체인 룰도 어려울 게 하나도 없어요."]},{"kind":"prof","when":"3주차 월요일 2교시","lines":["이 uᵀ 와 f'(z) 의 원소별 곱을 δ 라는 에러 시그널로 정의할 거예요.","s 를 W 로 미분할 때도 앞의 파란색, 주황색까지는 똑같아요. 그게 δ 예요.","z 를 W 로 미분하면 x 라서, δ 에 x 를 곱한 게 답이에요. 트랜스포즈는 차원을 맞추려고 붙은 거예요."]},{"kind":"bg","src":"기초 다지기 3단원 (wb-3 행렬과 행렬 곱, shape)","lines":["행렬 곱의 규칙: (a×b)(b×c) = (a×c). 가운데 b 가 같아야 곱할 수 있어요.","(2×1) 세로 × (1×3) 가로 = (2×3) 표. 외적도 이 규칙 그대로예요."]},{"kind":"say","lines":["실습에서는 N3L p.6 에서 delta = u * (1 - tanh(z)²), dW = torch.outer(delta, x) 로","이 식을 그대로 코드로 짜서 autograd 결과와 비교해요."]}],"pass4":[{"kind":"exam","src":"예상 문제","q":"s = uᵀh, h = ReLU(z), z = Wx + b 에서 u = [1, 4], z = [-1, 2], x = [2, 5] 이다. δ 와 ∂s/∂W 를 구하시오.","qko":"오차 신호 δ 와 W 의 기울기를 숫자로 구하는 문제예요.","solve":["ReLU 미분: z = [-1, 2] → f'(z) = [0, 1]","δ = u ⊙ f'(z) = [1×0, 4×1] = [0, 4]","∂s/∂W = δᵀxᵀ: 1행 0 × [2, 5] = [0, 0], 2행 4 × [2, 5] = [8, 20]"],"answer":"δ = [0, 4], ∂s/∂W = [[0, 0], [8, 20]]"},{"kind":"english","head":"답안 문장","en":"∂s/∂b 와 ∂s/∂W 의 연쇄 법칙 식은 앞부분 ∂s/∂h × ∂h/∂z 를 공유하므로, 이를 **오차 신호(Error Signal)** δ 로 한 번 계산해 재사용한다. 이 재사용이 **역전파(Backpropagation)**의 핵심이다.","ko":"'한 번 구해 여러 번 쓴다' 가 역전파가 빠른 이유예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드는 δ 를 가로(1×m)로 두고 ∂s/∂W = δᵀxᵀ 로 써요. 실습 코드는 δ 를 세로로 두고 δxᵀ 로 써요. 결과 shape 은 둘 다 W 와 같아요.","슬라이드 괄호의 'n × 1 times 1 × m' 은 레고 그림(p.22)과 n, m 글자가 뒤바뀌어 있어요. 글자보다 'W 와 같은 크기' 를 기억해요."]}]},{"p":24,"title":"풀이 예: 세 번째 기울기","terms":["Gradient","Gradient Descent","Learning Rate","Word Vector","Embedding","word2vec","Error Signal"],"pass1":[{"kind":"say","lines":["남은 기울기 하나는 입력 x, 즉 단어 벡터에 대한 것이에요.","여기서도 똑같은 δ 를 다시 써요. 이번엔 x 대신 W 를 곱해요.","그래서 **단어 벡터(Word Vector)**도 한 걸음씩 고쳐져요. 딥러닝이 '특징을 스스로 배운다' 는 말의 뜻이에요."]},{"kind":"compare","head":"기울기 세 개, δ 하나","cols":["무엇","δ 에 붙는 것","결과"],"rows":[["b","없음","δ"],["W","x","δᵀxᵀ"],["x (단어 벡터)","W","Wᵀδᵀ"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["the gradient that flows into the WORD VECTORS","단어 벡터로 흘러 들어가는 기울기"],["same δ again, now multiplied by W instead of by x","같은 δ 를 다시, 이번엔 x 대신 W 를 곱해요"],["three gradients, one shared δ","기울기 셋, 공유하는 δ 하나"],["the word vectors keep learning","단어 벡터가 계속 배워요"],["A2 asks for the word2vec versions","과제 2 는 **word2vec** 버전을 구하라고 해요"]]},{"kind":"points","head":"용어 뜻","items":["**임베딩(Embedding)**: 토큰을 벡터로 바꾼 것. 여기서는 입력 x 예요.","∇ₓ: x 에 대한 **기울기(Gradient)**. x 와 같은 크기예요.","x ← x - α∇ₓ: 단어 벡터에도 **경사 하강법(Gradient Descent)** 한 걸음을 적용해요."]},{"kind":"check","q":"∂s/∂x 에서 δ 에 곱해지는 것은?","choices":["x","W","b"],"a":1,"why":"z = Wx + b 를 x 로 미분하면 W 라서, δ 에 W 가 붙어요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.277,"w":0.543,"h":0.038,"say":"남은 하나: ∂s/∂x, 단어 벡터로 흘러 들어가는 기울기예요."},{"x":0.3,"y":0.324,"w":0.4,"h":0.148,"say":"파랑 × 주황 × 초록 = δW, 그리고 x 와 같은 세로 모양으로 바꾸면 ∇ₓ = Wᵀδᵀ."},{"x":0.061,"y":0.499,"w":0.664,"h":0.041,"say":"같은 δ 를 다시 써요. 기울기 셋이 δ 하나를 공유해요."},{"x":0.389,"y":0.628,"w":0.232,"h":0.07,"say":"단어 벡터 업데이트: x ← x - α Wᵀδᵀ."},{"x":0.061,"y":0.734,"w":0.657,"h":0.038,"say":"그래서 딥러닝은 특징을 스스로 배워요. 2주차 벡터가 계속 좋아져요."}]},{"kind":"formula","head":"x 에 대한 기울기","tex":"\\frac{\\partial s}{\\partial x} = \\frac{\\partial s}{\\partial h}\\frac{\\partial h}{\\partial z}\\frac{\\partial z}{\\partial x} = \\delta W \\;\\longrightarrow\\; \\nabla_x = W^T \\delta^T","parts":[{"sym":"\\frac{\\partial s}{\\partial h}\\frac{\\partial h}{\\partial z}","say":"앞의 두 조각, 곧 δ"},{"sym":"\\frac{\\partial z}{\\partial x} = W","say":"곱하기 블록을 x 로 미분하면 W"},{"sym":"\\delta W","say":"가로 모양(1×n)의 결과"},{"sym":"W^T \\delta^T","say":"x 와 같은 세로 모양(n×1)으로 세운 것"}],"whole":"δ 에 W 를 곱하면 x 의 기울기, 모양은 x 에 맞춰요."},{"kind":"formula","head":"단어 벡터 업데이트","tex":"x \\leftarrow x - \\alpha W^T \\delta^T","parts":[{"sym":"x","say":"입력 **단어 벡터(Word Vector)**"},{"sym":"\\alpha","say":"**학습률(Learning Rate)**"},{"sym":"W^T \\delta^T","say":"x 에 대한 기울기"},{"sym":"\\leftarrow","say":"오른쪽 값으로 바꿔 넣어요"}],"whole":"단어 벡터도 W, b 처럼 한 걸음 고쳐요."},{"kind":"steps","head":"숫자로: ∂s/∂x 와 한 걸음","steps":["δ = [2, 0], W = [[1, 0, 1], [-1, 1, -2]]","Wᵀδᵀ: 1칸 1×2 + (-1)×0 = 2, 2칸 0×2 + 1×0 = 0, 3칸 1×2 + (-2)×0 = 2","∂s/∂x = [2, 0, 2] (x 와 같은 3칸)","α = 0.1 로 한 걸음: x = [1, 2, 3] - 0.1 × [2, 0, 2] = [0.8, 2, 2.8]","새 x 로 다시 계산: z = [3.6, -3.4], h = [3.6, 0], s = 7.2"],"answer":"∂s/∂x = [2, 0, 2]. 한 걸음 뒤 s 는 8 → 7.2 로 줄었어요(s 가 벌점이었다면 줄어든 것)."},{"kind":"prof","when":"3주차 월요일 2교시","lines":["x 를 얼리지 않고 입력 벡터도 학습할 수 있어요. 그때는 s 를 x 로 미분해요.","파랑과 주황은 앞과 똑같아서 δ 이고, z 를 x 로 미분하면 W 라서 δW 가 돼요.","트랜스포즈가 신경 쓰이면, 모든 벡터를 n×1 로 시작해서 차원을 맞추려고 붙인다고 이해하면 돼요.","이게 바로 역전파의 핵심 원리예요."]},{"kind":"say","lines":["과제와 이어지는 부분이에요. 과제 2 는 이 세 기울기의 word2vec 버전을 손으로 유도하라고 해요.","실습 N3L p.6 에서 dx = W.T @ delta 로 이 식을 코드로 확인해요."]}],"pass4":[{"kind":"check","q":"W 가 (3×5), δ 가 3칸일 때 ∂s/∂x 의 크기는?","choices":["(3,)","(5,)","(3, 5)"],"a":1,"why":"Wᵀ(5×3) × δ(3칸) = 5칸. x 와 같은 크기예요."},{"kind":"english","head":"답안 문장","en":"∂s/∂b = δ, ∂s/∂W = δᵀxᵀ, ∂s/∂x = Wᵀδᵀ 이고 세 기울기는 **오차 신호(Error Signal)** δ 를 공유한다. 입력 **임베딩(Embedding)**도 x ← x - αWᵀδᵀ 로 학습된다.","ko":"세 식을 한 줄로 외우면 과제 2 에도 바로 써요.","tip":"'b 는 δ, W 는 δ에 x, x 는 δ에 W'."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["∂s/∂W 에는 x 가, ∂s/∂x 에는 W 가 붙어요. 서로 맞바꿔 붙는 것이에요(곱하기 노드의 성질, p.30).","미리 학습된 단어 벡터(예: GloVe)는 얼려 둘 수도 있어요. x 를 업데이트할지는 선택이에요."]}]},{"p":25,"title":"왜 전치(T)가 붙나: shape 으로 검사하기","terms":["Tensor","Shape","Transpose"],"pass1":[{"kind":"say","lines":["식마다 붙는 T(**전치(Transpose)**)가 헷갈리죠.","솔직한 답은 '그래야 크기가 맞기 때문' 이에요.","그래서 거꾸로 이용해요. 기호 밑에 크기를 적어 보면, 식이 맞는지 공짜로 검사돼요."]},{"kind":"figure","head":"크기가 맞는지 보기","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"20\" y=\"30\" font-size=\"15\" text-anchor=\"start\" class=\"tb\">∂s/∂W = δᵀxᵀ 는 W 와 같은 (3×5)<\/text><rect x=\"40\" y=\"60\" width=\"20\" height=\"60\" rx=\"2\" class=\"n3\"/><text x=\"50\" y=\"140\" font-size=\"14\" text-anchor=\"middle\" class=\"t\">δᵀ<\/text><text x=\"50\" y=\"158\" font-size=\"13\" text-anchor=\"middle\" class=\"tm\">(3×1)<\/text><text x=\"85\" y=\"95\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">×<\/text><rect x=\"105\" y=\"80\" width=\"100\" height=\"20\" rx=\"2\" class=\"n3\"/><text x=\"155\" y=\"140\" font-size=\"14\" text-anchor=\"middle\" class=\"t\">xᵀ<\/text><text x=\"155\" y=\"158\" font-size=\"13\" text-anchor=\"middle\" class=\"tm\">(1×5)<\/text><text x=\"228\" y=\"95\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b1\">=<\/text><rect x=\"250\" y=\"60\" width=\"100\" height=\"60\" rx=\"2\" class=\"n2 b1\"/><text x=\"300\" y=\"95\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b1\">3×5<\/text><text x=\"300\" y=\"140\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">W 와 같은 모양<\/text><text x=\"20\" y=\"205\" font-size=\"14\" text-anchor=\"start\" class=\"t b2\">Wᵀ (5×3) × δᵀ (3×1) = (5×1) = x 와 같아요<\/text><text x=\"20\" y=\"240\" font-size=\"14\" text-anchor=\"start\" class=\"tb b3\">가운데 숫자(3)가 같아야 곱할 수 있어요<\/text><\/svg>","caption":"δᵀ(3×1) × xᵀ(1×5) = (3×5) 로 W 와 크기가 같아요. 가운데 숫자가 같아야 곱해져요.","builds":3}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["Why the Transposes?","왜 전치가 붙을까?"],["because that is what makes the dimensions work out","그래야 차원(크기)이 맞으니까요"],["a feature, not a bug","결함이 아니라 쓸모 있는 기능이에요"],["a free correctness test","공짜 정답 검사"],["print(tensor.shape) is the single most useful debugging line","print(tensor.shape) 가 딥러닝에서 가장 쓸모 있는 디버깅 한 줄"]]},{"kind":"points","head":"용어 뜻","items":["**모양(Shape)**: 몇 행 몇 열인지. (3, 5) 는 3행 5열이에요.","**전치(Transpose)**: 행과 열 바꾸기. (3×1) → (1×3).","곱셈 규칙: (a×b)(b×c) = (a×c). 가운데가 같아야 곱할 수 있어요(conform).","**텐서(Tensor)**: PyTorch 의 숫자 묶음. tensor.shape 로 크기를 봐요."]},{"kind":"check","q":"(2×3) 행렬과 (2×1) 벡터를 이 순서로 곱할 수 있나요?","choices":["있어요, 결과는 (2×1)","없어요, 가운데 3 과 2 가 달라요","있어요, 결과는 (3×1)"],"a":1,"why":"(2×3)(2×1) 은 가운데 3 ≠ 2 라서 곱할 수 없어요. 전치가 잘못 붙었다는 신호예요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.736,"h":0.038,"say":"솔직한 답: 차원이 맞게 해 주니까. 결함이 아니라 기능이에요."},{"x":0.236,"y":0.368,"w":0.439,"h":0.057,"say":"δᵀxᵀ: (n×1)(1×m) = n×m = W 의 크기 (맞음)"},{"x":0.236,"y":0.459,"w":0.439,"h":0.058,"say":"Wᵀδᵀ: (m×n)(n×1) = m×1 = x 의 크기 (맞음)"},{"x":0.061,"y":0.561,"w":0.679,"h":0.039,"say":"기호마다 밑에 크기를 쓰고 사슬이 이어지는지 봐요. 안 맞으면 전치가 잘못된 거예요."},{"x":0.061,"y":0.657,"w":0.679,"h":0.041,"say":"코드에서는 print(tensor.shape) 한 줄이 가장 쓸모 있어요."}]},{"kind":"formula","head":"shape 검사 두 줄","tex":"\\delta^T x^T: (n\\times 1)(1\\times m) = n\\times m = \\mathrm{shape}(W), \\quad W^T\\delta^T: (m\\times n)(n\\times 1) = m\\times 1 = \\mathrm{shape}(x)","parts":[{"sym":"(n\\times 1)(1\\times m)","say":"세로 × 가로. 가운데 1 이 같아 곱할 수 있어요"},{"sym":"n\\times m = \\mathrm{shape}(W)","say":"결과가 W 와 같은 크기"},{"sym":"(m\\times n)(n\\times 1)","say":"가운데 n 이 같아 곱할 수 있어요"},{"sym":"m\\times 1 = \\mathrm{shape}(x)","say":"결과가 x 와 같은 크기"}],"whole":"기울기의 크기가 원래 변수의 크기와 같으면 통과예요."},{"kind":"steps","head":"실습 크기로 검사하기 (N3L p.3 과 같은 크기)","steps":["x (5칸), W (3×5), b, z, h, u (3칸), s 는 숫자 하나","δ 는 z 와 같은 3칸. 세로로 (3×1)","∂s/∂W = δ(3×1) × xᵀ(1×5) = (3×5) → W 와 같아요 (맞음)","∂s/∂x = Wᵀ(5×3) × δ(3×1) = (5×1) → x 와 같아요 (맞음)","잘못 쓴 예: x(5×1) × δᵀ(1×3) = (5×3) → W(3×5) 와 달라요 (틀림)","또 잘못 쓴 예: W(3×5) × δ(3×1) → 가운데 5 ≠ 3, 곱할 수조차 없어요 (틀림)"],"answer":"크기만 적어 봐도 틀린 식 두 개를 코드 돌리기 전에 잡아요."},{"kind":"prof","when":"3주차 월요일 2교시","lines":["왜 트랜스포즈가 계속 붙지? 실용적인 답은, 결과 shape 이 우리가 미분하는 변수의 shape 과 같아야 해서예요.","수식을 다 외울 필요는 없고, shape 을 맞추기 위해 트랜스포즈를 취한다고 보면 돼요.","오늘 실습에서도 shape 을 계속 보면서 맞춰 줘야 코드가 에러 없이 돌아가요. 가장 빠른 점검 팁이에요."]},{"kind":"bg","src":"기초 다지기 3단원 (wb-3 행렬과 행렬 곱, shape)","lines":["전치와 행렬 곱의 크기 규칙은 기초 다지기 3단원에 있어요.","(3,5)@(5,) → (3,) 같은 PyTorch 표기도 거기서 연습해요."]},{"kind":"say","lines":["실습 N3L p.3 에서 x, W, b, z, h, u, s 의 shape 을 한 번에 출력해 봐요.","결과는 x (5,), W (3, 5), b, z, h, u (3,), s () 예요."]}],"pass4":[{"kind":"check","q":"∂s/∂W 를 x δᵀ 로 잘못 쓰면 크기는? (x 5칸, δ 3칸)","choices":["(3, 5)","(5, 3)","곱할 수 없음"],"a":1,"why":"(5×1)(1×3) = (5×3). W 는 (3×5) 라서 틀린 식이라는 걸 바로 알 수 있어요."},{"kind":"english","head":"답안 문장","en":"역전파 식의 **전치(Transpose)**는 기울기의 **모양(Shape)**이 해당 변수의 shape 과 같아지도록 차원을 맞추기 위해 붙는다. 그래서 각 기호 밑에 shape 을 적어 곱셈이 이어지는지 확인하면 식의 오류를 찾을 수 있다.","ko":"교수님: 전치 위치를 외우기보다 shape 을 맞춘다고 생각하라."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["이 쪽 슬라이드는 W 를 n×m, x 를 m×1 로 적었어요. p.22 레고 그림(W 는 m×n, x 는 n×1)과 n, m 이 뒤바뀌었지만 결론은 같아요.","PyTorch 1차원 벡터는 (5,) 처럼 세로, 가로 구별이 없어요. 그래서 실습은 δxᵀ 대신 torch.outer 를 써요."]}]},{"p":26,"title":"shape 장부 정리 규칙","terms":["Chain Rule","Gradient","Learning Rate","Parameter","Shape"],"pass1":[{"kind":"say","lines":["규칙은 딱 하나예요.","\"파라미터의 기울기는 파라미터와 같은 크기다.\"","W 가 3×5 칸이면, W 의 기울기도 3×5 칸이에요. 칸마다 짝이 있어야 한 칸씩 고칠 수 있으니까요."]},{"kind":"analogy","head":"성적표와 첨삭표","scene":"3×5 칸 성적표를 고치려면 첨삭표도 똑같은 3×5 칸이어야 칸마다 고칠 수 있어요.","map":[["성적표 W","**파라미터(Parameter)**"],["첨삭표","∂J/∂W (**기울기(Gradient)**)"],["칸 수가 같아야 함","같은 **모양(Shape)**"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["the gradient of a parameter has the SAME SHAPE as the parameter","파라미터의 기울기는 파라미터와 같은 shape"],["derive in Jacobian form, reshape to convention at the end","야코비안 꼴로 유도하고, 마지막에 약속된 shape 으로 바꿔요"],["Sanity check that catches 90% of mistakes","실수의 90% 를 잡는 점검"],["if the shapes cannot chain, the math is wrong","shape 이 이어지지 않으면 수식이 틀린 거예요"]]},{"kind":"steps","head":"장부 정리 순서","steps":["**연쇄 법칙(Chain Rule)**으로 야코비안 꼴 식을 세워요.","기호마다 밑에 shape 을 적어요.","곱셈마다 가운데 숫자가 같은지 봐요.","마지막 결과를 파라미터와 같은 shape 으로 맞춰요(필요하면 전치)."],"answer":"계산보다 먼저 shape 부터 확인해요."},{"kind":"check","q":"W 가 (4×10) 이면 ∂J/∂W 의 칸 수는?","choices":["4","10","40"],"a":2,"why":"W 와 같은 4×10 이라서 40 칸이에요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.611,"h":0.042,"say":"약속: 파라미터의 기울기는 파라미터와 같은 shape."},{"x":0.061,"y":0.247,"w":0.146,"h":0.067,"say":"업데이트 W ← W - α ∂J/∂W. 빼려면 두 표의 크기가 같아야 해요."},{"x":0.079,"y":0.324,"w":0.518,"h":0.038,"say":"W 가 n×m 이면 ∂J/∂W 도 n×m. 그래서 외적 δᵀxᵀ 꼴이에요."},{"x":0.061,"y":0.383,"w":0.561,"h":0.039,"say":"실전 요령: 야코비안 꼴로 유도하고, 마지막에 약속된 shape 으로."},{"x":0.061,"y":0.442,"w":0.539,"h":0.041,"say":"실수의 90% 를 잡는 점검: 차원이 맞는가?"}]},{"kind":"formula","head":"W 업데이트","tex":"W \\leftarrow W - \\alpha \\frac{\\partial J}{\\partial W}","parts":[{"sym":"W","say":"가중치 행렬(예: 3×5)"},{"sym":"\\alpha","say":"**학습률(Learning Rate)**"},{"sym":"\\frac{\\partial J}{\\partial W}","say":"손실을 W 로 미분한 **기울기(Gradient)**, W 와 같은 3×5"},{"sym":"-","say":"칸마다 같은 자리끼리 빼요"}],"whole":"같은 크기의 두 표를 칸마다 빼는 것이라 크기가 같아야 해요."},{"kind":"steps","head":"칸 수 세기","steps":["실습 크기: W (3×5) → 기울기도 3×5 = 15 칸","b (3칸) → 기울기도 3칸","교수님 예: 입력 500, 출력 300 → W 는 500 × 300 = 150,000 칸","그러면 기울기도 150,000 개가 생겨요"],"answer":"기울기 개수 = 파라미터 개수. 칸마다 짝이 있어요."},{"kind":"prof","when":"3주차 월요일 2교시","lines":["어떤 파라미터의 그레디언트든 기존 파라미터와 같은 shape 을 가져야 한다, 이것만 기억하시면 됩니다.","shape 이 이렇게 앞으로 흐를 때 뒤로 흐른다, 이렇게 보시면 돼요.","트랜스포즈가 어디 붙는지 무작정 외우기보다, 이 변수에 적용되려면 shape 이 어떻게 돼야 하는지 먼저 생각해 보세요."]},{"kind":"bg","src":"기초 다지기 3단원 (wb-3 행렬과 행렬 곱, shape)","lines":["행렬 빼기는 같은 자리 칸끼리 빼는 것이라 두 행렬의 shape 이 같아야 해요.","기초 다지기 3단원에서 shape 표기를 연습해요."]},{"kind":"say","lines":["실습 N3L p.6 은 dW, db, dx 의 shape 이 W.grad, b.grad, x.grad 와 같은지 출력해 확인해요.","결과: dW (3, 5), db (3,), dx (5,) 로 모두 짝이 맞아요."]}],"pass4":[{"kind":"check","q":"다음 중 shape 규칙에 맞는 것은? (W 가 3×5)","choices":["∂J/∂W 가 (5×3)","∂J/∂W 가 (3×5)","∂J/∂W 가 (3×1)"],"a":1,"why":"기울기는 파라미터와 같은 shape 이라서 (3×5) 예요."},{"kind":"english","head":"답안 문장","en":"파라미터의 **기울기(Gradient)**는 파라미터와 같은 **모양(Shape)**을 가져야 W ← W - α∂J/∂W 처럼 원소별로 업데이트할 수 있다. shape 이 이어지지 않으면 유도가 틀린 것이다.","ko":"교수님이 '이것만 기억하라' 고 한 문장이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["야코비안 꼴 그대로면 가로, 세로가 뒤집혀 나올 수 있어요. 마지막에 파라미터 shape 으로 맞추는 단계를 잊지 마요.","슬라이드는 여기서 W 를 n×m 이라 적었어요. 글자 대신 '파라미터와 같다' 만 기억하면 돼요."]}]},{"p":27,"title":"계산 그래프","terms":["Computation Graph","Forward Pass","Node"],"pass1":[{"kind":"say","lines":["컴퓨터는 신경망을 **계산 그래프(Computation Graph)**로 봐요.","동그라미 하나하나가 **노드(Node)**, 입력값이거나 곱하기, 더하기 같은 연산이에요.","왼쪽에서 오른쪽으로 값을 차례로 구하는 것이 **순전파(Forward Pass)**예요."]},{"kind":"figure","head":"풀이 예를 그래프로","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"40\" cy=\"75\" r=\"20\" class=\"n3\"/><text x=\"40\" y=\"80\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">x<\/text><circle cx=\"40\" cy=\"195\" r=\"20\" class=\"n3\"/><text x=\"40\" y=\"200\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">W<\/text><circle cx=\"215\" cy=\"45\" r=\"18\" class=\"n3\"/><text x=\"215\" y=\"50\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">b<\/text><circle cx=\"385\" cy=\"45\" r=\"18\" class=\"n3\"/><text x=\"385\" y=\"50\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">u<\/text><line x1=\"58\" y1=\"83\" x2=\"112\" y2=\"127\" class=\"e\"/><line x1=\"58\" y1=\"187\" x2=\"112\" y2=\"143\" class=\"e\"/><line x1=\"215\" y1=\"63\" x2=\"215\" y2=\"115\" class=\"e\"/><line x1=\"385\" y1=\"63\" x2=\"385\" y2=\"115\" class=\"e\"/><circle cx=\"130\" cy=\"135\" r=\"20\" class=\"n\"/><text x=\"130\" y=\"141\" font-size=\"16\" text-anchor=\"middle\" class=\"tl\">×<\/text><circle cx=\"215\" cy=\"135\" r=\"20\" class=\"n\"/><text x=\"215\" y=\"141\" font-size=\"16\" text-anchor=\"middle\" class=\"tl\">+<\/text><circle cx=\"300\" cy=\"135\" r=\"20\" class=\"n\"/><text x=\"300\" y=\"141\" font-size=\"16\" text-anchor=\"middle\" class=\"tl\">f<\/text><circle cx=\"385\" cy=\"135\" r=\"20\" class=\"n\"/><text x=\"385\" y=\"140\" font-size=\"12\" text-anchor=\"middle\" class=\"tl\">uᵀh<\/text><line x1=\"150\" y1=\"135\" x2=\"195\" y2=\"135\" class=\"e\"/><line x1=\"235\" y1=\"135\" x2=\"280\" y2=\"135\" class=\"e\"/><line x1=\"320\" y1=\"135\" x2=\"365\" y2=\"135\" class=\"e\"/><line x1=\"405\" y1=\"135\" x2=\"440\" y2=\"135\" class=\"e\"/><text x=\"458\" y=\"140\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">s<\/text><text x=\"40\" y=\"108\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b1\">[1,2,3]<\/text><text x=\"40\" y=\"232\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b1\">2×3 표<\/text><text x=\"240\" y=\"50\" font-size=\"13\" text-anchor=\"start\" class=\"tm b1\">[0,1]<\/text><text x=\"410\" y=\"50\" font-size=\"13\" text-anchor=\"start\" class=\"tm b1\">[2,3]<\/text><text x=\"172\" y=\"165\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b2\">Wx<\/text><text x=\"172\" y=\"182\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">[4,-5]<\/text><text x=\"257\" y=\"165\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b2\">z<\/text><text x=\"257\" y=\"182\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">[4,-4]<\/text><text x=\"342\" y=\"165\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b2\">h<\/text><text x=\"342\" y=\"182\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">[4,0]<\/text><text x=\"458\" y=\"182\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b2\">8<\/text><text x=\"240\" y=\"255\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">왼쪽에서 오른쪽으로 값을 구해 저장해요<\/text><\/svg>","caption":"x, W 를 곱하고 b 를 더하고 f 를 씌우고 u 와 곱해 점수 8 이 나와요.","builds":2}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["Software sees your network as a graph","소프트웨어는 신경망을 그래프로 봐요"],["source nodes = inputs, interior nodes = operations","시작 노드 = 입력, 안쪽 노드 = 연산"],["Forward pass: visit nodes left to right","순전파: 노드를 왼쪽에서 오른쪽으로 방문"],["PyTorch builds this graph for you","PyTorch 가 이 그래프를 대신 만들어 줘요"]]},{"kind":"points","head":"용어 뜻","items":["**계산 그래프(Computation Graph)**: 계산을 노드와 화살표로 그린 그림.","**노드(Node)**: 입력값(x, W, b, u) 또는 연산(×, +, f, 점곱).","**순전파(Forward Pass)**: 그래프를 왼쪽에서 오른쪽으로 따라가며 값을 구하는 것. 그냥 신경망을 계산하는 것이에요."]},{"kind":"check","q":"계산 그래프에서 '+' 동그라미는 무엇일까요?","choices":["입력값 노드","연산 노드","출력값"],"a":1,"why":"×, +, f 같은 계산은 안쪽의 연산 노드예요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.639,"h":0.038,"say":"소프트웨어는 신경망을 그래프로 봐요. 시작 노드는 입력, 안쪽 노드는 연산."},{"x":0.114,"y":0.425,"w":0.071,"h":0.19,"say":"파란 노드 x, W 가 입력이에요."},{"x":0.246,"y":0.419,"w":0.561,"h":0.146,"say":"×, +, f, 점곱(가운데 점) 노드가 연산 노드예요. 화살표 방향으로 값이 흘러요."},{"x":0.843,"y":0.501,"w":0.039,"h":0.038,"say":"마지막 출력 s 예요."},{"x":0.061,"y":0.742,"w":0.639,"h":0.038,"say":"순전파: 왼쪽에서 오른쪽으로 노드를 방문해 값을 구해요."}]},{"kind":"steps","head":"그래프 위 순전파 (p.22 숫자)","steps":["× 노드: W 와 x 를 곱해 Wx = [4, -5]","+ 노드: b = [0, 1] 을 더해 z = [4, -4]","f 노드: ReLU 로 h = [4, 0]","점곱 노드: u = [2, 3] 과 점곱해 s = 8","이 중간값들(Wx, z, h)을 모두 저장해 둬요. 역방향 패스에서 다시 써요."],"answer":"s = 8. 순전파는 그냥 신경망을 한 번 계산하는 것이에요."},{"kind":"prof","when":"3주차 월요일 2교시","lines":["텐서플로우 시절에는 이 그래프를 우리가 직접 그렸어야 했어요. 플레이스홀더로 그래프를 직접 선언했죠.","PyTorch 가 나오면서 그래프를 자동으로 그려 주고, 기울기 계산도 알아서 해 줘요.","요즘은 Hugging Face 모델에 train 함수까지 있어서, 그래프를 직접 그릴 일은 거의 없고 이번 수업에서만 배워요."]},{"kind":"warn","head":"그림 읽기 주의","items":["선 아래 글자는 조금 밀려 있어요. ×→+ 선의 값은 Wx, +→f 선의 값은 z = Wx + b, f→점곱 선의 값은 h 예요.","그림의 'h = f(z)', 's = uᵀh' 는 바로 오른쪽 노드가 하는 계산이라고 읽으면 편해요."]}],"pass4":[{"kind":"check","q":"순전파에서 중간값(Wx, z, h)을 저장하는 이유는?","choices":["메모리를 아끼려고","역방향 패스에서 국소 기울기를 계산할 때 다시 쓰려고","점수를 두 번 출력하려고"],"a":1,"why":"예를 들어 ReLU 의 미분은 z 가 양수였는지 알아야 구할 수 있어요. 그래서 저장해 둬요."},{"kind":"english","head":"답안 문장","en":"**계산 그래프(Computation Graph)**는 입력을 시작 노드, 연산을 안쪽 노드로 그린 것이고, **순전파(Forward Pass)**는 노드를 왼쪽부터 방문해 값을 계산하는 과정이다.","ko":"다음 쪽의 역방향 패스와 짝으로 외워요."}]},{"p":28,"title":"그래프 위의 역전파","terms":["Backpropagation","Chain Rule","Forward Pass","Backward Pass"],"pass1":[{"kind":"say","lines":["이번엔 거꾸로, 오른쪽 끝에서 왼쪽으로 가요. 이것이 **역방향 패스(Backward Pass)**예요.","출발값은 1 이에요. s 를 s 로 미분하면 1 이니까요.","선을 하나 지날 때마다 그 노드의 미분을 곱해 넘겨요. 앞에서 손으로 구한 δ 가 딱 그 자리에 나타나요."]},{"kind":"figure","head":"거꾸로 흐르는 기울기","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"40\" cy=\"75\" r=\"20\" class=\"n3\"/><text x=\"40\" y=\"80\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">x<\/text><circle cx=\"40\" cy=\"195\" r=\"20\" class=\"n3\"/><text x=\"40\" y=\"200\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">W<\/text><circle cx=\"215\" cy=\"45\" r=\"18\" class=\"n3\"/><text x=\"215\" y=\"50\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">b<\/text><circle cx=\"385\" cy=\"45\" r=\"18\" class=\"n3\"/><text x=\"385\" y=\"50\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">u<\/text><line x1=\"58\" y1=\"83\" x2=\"112\" y2=\"127\" class=\"e\"/><line x1=\"58\" y1=\"187\" x2=\"112\" y2=\"143\" class=\"e\"/><line x1=\"215\" y1=\"63\" x2=\"215\" y2=\"115\" class=\"e\"/><line x1=\"385\" y1=\"63\" x2=\"385\" y2=\"115\" class=\"e\"/><circle cx=\"130\" cy=\"135\" r=\"20\" class=\"n\"/><text x=\"130\" y=\"141\" font-size=\"16\" text-anchor=\"middle\" class=\"tl\">×<\/text><circle cx=\"215\" cy=\"135\" r=\"20\" class=\"n\"/><text x=\"215\" y=\"141\" font-size=\"16\" text-anchor=\"middle\" class=\"tl\">+<\/text><circle cx=\"300\" cy=\"135\" r=\"20\" class=\"n\"/><text x=\"300\" y=\"141\" font-size=\"16\" text-anchor=\"middle\" class=\"tl\">f<\/text><circle cx=\"385\" cy=\"135\" r=\"20\" class=\"n\"/><text x=\"385\" y=\"140\" font-size=\"12\" text-anchor=\"middle\" class=\"tl\">uᵀh<\/text><line x1=\"150\" y1=\"135\" x2=\"195\" y2=\"135\" class=\"e\"/><line x1=\"235\" y1=\"135\" x2=\"280\" y2=\"135\" class=\"e\"/><line x1=\"320\" y1=\"135\" x2=\"365\" y2=\"135\" class=\"e\"/><line x1=\"405\" y1=\"135\" x2=\"440\" y2=\"135\" class=\"e\"/><text x=\"458\" y=\"140\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">s<\/text><line x1=\"440\" y1=\"112\" x2=\"417\" y2=\"112\" class=\"e2 b1\"/><polygon points=\"408,112 417,107 417,117\" class=\"arrow b1\"/><text x=\"430\" y=\"102\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">1<\/text><line x1=\"362\" y1=\"112\" x2=\"331\" y2=\"112\" class=\"e2 b1\"/><polygon points=\"322,112 331,107 331,117\" class=\"arrow b1\"/><text x=\"342\" y=\"102\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b1\">[2,3]<\/text><line x1=\"277\" y1=\"112\" x2=\"246\" y2=\"112\" class=\"e2 b2\"/><polygon points=\"237,112 246,107 246,117\" class=\"arrow b2\"/><text x=\"257\" y=\"102\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">δ=[2,0]<\/text><text x=\"300\" y=\"175\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b2\">f'(z) = [1,0] 을 곱해요<\/text><line x1=\"200\" y1=\"95\" x2=\"200\" y2=\"79\" class=\"e2 b3\"/><polygon points=\"200,70 205,79 195,79\" class=\"arrow b3\"/><text x=\"240\" y=\"28\" font-size=\"13\" text-anchor=\"start\" class=\"tb b3\">∂s/∂b = [2,0]<\/text><line x1=\"112\" y1=\"120\" x2=\"71\" y2=\"93\" class=\"e2 b3\"/><polygon points=\"64,88 74,89 69,97\" class=\"arrow b3\"/><text x=\"12\" y=\"30\" font-size=\"13\" text-anchor=\"start\" class=\"tb b3\">∂s/∂x = [2,0,2]<\/text><line x1=\"112\" y1=\"150\" x2=\"71\" y2=\"177\" class=\"e2 b3\"/><polygon points=\"64,182 69,173 74,181\" class=\"arrow b3\"/><text x=\"20\" y=\"250\" font-size=\"13\" text-anchor=\"start\" class=\"tb b3\">∂s/∂W = [[2,4,6],[0,0,0]]<\/text><\/svg>","caption":"1 에서 출발해 [2, 3], δ = [2, 0] 을 거쳐 b, W, x 의 기울기에 도착해요.","builds":3}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["Backward pass: start with 1 at the output","역방향 패스: 출력에서 1 로 시작해요"],["push gradients along the edges in reverse","선을 따라 거꾸로 기울기를 밀어 보내요"],["each edge multiplies by a local Jacobian","선마다 그 자리의 야코비안을 곱해요"],["Backprop = the chain rule, executed as a graph walk","역전파 = 그래프를 걸으며 실행하는 연쇄 법칙"]]},{"kind":"compare","head":"순전파와 역방향 패스","cols":["","**순전파(Forward Pass)**","**역방향 패스(Backward Pass)**"],"rows":[["방향","왼쪽 → 오른쪽","오른쪽 → 왼쪽"],["흐르는 것","값(Wx, z, h, s)","기울기(1, ∂s/∂h, δ, ...)"],["출발","입력 x","출력에서 1"],["노드에서 하는 일","연산","국소 미분을 곱하기"]]},{"kind":"check","q":"역방향 패스의 출발값이 1 인 이유는?","choices":["s 를 s 로 미분하면 1 이라서","학습률이 1 이라서","점수가 항상 1 이라서"],"a":0,"why":"자기 자신으로 미분하면 1 이에요. 여기서부터 곱해 나가요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.6,"h":0.038,"say":"역방향 패스: 출력에서 1 로 시작해 선을 따라 거꾸로 기울기를 보내요."},{"x":0.796,"y":0.444,"w":0.057,"h":0.053,"say":"출발값 1."},{"x":0.486,"y":0.444,"w":0.082,"h":0.057,"say":"∂s/∂h 글자예요. 그림에서는 + 와 f 사이에 적혔지만, 뜻은 h 선(f 와 점곱 사이)의 기울기예요."},{"x":0.264,"y":0.362,"w":0.164,"h":0.114,"say":"∂s/∂z = δ, 오차 신호가 여기 나타나요. + 는 기울기를 그대로 넘기니 + 앞뒤 모두 δ 예요."},{"x":0.114,"y":0.355,"w":0.143,"h":0.305,"say":"마지막으로 x 와 W 에 ∂s/∂x, ∂s/∂W 가 도착해요."}]},{"kind":"steps","head":"그래프 위 역방향 패스 (p.22 숫자)","steps":["출발: ∂s/∂s = 1","점곱 노드(s = uᵀh): ∂s/∂h = u = [2, 3]","f 노드(ReLU): f'(z) = [1, 0] 을 원소별로 곱해 δ = ∂s/∂z = [2, 0]","+ 노드: b 로 그대로 → ∂s/∂b = [2, 0]","× 노드: W 쪽으로 δ 와 x 의 외적 [[2, 4, 6], [0, 0, 0]], x 쪽으로 Wᵀδ = [2, 0, 2]"],"answer":"p.23, p.24 에서 손으로 구한 값과 똑같이 나와요."},{"kind":"prof","when":"3주차 월요일 2교시","lines":["맨 처음 신호는 1 이에요. s 를 s 로 미분하면 1 이니까요.","PyTorch 의 autograd 는 1 로 시작해서 W, b 등의 기울기를 다 계산해 저장해 둬요.","그래서 파라미터가 100MB 인 모델을 학습하려면 기울기까지 담을 최소 2배 메모리가 필요해요.","GPU 메모리가 16GB 인데 모델이 10GB 면, 추론은 되지만 학습은 안 돼요(20GB 필요)."]},{"kind":"say","lines":["실습 N3L p.6 에서 s.backward() 한 줄이 이 걸음을 대신하고,","W.grad, b.grad, x.grad 에 결과를 채워요."]}],"pass4":[{"kind":"check","q":"이 그래프에서 δ(오차 신호)가 나타나는 자리는?","choices":["s 바로 앞","+ 노드 앞, 곧 ∂s/∂z 자리","x 노드"],"a":1,"why":"δ = ∂s/∂z 라서 z 선(+ 와 f 사이)의 기울기예요. + 는 그대로 넘기므로 슬라이드처럼 + 앞에 적어도 같은 값이에요."},{"kind":"english","head":"답안 문장","en":"**역방향 패스(Backward Pass)**는 출력 기울기 1 에서 시작해 그래프를 거꾸로 따라가며 선마다 국소 야코비안을 곱한다. 즉 **역전파(Backpropagation)**는 그래프 위의 **연쇄 법칙(Chain Rule)**이다.","ko":"'Backprop = the chain rule, executed as a graph walk'."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["역방향 패스는 순전파 값을 다시 써요. 그래서 학습할 때는 추론할 때보다 메모리가 훨씬 많이 들어요(교수님: 최소 2배)."]}]},{"p":29,"title":"노드 하나씩","terms":["Chain Rule","Upstream Gradient","Local Gradient","Downstream Gradient","Node"],"pass1":[{"kind":"say","lines":["**노드(Node)** 하나만 떼어서 보면 할 일이 아주 단순해요.","뒤에서 받은 **상류 기울기(Upstream Gradient)**에 자기 **국소 기울기(Local Gradient)**를 곱해서 앞으로 넘기면 끝이에요.","어떤 노드도 네트워크 전체를 볼 필요가 없어요."]},{"kind":"figure","head":"노드 하나의 일","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"190\" y=\"85\" width=\"100\" height=\"70\" rx=\"2\" class=\"n2\"/><text x=\"240.0\" y=\"126.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl\">f: y = x²<\/text><line x1=\"30\" y1=\"105\" x2=\"179\" y2=\"105\" class=\"e\"/><polygon points=\"188,105 179,110 179,100\" class=\"arrow\"/><text x=\"110\" y=\"95\" font-size=\"14\" text-anchor=\"middle\" class=\"t\">입력 x = 3<\/text><line x1=\"292\" y1=\"105\" x2=\"441\" y2=\"105\" class=\"e\"/><polygon points=\"450,105 441,110 441,100\" class=\"arrow\"/><text x=\"370\" y=\"95\" font-size=\"14\" text-anchor=\"middle\" class=\"t\">출력 y = 9<\/text><line x1=\"450\" y1=\"140\" x2=\"301\" y2=\"140\" class=\"e2 b1\"/><polygon points=\"292,140 301,135 301,145\" class=\"arrow b1\"/><text x=\"370\" y=\"165\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">상류 기울기 2<\/text><text x=\"240\" y=\"190\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">국소 기울기 dy/dx = 2x = 6<\/text><line x1=\"188\" y1=\"140\" x2=\"39\" y2=\"140\" class=\"e2 b2\"/><polygon points=\"30,140 39,135 39,145\" class=\"arrow b2\"/><text x=\"110\" y=\"165\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b2\">하류 2 × 6 = 12<\/text><text x=\"240\" y=\"240\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">노드는 자기 입력과 출력만 알면 돼요<\/text><\/svg>","caption":"x = 3 이 들어와 y = 9 가 나가요. 뒤에서 2 가 오면, 국소 기울기 6 을 곱해 12 를 앞으로 보내요.","builds":2}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["Every node only needs to know ONE thing","노드마다 딱 한 가지만 알면 돼요"],["its local gradient","자기 **국소 기울기(Local Gradient)**"],["downstream = upstream × local","하류 = 상류 × 국소"],["no node ever sees the whole network","어떤 노드도 전체 네트워크를 보지 않아요"],["This locality is why autodiff frameworks can be built at all","이 '자기 주변만' 성질 덕분에 자동 미분 도구를 만들 수 있어요"]]},{"kind":"compare","head":"기울기 세 가지","cols":["이름","기호","뜻"],"rows":[["**상류 기울기(Upstream Gradient)**","∂J/∂y","내 출력 쪽(뒤)에서 받은 것"],["**국소 기울기(Local Gradient)**","∂y/∂x","내 입력과 출력만 보고 구한 것"],["**하류 기울기(Downstream Gradient)**","∂J/∂x","둘을 곱해 내 입력 쪽(앞)으로 보내는 것"]]},{"kind":"check","q":"하류 기울기를 구하는 식은?","choices":["상류 + 국소","상류 × 국소","상류 ÷ 국소"],"a":1,"why":"**연쇄 법칙(Chain Rule)** 그대로, 곱해요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.446,"h":0.038,"say":"노드마다 딱 하나, 자기 국소 기울기만 알면 돼요."},{"x":0.427,"y":0.412,"w":0.146,"h":0.127,"say":"노드 f: 입력 x 를 받아 출력 y = f(x) 를 내요."},{"x":0.571,"y":0.501,"w":0.2,"h":0.057,"say":"오른쪽에서 상류 기울기 ∂J/∂y 가 들어와요."},{"x":0.232,"y":0.501,"w":0.196,"h":0.057,"say":"왼쪽으로 하류 기울기 ∂J/∂x = ∂J/∂y × ∂y/∂x 가 나가요."},{"x":0.371,"y":0.584,"w":0.257,"h":0.032,"say":"국소 기울기 ∂y/∂x 는 노드 안에 살아요."}]},{"kind":"formula","head":"노드 하나의 규칙","tex":"\\frac{\\partial J}{\\partial x} = \\frac{\\partial J}{\\partial y}\\cdot\\frac{\\partial y}{\\partial x}","parts":[{"sym":"\\frac{\\partial J}{\\partial y}","say":"**상류 기울기(Upstream Gradient)**: 뒤에서 받은 것"},{"sym":"\\frac{\\partial y}{\\partial x}","say":"**국소 기울기(Local Gradient)**: 노드 안에서 구한 것"},{"sym":"\\frac{\\partial J}{\\partial x}","say":"**하류 기울기(Downstream Gradient)**: 앞으로 보낼 것"}],"whole":"받은 것 × 내 것 = 보낼 것. 연쇄 법칙을 노드 하나에 적용한 모양이에요."},{"kind":"steps","head":"제곱 노드 손계산","steps":["노드: y = x², 들어온 값 x = 3, 나간 값 y = 9","뒤에서 상류 기울기 ∂J/∂y = 2 가 도착했어요.","국소 기울기: y = x² 의 미분 2x = 2 × 3 = 6","하류 기울기: 2 × 6 = 12 를 앞으로 보내요."],"answer":"∂J/∂x = 12. 노드는 J 가 뭔지 몰라도 계산할 수 있어요."},{"kind":"prof","when":"3주차 월요일 2교시","lines":["노드 하나는 전체 네트워크의 다른 노드 흐름을 알 필요가 없어요. 각 노드는 나만 알면 돼요.","다운스트림 그레디언트는 업스트림 그레디언트에 로컬 그레디언트를 곱하면 된다.","이 로컬리티 때문에 역전파를 일반적인 알고리즘으로 만들 수 있고, PyTorch 같은 자동 미분 프레임워크도 가능한 거예요."]},{"kind":"bg","src":"기초 다지기 7단원 (wb-7 함수, 기울기, 미분)","lines":["국소 기울기는 결국 그 노드 함수의 미분이에요. x² → 2x 같은 규칙은 기초 다지기 7단원에 있어요."]}],"pass4":[{"kind":"check","q":"노드 y = 3x 에 상류 기울기 5 가 들어오면 하류 기울기는?","choices":["3","8","15"],"a":2,"why":"국소 기울기 3, 상류 5 를 곱해 15 예요."},{"kind":"english","head":"답안 문장","en":"각 노드는 **상류 기울기(Upstream Gradient)**에 자신의 **국소 기울기(Local Gradient)**를 곱해 **하류 기울기(Downstream Gradient)**를 입력 쪽으로 보낸다.","ko":"하류 = 상류 × 국소, 한 줄만 외워도 돼요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'상류(upstream)' 는 출력 쪽, '하류(downstream)' 는 입력 쪽이에요. 기울기가 거꾸로 흐르니 물의 방향도 뒤에서 앞으로예요.","J 는 여기서 전체 손실(또는 점수)이에요. 야코비안 J 와 헷갈리지 마요."]}]},{"p":30,"title":"노드의 성격: +, max, ×","terms":["ReLU","Local Gradient"],"pass1":[{"kind":"say","lines":["자주 나오는 노드 세 개는 성격이 뚜렷해요.","+ 는 받은 기울기를 똑같이 나눠 주고, max 는 이긴 쪽에만 주고,","× 는 상대편 값을 곱해서 맞바꿔 줘요."]},{"kind":"figure","head":"세 노드, 세 성격 (뒤에서 온 기울기 2)","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"22\" y=\"68\" font-size=\"15\" text-anchor=\"end\" class=\"t\">3<\/text><text x=\"22\" y=\"176\" font-size=\"15\" text-anchor=\"end\" class=\"t\">2<\/text><line x1=\"28\" y1=\"65\" x2=\"60\" y2=\"106\" class=\"e\"/><line x1=\"28\" y1=\"168\" x2=\"60\" y2=\"124\" class=\"e\"/><circle cx=\"80\" cy=\"115\" r=\"22\" class=\"n\"/><text x=\"80\" y=\"121\" font-size=\"16\" text-anchor=\"middle\" class=\"tl\">+<\/text><line x1=\"102\" y1=\"115\" x2=\"135\" y2=\"115\" class=\"e\"/><text x=\"142\" y=\"120\" font-size=\"15\" text-anchor=\"start\" class=\"t\">5<\/text><text x=\"122\" y=\"142\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">2<\/text><text x=\"28\" y=\"94\" font-size=\"14\" text-anchor=\"end\" class=\"tb b1\">2<\/text><text x=\"28\" y=\"200\" font-size=\"14\" text-anchor=\"end\" class=\"tb b1\">2<\/text><text x=\"80\" y=\"240\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">나눠 주기<\/text><text x=\"182\" y=\"68\" font-size=\"15\" text-anchor=\"end\" class=\"t\">3<\/text><text x=\"182\" y=\"176\" font-size=\"15\" text-anchor=\"end\" class=\"t\">2<\/text><line x1=\"188\" y1=\"65\" x2=\"220\" y2=\"106\" class=\"e\"/><line x1=\"188\" y1=\"168\" x2=\"220\" y2=\"124\" class=\"e\"/><circle cx=\"240\" cy=\"115\" r=\"22\" class=\"n\"/><text x=\"240\" y=\"120\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">max<\/text><line x1=\"262\" y1=\"115\" x2=\"295\" y2=\"115\" class=\"e\"/><text x=\"302\" y=\"120\" font-size=\"15\" text-anchor=\"start\" class=\"t\">3<\/text><text x=\"282\" y=\"142\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b2\">2<\/text><text x=\"188\" y=\"94\" font-size=\"14\" text-anchor=\"end\" class=\"tb b2\">2<\/text><text x=\"188\" y=\"200\" font-size=\"14\" text-anchor=\"end\" class=\"tb b2\">0<\/text><text x=\"240\" y=\"240\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">이긴 쪽에만<\/text><text x=\"342\" y=\"68\" font-size=\"15\" text-anchor=\"end\" class=\"t\">3<\/text><text x=\"342\" y=\"176\" font-size=\"15\" text-anchor=\"end\" class=\"t\">2<\/text><line x1=\"348\" y1=\"65\" x2=\"380\" y2=\"106\" class=\"e\"/><line x1=\"348\" y1=\"168\" x2=\"380\" y2=\"124\" class=\"e\"/><circle cx=\"400\" cy=\"115\" r=\"22\" class=\"n\"/><text x=\"400\" y=\"121\" font-size=\"16\" text-anchor=\"middle\" class=\"tl\">×<\/text><line x1=\"422\" y1=\"115\" x2=\"455\" y2=\"115\" class=\"e\"/><text x=\"462\" y=\"120\" font-size=\"15\" text-anchor=\"start\" class=\"t\">6<\/text><text x=\"442\" y=\"142\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b3\">2<\/text><text x=\"348\" y=\"94\" font-size=\"14\" text-anchor=\"end\" class=\"tb b3\">2×2=4<\/text><text x=\"348\" y=\"200\" font-size=\"14\" text-anchor=\"end\" class=\"tb b3\">2×3=6<\/text><text x=\"400\" y=\"240\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">맞바꿔 곱하기<\/text><\/svg>","caption":"+ 는 2, 2 로 나눠 주고, max 는 이긴 3 쪽에만 2, × 는 상대 값을 곱해 4 와 6 을 보내요.","builds":3},{"kind":"analogy","head":"배관공처럼 읽기","scene":"물(기울기)이 파이프를 거꾸로 흘러요. 갈림길에서 나뉘고, 밸브에서 한쪽만 열리고, 스위치에서 바뀌어요.","map":[["물을 양쪽에 똑같이 보냄","+ 노드: 나눠 주기"],["한쪽 밸브만 열림","max 노드: 이긴 쪽에만"],["상대편 굵기로 바뀜","× 노드: 맞바꿔 곱하기"],["두 파이프가 만나면 물이 합쳐짐","갈라졌던 길의 기울기는 더해요"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["\"+\" distributes the gradient","+ 는 기울기를 나눠 줘요"],["\"max\" routes it to the winner","max 는 이긴 쪽으로 보내요"],["\"×\" switches the inputs","× 는 입력을 맞바꿔 곱해요"],["branches that MERGE forward will SUM their gradients backward","순전파에서 갈라져 쓰인 값은 역전파에서 기울기를 더해요"],["Read a graph like a plumber","그래프를 배관공처럼 읽어요"]]},{"kind":"compare","head":"세 노드의 국소 기울기","cols":["노드","순전파","국소 기울기","뒤로 보내는 것(상류 2)"],"rows":[["+","3 + 2 = 5","둘 다 1","2, 2"],["max","max(3, 2) = 3","이긴 쪽 1, 진 쪽 0","2, 0"],["×","3 × 2 = 6","상대편 값(2, 3)","2×2 = 4, 2×3 = 6"]]},{"kind":"check","q":"max 노드에서 진 쪽 입력이 받는 기울기는?","choices":["상류 기울기 그대로","0","상류 기울기의 절반"],"a":1,"why":"진 쪽은 출력에 영향을 주지 않으니 0 이에요. **ReLU** = max(0, x) 도 음수 쪽 기울기가 0 이에요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.593,"h":0.038,"say":"흔한 노드 세 개, 성격 세 가지. 세 예 모두 뒤에서 온 기울기는 2 예요."},{"x":0.107,"y":0.406,"w":0.239,"h":0.254,"say":"+ : 3 + 2 = 5. 뒤로 2, 2 를 똑같이 나눠 줘요."},{"x":0.379,"y":0.406,"w":0.243,"h":0.254,"say":"max : 더 큰 3 이 이겨요. 이긴 쪽에 2, 진 쪽에 0."},{"x":0.654,"y":0.406,"w":0.243,"h":0.254,"say":"× : 3 × 2 = 6. 3 쪽에는 2×2 = 4, 2 쪽에는 2×3 = 6. 상대 값을 곱해요."},{"x":0.061,"y":0.749,"w":0.464,"h":0.036,"say":"순전파에서 갈라진 가지는 역전파에서 기울기를 합쳐요(더하기)."}]},{"kind":"formula","head":"세 노드의 국소 기울기","tex":"y = x_1 + x_2: \\frac{\\partial y}{\\partial x_1} = 1, \\quad y = \\max(x_1, x_2): \\frac{\\partial y}{\\partial x_1} = \\begin{cases}1 & x_1 > x_2\\\\ 0 & \\text{else}\\end{cases}, \\quad y = x_1 x_2: \\frac{\\partial y}{\\partial x_1} = x_2","parts":[{"sym":"x_1 + x_2","say":"x₁ 을 1 밀면 y 도 1 움직여요 → 1"},{"sym":"\\max(x_1, x_2)","say":"이긴 쪽만 y 를 움직여요 → 1 또는 0"},{"sym":"x_1 x_2","say":"x₁ 을 1 밀면 y 는 x₂ 만큼 움직여요 → 상대 값"},{"sym":"\\frac{\\partial y}{\\partial x_1}","say":"**국소 기울기(Local Gradient)**. 여기에 상류 기울기를 곱해요"}],"whole":"나눠 주기(1), 이긴 쪽만(1 과 0), 맞바꾸기(상대 값)."},{"kind":"steps","head":"세 성격을 한 그래프에서: f = (a + b) × max(b, c)","steps":["값: a = 1, b = 3, c = 2. 순전파: q = a + b = 4, r = max(b, c) = 3, f = q × r = 12","출발 ∂f/∂f = 1. × 노드는 맞바꿔요: q 쪽 1 × r = 3, r 쪽 1 × q = 4","+ 노드는 나눠 줘요: a 에 3, b 에 3","max 노드는 이긴 쪽(b = 3 > c = 2)에만: b 에 4, c 에 0","b 는 두 가지에 쓰였으니 합쳐요: 3 + 4 = 7","확인: ∂f/∂b = max(b, c) + (a + b) × 1 = 3 + 4 = 7 (맞음)"],"answer":"∂f/∂a = 3, ∂f/∂b = 7, ∂f/∂c = 0."},{"kind":"prof","when":"3주차 월요일 2교시","lines":["이건 조금 알아두시면 좋은데, 손으로 계산할 때 쓰는 세 가지 백워드 동작이에요.","덧셈은 그레디언트를 그대로 분배하고, max 는 큰 놈만 골라 흘려서 위너에게 라우팅해요.","곱하기는 각자 상대 카운터파트 값을 곱해서 흘러가요. 3 과 2 가 있으면 위로 2×2, 아래로 2×3 이에요."]},{"kind":"bg","src":"기초 다지기 7단원 (wb-7 함수, 기울기, 미분)","lines":["합의 미분은 각각의 미분의 합, 상수배는 그 상수. 이 두 규칙만으로 + 와 × 노드가 설명돼요."]}],"pass4":[{"kind":"check","q":"× 노드에 x = 4, y = -1 이 들어오고 상류 기울기가 3 이면, x 쪽 기울기는?","choices":["-3","12","3"],"a":0,"why":"x 쪽은 상대 값 y = -1 을 곱해 3 × (-1) = -3, y 쪽은 3 × 4 = 12 예요."},{"kind":"check","q":"한 값이 순전파에서 두 곳에 쓰였다면 역전파에서 그 값의 기울기는?","choices":["두 기울기 중 큰 것","두 기울기의 합","두 기울기의 곱"],"a":1,"why":"갈라진 가지는 역전파에서 더해요(sum at joins)."},{"kind":"english","head":"답안 문장","en":"역전파에서 덧셈 노드는 상류 기울기를 입력에 그대로 분배하고, max 노드는 더 큰 입력에만 전달하며, 곱셈 노드는 상대 입력값을 곱해 전달한다. 순전파에서 여러 곳에 쓰인 변수의 기울기는 합한다.","ko":"distribute, route, switch, 그리고 sum."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["× 노드는 '자기 값' 이 아니라 '상대 값' 을 곱해요. 3 쪽에 가는 기울기는 2 × 2 = 4 예요.","max 에서 진 쪽 기울기 0 은 '틀렸다' 가 아니라 '출력에 영향이 없었다' 는 뜻이에요."]}]},{"p":31,"title":"전체 알고리즘과 그 값","terms":["Backpropagation","Forward Pass","Backward Pass","Parameter","Topological Order"],"pass1":[{"kind":"say","lines":["정리하면 **역전파(Backpropagation)**는 두 번 걷기예요.","앞으로 한 번 걸으며 값을 구해 저장하고, 뒤로 한 번 걸으며 기울기를 구해요.","진짜 마법은 값싸다는 것이에요. 뒤로 한 번 걷는 비용이 앞으로 한 번 걷는 비용과 비슷해요."]},{"kind":"figure","head":"두 가지 방법의 값","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"20\" y=\"60\" font-size=\"15\" text-anchor=\"start\" class=\"tb\">하나씩 흔들어 보기<\/text><rect x=\"20\" y=\"72\" width=\"440\" height=\"30\" rx=\"2\" class=\"n4\"/><text x=\"240\" y=\"93\" font-size=\"14\" text-anchor=\"middle\" class=\"tl\">순전파 1,000,000번<\/text><text x=\"20\" y=\"150\" font-size=\"15\" text-anchor=\"start\" class=\"tb b1\">역전파<\/text><rect x=\"20\" y=\"162\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b1\"/><rect x=\"50\" y=\"162\" width=\"30\" height=\"30\" rx=\"2\" class=\"n3 b1\"/><text x=\"90\" y=\"183\" font-size=\"14\" text-anchor=\"start\" class=\"t b1\">순전파 1번 + 역방향 1번 (비슷한 값)<\/text><text x=\"240\" y=\"240\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">파라미터 백만 개의 기울기를 한 번에<\/text><\/svg>","caption":"파라미터를 하나씩 흔들면 백만 번 계산해야 하지만, 역전파는 두 번 걷기로 끝나요.","builds":1}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["visit nodes in topological order, compute values (store them!)","**위상 순서(Topological Order)**대로 노드를 방문해 값을 구해요(저장!)"],["output gradient = 1, visit in REVERSE order","출력 기울기 1, 순서를 거꾸로 방문"],["apply upstream × local, sum at branches","상류 × 국소를 곱하고, 갈림길에서는 더해요"],["ALL gradients for the price of one","기울기 전부를 한 번 값에"],["Backprop's real magic is not correctness, it is the price tag","역전파의 진짜 마법은 정확함이 아니라 값(가격표)이에요"]]},{"kind":"steps","head":"전체 알고리즘","steps":["**순전파(Forward Pass)**: **위상 순서(Topological Order)**대로 노드를 방문해 값을 구하고 저장해요.","**역방향 패스(Backward Pass)**: 출력 기울기를 1 로 두고, 순서를 거꾸로 방문해요.","노드마다 상류 × 국소를 곱해 앞으로 보내요.","여러 가지가 만나는 곳에서는 기울기를 더해요.","모든 **파라미터(Parameter)**의 기울기가 모이면 경사 하강법으로 한 걸음 고쳐요."],"answer":"앞으로 한 번, 뒤로 한 번이면 모든 기울기가 나와요."},{"kind":"points","head":"용어 뜻","items":["**위상 순서(Topological Order)**: 필요한 값이 먼저 계산되도록 정한 방문 순서. 예: x, W → × → + → f → 점곱 → s","비용(cost): 계산에 드는 시간. 역방향 한 번 ≈ 순방향 한 번이에요."]},{"kind":"check","q":"파라미터가 백만 개일 때, 하나씩 흔들어 기울기를 구하면 순전파가 몇 번 필요할까요? (슬라이드 기준)","choices":["1 번","2 번","백만 번"],"a":2,"why":"파라미터마다 따로 흔들어야 하니 백만 번이에요. 역전파는 앞뒤 한 번씩이면 돼요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.539,"h":0.042,"say":"순방향: 위상 순서대로 노드를 방문해 값을 계산하고, 저장해요!"},{"x":0.061,"y":0.251,"w":0.718,"h":0.041,"say":"역방향: 출력 기울기 1, 거꾸로 방문, 상류 × 국소, 갈림길에서 합."},{"x":0.061,"y":0.307,"w":0.696,"h":0.042,"say":"비용: 역방향 한 번 ≈ 순방향 한 번. 기울기 전부를 한 번 값에."},{"x":0.079,"y":0.355,"w":0.582,"h":0.034,"say":"비교: 백만 개 파라미터를 하나씩 흔들면 순전파 백만 번."},{"x":0.061,"y":0.406,"w":0.521,"h":0.041,"say":"이 효율 덕분에 딥러닝이 계산상 가능해졌어요."}]},{"kind":"steps","head":"값 비교 손계산","steps":["파라미터 1,000,000 개, 순전파 한 번에 1 초가 걸린다고 해 봐요.","하나씩 흔들기: 1,000,000 번 × 1 초 = 1,000,000 초(약 11.6 일)","역전파: 순전파 1 번 + 역방향 1 번 ≈ 2 초","그래서 한 걸음 업데이트에 11 일이 걸리느냐, 2 초가 걸리느냐의 차이예요."],"answer":"역전파는 기울기 전부를 순전파 한 번과 비슷한 값에 줘요."},{"kind":"prof","when":"3주차 월요일 2교시","lines":["포워드 패스에서 각 노드 값을 계산하고, 백워드 때 다시 써야 하니까 중간 값들을 저장해 놓아요.","백워드 패스는 출력에서 시작하고, 맨 출력의 기울기는 1 이에요.","모든 그레디언트를 포워드 한 번, 백워드 한 번으로 한 번에 구해요. 수십억 개 파라미터 신경망이 한 스텝에 어떻게 동작하는지를 설명해 줘요."]},{"kind":"prof","when":"3주차 월요일 2교시","lines":["정리하면 역전파의 목적은 각 파라미터가 손실에 얼마나 영향을 미치는지, 그 그레디언트를 계산하는 것이에요.","위에서 받은 업스트림 에러 시그널에 내 로컬만 곱하면 되고, 그렇게 거꾸로 전파시키니까 역전파라고 불러요."]}],"pass4":[{"kind":"check","q":"역전파 알고리즘에서 순전파 값을 저장하는 이유로 알맞은 것은?","choices":["역방향 패스에서 국소 기울기를 계산할 때 필요해서","출력을 여러 번 보여 주려고","학습률을 정하려고"],"a":0,"why":"예: ReLU 미분은 z 부호, × 노드는 상대 입력값이 필요해요."},{"kind":"english","head":"답안 문장","en":"**역전파(Backpropagation)**는 순전파 값을 저장한 뒤 역순으로 상류 × 국소를 곱하고 분기점에서 합한다. 비용이 순전파 한 번과 비슷한 것이 핵심이다.","ko":"정확함보다 '값(price tag)' 이 핵심이라는 슬라이드 결론까지 함께 써요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'백만 번' 은 슬라이드가 든 비교예요. 역전파가 공짜라는 뜻은 아니고, 순전파 한 번과 비슷한 비용이 든다는 뜻이에요.","속도 대신 메모리를 써요. 중간값과 기울기를 저장해야 해서 학습은 추론보다 메모리가 많이 들어요."]}]},{"p":32,"title":"자동 미분, 기울기 검사, 그리고 여러분","terms":["Automatic Differentiation (Autodiff)","Gradient Checking","Numeric Gradient","autograd","Matrix Calculus","Vanishing Gradient","Exploding Gradient"],"pass1":[{"kind":"say","lines":["실제로는 PyTorch 의 **autograd(오토그래드)**가 역전파를 대신해요.","loss.backward() 한 줄이면 그래프를 거꾸로 걸어 모든 기울기를 채워요.","손으로 짠 기울기가 맞는지 의심되면 **기울기 검사(Gradient Checking)**로 확인해요.","그래도 수학을 배우는 이유가 있어요. 도구는 방법을 숨길 뿐, 책임은 우리에게 남아요."]},{"kind":"compare","head":"기울기를 구하는 세 가지 길","cols":["방법","속도","쓰임"],"rows":[["손으로 유도(**행렬 미적분(Matrix Calculus)**)","사람이 느림","원리 이해, 과제 2"],["**자동 미분(Automatic Differentiation (Autodiff))**","빠름","실제 학습"],["**수치 기울기(Numeric Gradient)**","아주 느림","맞는지 검사"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어를 우리말로","cols":["영어 원문","우리말 뜻"],"rows":[["every op knows its local gradient","연산마다 자기 국소 기울기를 알아요"],["loss.backward() runs the graph walk for you","loss.backward() 가 그래프 걷기를 대신 해요"],["the numeric gradient: slow but nearly impossible to get wrong","수치 기울기: 느리지만 틀리기가 거의 불가능해요"],["Why still learn the math?","그래도 왜 수학을 배우나?"],["frameworks hide the how, not the responsibility","도구는 '어떻게' 를 숨길 뿐, 책임까지 숨기진 않아요"]]},{"kind":"points","head":"용어 뜻","items":["**autograd(오토그래드)**: PyTorch 의 **자동 미분(Automatic Differentiation (Autodiff))** 장치.","**수치 기울기(Numeric Gradient)**: θ 를 조금 올린 값과 내린 값의 차이로 어림한 기울기.","**기울기 검사(Gradient Checking)**: 손 유도 기울기와 수치 기울기를 비교해 버그를 찾는 것.","수학이 필요한 때: **기울기 소실(Vanishing Gradient)**, **기울기 폭발(Exploding Gradient)** 원인 찾기, 새 층 만들기, 논문 읽기."]},{"kind":"check","q":"수치 기울기의 장점은?","choices":["아주 빠르다","틀리기가 거의 어렵다","메모리가 필요 없다"],"a":1,"why":"느리지만 공식이 단순해서 틀리기 어려워요. 그래서 검사용으로 써요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.729,"h":0.038,"say":"PyTorch autograd: 연산마다 국소 기울기를 알아서, loss.backward() 가 그래프 걷기를 대신해요."},{"x":0.061,"y":0.25,"w":0.554,"h":0.039,"say":"디버그 도구, 수치 기울기: 느리지만 틀리기 거의 불가능해요."},{"x":0.332,"y":0.4,"w":0.336,"h":0.089,"say":"f'(θ) ≈ (f(θ + h) - f(θ - h)) / 2h, h 는 10⁻⁴ 쯤."},{"x":0.061,"y":0.533,"w":0.743,"h":0.041,"say":"그래도 수학을 배우는 이유: 기울기 소실과 폭발 디버깅, 직접 만드는 층, 논문 읽기."},{"x":0.079,"y":0.581,"w":0.35,"h":0.034,"say":"도구는 방법을 숨길 뿐 책임은 숨기지 않아요."}]},{"kind":"formula","head":"수치 기울기 (중앙 차분)","tex":"f'(\\theta) \\approx \\frac{f(\\theta + h) - f(\\theta - h)}{2h}, \\quad h \\approx 10^{-4}","parts":[{"sym":"f(\\theta + h)","say":"θ 를 아주 조금 올려서 계산한 값"},{"sym":"f(\\theta - h)","say":"θ 를 아주 조금 내려서 계산한 값"},{"sym":"2h","say":"올린 곳과 내린 곳 사이 거리"},{"sym":"h \\approx 10^{-4}","say":"0.0001. 은닉층 h 와는 다른, 아주 작은 수예요"}],"whole":"양쪽으로 살짝 밀어 본 차이를 거리로 나누면 기울기의 어림값이에요."},{"kind":"steps","head":"수치 기울기로 검사하기 (실습 N3L p.4 의 함수)","steps":["f(θ) = θ³ + 2θ, θ = 2, h = 0.0001","손 공식: f'(θ) = 3θ² + 2 = 3 × 4 + 2 = 14","f(2.0001) = 12.001400060001, f(1.9999) = 11.998600059999","차이 0.002800000002 를 2h = 0.0002 로 나누면 약 14.00000001","14 와 거의 같아요 → 손 공식이 맞아요 (맞음)"],"answer":"수치 기울기 ≈ 14.00000001, 손 공식 14. 기울기 검사 통과."},{"kind":"prof","when":"3주차 월요일 2교시","lines":["현실에서는 PyTorch 가 이걸 대신해요. 모든 연산이 자기만의 로컬 그레디언트를 갖고 있어요.","loss.backward() 한 방이면 역전파 그레디언트를 다 계산해 주고, 옵티마이저 스텝이 알파만큼 업데이트해요.","그래서 여러분이 굳이 수학적으로 미분을 다 계산할 필요는 없어요."]},{"kind":"say","lines":["실습 N3L p.4 에서 f(x) = x³ + 2x 를 x.grad 로 미분해 손 공식 14 와 비교하고,","N3L p.5~6 에서 두 층 신경망의 dW, db, dx 를 손 공식과 autograd 로 비교해요. 과제 2 Part A 와 같은 작업이에요."]}],"pass4":[{"kind":"check","q":"f(θ) = θ², θ = 3, h = 0.1 로 중앙 차분 수치 기울기를 구하면?","choices":["5.9","6","6.1"],"a":1,"why":"(3.1² - 2.9²) / 0.2 = (9.61 - 8.41) / 0.2 = 1.2 / 0.2 = 6 이에요."},{"kind":"check","q":"loss.backward() 가 하는 일은?","choices":["파라미터를 업데이트한다","계산 그래프를 거꾸로 걸으며 모든 기울기를 구해 .grad 에 채운다","순전파를 다시 한다"],"a":1,"why":"업데이트는 옵티마이저 스텝이 해요. backward 는 기울기 계산까지예요."},{"kind":"english","head":"답안 문장","en":"**자동 미분(Automatic Differentiation (Autodiff))**는 국소 기울기로 역전파를 자동 수행하고, **기울기 검사(Gradient Checking)**는 수치 기울기와 비교해 손 유도를 검증한다.","ko":"수치 기울기는 느려서 학습이 아니라 검사에만 써요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["수치 기울기 식의 h 는 아주 작은 수(0.0001)예요. 은닉층 값 h 와 글자만 같아요.","backward() 는 기울기만 구하고, 파라미터를 바꾸는 건 옵티마이저 스텝이에요.","뒤의 RNN 에서 **기울기 소실(Vanishing Gradient)**과 **기울기 폭발(Exploding Gradient)**을 다시 만나요. 그때 이 쪽의 '수학을 배우는 이유' 가 쓰여요."]}]},{"p":33,"title":"10분 쉬는 시간","terms":["Language Model (LM)","Next Token Prediction"],"pass1":[{"kind":"say","lines":["반환점이에요. 지금까지 신경망이 어떻게 계산하고(1부), 어떻게 배우는지(2부) 봤어요.","다음은 **언어 모델(Language Model (LM))**, 앞 단어로 **다음 토큰 예측(Next Token Prediction)**을 하는 과제예요. 이것이 ChatGPT 까지 이어져요.","글을 토큰으로 자르고, 토큰을 벡터로 바꾸고, 벡터로 다음 토큰을 맞혀요.","실제 수업에서는 이 쪽에서 쉬지 않고 바로 이어서 진행했어요."]},{"kind":"say","lines":["**언어 모델(Language Model (LM))**은 휴대폰 자판의 다음 단어 추천과 같아요.","교수님은 **다음 토큰 예측(Next Token Prediction)**이 거의 모든 걸 결정한다고, GPT 도 결국 이것이라고 했어요."]}],"pass2":[],"pass3":[],"pass4":[]},{"p":34,"title":"3부 구분: 언어 모델링","terms":["Language Model (LM)","Next Token Prediction","n-gram","Perplexity (PPL)"],"pass1":[{"kind":"say","lines":["3부 **언어 모델링(Language Modeling)**이 시작돼요. 부제는 '다음 단어를 맞히는 일'이에요.","주문의 마지막 조각 '벡터로 다음 토큰을 맞혀요'가 바로 이 부분이에요.","배울 것: **언어 모델(LM)**, **n-gram(엔그램)**, 그리고 모델을 재는 자 **퍼플렉서티(PPL)**.","교수님은 이 **다음 토큰 예측(Next Token Prediction)**가 자연어처리의 알파부터 오메가라고 했어요."]}],"pass2":[],"pass3":[],"pass4":[]},{"p":35,"title":"언어 모델링이라는 과제","terms":["Language Model (LM)","Next Token Prediction","Probability Distribution","Conditional Probability","Chain Rule of Probability","Vocabulary","Token","Large Language Model (LLM)","Corpus"],"pass1":[{"kind":"say","lines":["주문을 다시 불러요: 글을 토큰으로 자르고, 토큰을 벡터로 바꾸고, 벡터로 다음 토큰을 맞혀요.","오늘은 마지막 조각, '다음 토큰을 맞히기'를 배워요.","**언어 모델(LM)**은 앞 글을 보고 다음에 올 단어를 맞히는 모델이에요."]},{"kind":"analogy","head":"휴대폰 자판의 다음 단어 추천","scene":"휴대폰에 '오늘 수업은 몇 시에'까지 치면 자판 위에 '끝나요', '시작해요' 같은 추천이 떠요. 앞 글을 보고 다음 단어 후보마다 가능성을 매긴 거예요.","map":[["자판의 추천 단어","다음 단어 후보"],["추천 순서(가능성)","후보마다 붙은 확률"],["추천 기능 자체","**언어 모델(LM)**"]]},{"kind":"figure","head":"빈칸 뒤에 올 단어마다 확률을 붙여요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect x=\"20\" y=\"20\" width=\"440\" height=\"40\" rx=\"2\" class=\"box2\"/><text x=\"240.0\" y=\"45.333333333333336\" class=\"tb\" font-size=\"16\" text-anchor=\"middle\">the lecture will end at ____<\/text><line x1=\"240\" y1=\"62\" x2=\"240.0\" y2=\"78.0\" class=\"e2 b1\"/><polygon points=\"240.0,88.0 235.0,78.0 245.0,78.0\" class=\"arrow b1\"/><text x=\"40\" y=\"115\" class=\"t b1\" font-size=\"15\" text-anchor=\"start\">9pm<\/text><rect x=\"140\" y=\"101\" width=\"120\" height=\"18\" rx=\"2\" class=\"n2 b1\"/><text x=\"270\" y=\"115\" class=\"tb b1\" font-size=\"14\" text-anchor=\"start\">0.2<\/text><text x=\"40\" y=\"150\" class=\"t b1\" font-size=\"15\" text-anchor=\"start\">noon<\/text><rect x=\"140\" y=\"136\" width=\"60\" height=\"18\" rx=\"2\" class=\"n3 b1\"/><text x=\"210\" y=\"150\" class=\"tb b1\" font-size=\"14\" text-anchor=\"start\">0.1<\/text><text x=\"40\" y=\"185\" class=\"t b1\" font-size=\"15\" text-anchor=\"start\">midnight<\/text><rect x=\"140\" y=\"171\" width=\"30\" height=\"18\" rx=\"2\" class=\"n3 b1\"/><text x=\"180\" y=\"185\" class=\"tb b1\" font-size=\"14\" text-anchor=\"start\">0.05<\/text><text x=\"40\" y=\"220\" class=\"tm b2\" font-size=\"14\" text-anchor=\"start\">나머지 전부<\/text><rect x=\"140\" y=\"206\" width=\"300\" height=\"18\" rx=\"2\" class=\"n b2\"/><text x=\"290\" y=\"220\" class=\"tl b2\" font-size=\"14\" text-anchor=\"middle\">0.65<\/text><text x=\"240\" y=\"258\" class=\"tb b2\" font-size=\"15\" text-anchor=\"middle\">모든 후보(어휘 크기만큼)의 확률을 더하면 1<\/text><\/svg>","caption":"'the lecture will end at' 뒤에 9pm 0.2, noon 0.1, midnight 0.05, 나머지 후보가 0.65","builds":2}],"pass2":[{"kind":"compare","head":"영어 문장 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["**Language Modeling: The Task**","언어 모델링이라는 과제"],["given a prefix, predict a probability distribution over the next word","앞부분이 주어지면, 다음 단어의 확률 분포를 내요"],["assigns a probability to any piece of text","어떤 글이든 그 글 전체의 확률을 매겨요"],["chain rule of probability","확률의 연쇄 법칙(한 단어씩 확률을 곱하기)"],["One innocent-looking task, it will carry us all the way to GPT","순해 보이는 이 과제 하나가 GPT 까지 이어져요"]]},{"kind":"points","head":"용어 하나씩","items":["**언어 모델(LM)**: 앞 단어들을 보고 다음 단어의 확률을 내는 모델","**다음 토큰 예측(Next Token Prediction)**: 지금까지의 토큰으로 바로 다음 토큰 맞히기. 언어 모델이 하는 일 그 자체","**확률 분포(Probability Distribution)**: 후보마다 확률을 붙인 목록. 모두 더하면 1","**조건부 확률(Conditional Probability)**: 'B 가 주어졌을 때 A 의 확률' P(A | B). 앞 단어가 주어졌을 때 다음 단어의 확률","**확률의 연쇄 법칙(Chain Rule of Probability)**: 글 전체 확률 = 한 단어씩의 조건부 확률을 모두 곱한 것"]},{"kind":"steps","head":"무엇이 무엇으로 이어지나","steps":["앞부분(prefix) 'the lecture will end at' 이 들어와요","**언어 모델(LM)**이 **어휘(Vocabulary)**의 모든 후보에 확률을 붙여요","그게 다음 단어의 **확률 분포(Probability Distribution)**예요: 9pm 0.2, noon 0.1, ...","한 단어씩 이 확률을 곱해 가면 글 전체의 확률도 나와요(**확률의 연쇄 법칙(Chain Rule of Probability)**)"],"answer":"다음 단어 확률을 낼 수 있으면, 글 전체의 확률도 낼 수 있어요"},{"kind":"check","q":"언어 모델(Language Model)이 내는 것은?","choices":["다음 단어 후보마다 붙은 확률(확률 분포)","문장의 문법 오류 목록","단어의 뜻풀이"],"a":0,"why":"**언어 모델(LM)**은 앞부분이 주어지면 다음 단어의 **확률 분포(Probability Distribution)**를 내요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.625,"h":0.042,"say":"'given a prefix, predict a probability distribution over the next word': 앞부분 → 다음 단어 확률 분포"},{"x":0.075,"y":0.241,"w":0.686,"h":0.036,"say":"예: 'the lecture will end at ___' → {9pm: 0.2, noon: 0.1, midnight: 0.05, ...}"},{"x":0.061,"y":0.289,"w":0.664,"h":0.041,"say":"같은 말로: 어떤 글이든 확률을 매기는 모델(확률의 연쇄 법칙)"},{"x":0.193,"y":0.425,"w":0.225,"h":0.102,"say":"왼쪽 식: x(1)~x(t)가 주어졌을 때 다음 단어 x(t+1)의 조건부 확률"},{"x":0.468,"y":0.412,"w":0.339,"h":0.121,"say":"오른쪽 식: 글 전체 확률 = 각 단어의 '앞 단어들이 주어졌을 때' 확률을 모두 곱한 것"},{"x":0.296,"y":0.86,"w":0.411,"h":0.038,"say":"순해 보이는 과제 하나가 GPT 까지 이어져요"}]},{"kind":"formula","head":"다음 단어의 확률 (언어 모델이 내는 것)","tex":"P\\left(x^{(t+1)} \\mid x^{(t)}, \\ldots, x^{(1)}\\right)","parts":[{"sym":"x^{(1)}, \\ldots, x^{(t)}","say":"지금까지 나온 단어(토큰) t 개. 위 첨자 (t)는 '몇 번째 자리'라는 뜻"},{"sym":"x^{(t+1)}","say":"바로 다음 자리에 올 단어. 맞히려는 것"},{"sym":"\\mid","say":"'~가 주어졌을 때'라고 읽어요. 조건부 확률 표시"},{"sym":"P(\\cdot)","say":"어휘의 후보마다 이 값을 내면 확률 분포가 돼요. 모두 더하면 1"}],"whole":"지금까지의 단어들이 주어졌을 때, 다음 단어가 무엇일지 후보마다 확률을 내는 것이 **언어 모델(LM)**이에요."},{"kind":"formula","head":"확률의 연쇄 법칙: 글 전체의 확률","tex":"P\\left(x^{(1)}, \\ldots, x^{(T)}\\right) = \\prod_{t=1}^{T} P\\left(x^{(t)} \\mid x^{(<t)}\\right)","parts":[{"sym":"P(x^{(1)}, \\ldots, x^{(T)})","say":"T 개 단어로 된 글 전체가 나올 확률"},{"sym":"\\prod_{t=1}^{T}","say":"t = 1 부터 T 까지 모두 곱하라는 기호(파이)"},{"sym":"x^{(<t)}","say":"t 번째보다 앞에 나온 모든 단어"},{"sym":"P(x^{(t)} \\mid x^{(<t)})","say":"앞 단어들이 주어졌을 때 t 번째 단어의 확률. 언어 모델이 매번 내는 값"}],"whole":"글 전체 확률은 '다음 단어 확률'을 한 단어씩 곱한 것이에요. 그래서 다음 단어만 잘 맞히면 글 전체의 확률도 매길 수 있어요."},{"kind":"steps","head":"손계산: 확률 분포와 연쇄 법칙","steps":["슬라이드 후보: 9pm 0.2 + noon 0.1 + midnight 0.05 = 0.35","확률 분포는 모두 더해 1이어야 하니, 나머지 후보들이 1 - 0.35 = 0.65 를 나눠 가져요","예시 숫자로 연쇄 법칙: P(첫 단어) = 0.1, P(둘째 | 첫) = 0.5, P(셋째 | 첫, 둘째) = 0.2","세 단어 글 전체의 확률 = 0.1 x 0.5 x 0.2 = 0.01"],"answer":"나머지 후보 몫 0.65, 예시 글의 확률 0.01","given":"앞 두 줄은 슬라이드 숫자, 뒤 두 줄은 설명용 예시 숫자"},{"kind":"prof","when":"3주차 월요일 2교시","lines":["자연어처리에서는 랭귀지 모델링이라는 태스크가 거의 알파부터 오메가라고 보면 된다고 했어요.","후보는 몇 개일까요? 쌓아 놓은 어휘(vocab) 개수만큼 있고, 모두 더하면 1이라고 했어요.","\"지금까지 토큰으로 다음 토큰을 예측하는 next token prediction 이 거의 모든 걸 결정한다, GPT 도 다 결국 이거다.\""]},{"kind":"bg","src":"기초 다지기 5단원 (확률 기초)","lines":["P(A | B) 는 조건부 확률, 'B 가 주어졌을 때 A 의 확률'이에요.","곱의 규칙: P(A, B) = P(A) x P(B | A). 이걸 여러 번 이으면 연쇄 법칙이 돼요."]},{"kind":"say","lines":["실습에서는 N3L p.9 에서 입력 x 를 한 칸 민 것을 정답 y 로 만들어요('shifted by one').","곧 모든 자리에서 '다음 글자 맞히기'를 시키는 거예요."]}],"pass4":[{"kind":"check","q":"언어 모델의 다음 단어 후보는 모두 몇 개인가요? (녹음 설명)","choices":["어휘(Vocabulary) 크기만큼","항상 10개","앞 문장 길이만큼"],"a":0,"why":"교수님: 후보는 쌓아 놓은 **어휘(Vocabulary)** 개수만큼이고, 모두의 확률을 더하면 1이에요."},{"kind":"english","head":"답안에 쓸 문장","en":"언어 모델(Language Model)은 앞의 단어들 x(1)~x(t)가 주어졌을 때 다음 단어 x(t+1)의 조건부 확률 분포를 예측하는 모델이며, 확률의 연쇄 법칙으로 글 전체의 확률도 매길 수 있다.","ko":"다음 단어 확률 = 언어 모델, 그 곱 = 글 전체 확률.","tip":"앞부분 → 다음 단어 분포 → 곱하면 문장 확률"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**확률의 연쇄 법칙(Chain Rule of Probability)**은 확률을 곱으로 쪼개는 규칙이에요. 2부 역전파의 연쇄 법칙(Chain Rule, 미분)과 이름만 같아요.","확률 분포의 합은 늘 1이에요. 슬라이드에 보이는 세 후보(0.35)가 전부가 아니에요."]}]},{"p":36,"title":"매일 쓰는 언어 모델","terms":["Language Model (LM)","Large Language Model (LLM)","Next Token Prediction","Token","Sampling"],"pass1":[{"kind":"say","lines":["사실 여러분은 이미 **언어 모델(LM)**을 매일 쓰고 있어요.","휴대폰 자판, 검색창, 음성 인식, 그리고 ChatGPT 까지요."]},{"kind":"points","head":"언어 모델이 숨어 있는 곳","items":["휴대폰 자판 자동 완성: 다음 단어 후보를 줄 세워요","검색어 추천: '자연어처리' 뒤에 강의, 책, 예제","음성 인식과 번역: 비슷한 후보 중 더 자연스러운 쪽 고르기","ChatGPT: 아주 큰 **언어 모델(LM)**이 다음 토큰을 계속 뽑는 것"]}],"pass2":[{"kind":"compare","head":"영어 문장 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["**You Use One Every Day**","여러분은 매일 하나씩 써요"],["Keyboard autocomplete: ranks your next word as you type","자판 자동 완성: 치는 동안 다음 단어를 줄 세워요"],["Search suggestions: that's a LM over queries","검색어 추천: 검색어에 대한 언어 모델이에요"],["choosing between similar-sounding outputs","비슷하게 들리는 후보 중 고르기"],["sampling the next token again and again, that's the whole trick","다음 토큰을 거듭 뽑는 것, 그게 비결의 전부예요"],["LLM = Large Language Model","LLM = 대규모 언어 모델. 가운데 LM 이 오늘 주제"]]},{"kind":"points","head":"용어 하나씩","items":["**대규모 언어 모델(LLM)**: 아주 큰 언어 모델. 가운데 두 글자 LM 이 오늘 배우는 것","**샘플링(Sampling)**: 확률 분포에서 제비뽑기처럼 후보 하나를 뽑기","**다음 토큰 예측(Next Token Prediction)**: ChatGPT 도 결국 다음 토큰 맞히기를 되풀이해요"]},{"kind":"check","q":"LLM 의 가운데 두 글자 LM 은 무엇의 줄임말인가요?","choices":["Language Model (언어 모델)","Linear Map","Loss Minimum"],"a":0,"why":"**대규모 언어 모델(LLM)** = Large **언어 모델(LM)**. 가운데가 오늘의 주제예요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.201,"w":0.454,"h":0.038,"say":"Keyboard autocomplete: 치는 동안 다음 단어 후보를 줄 세워요"},{"x":0.061,"y":0.254,"w":0.621,"h":0.041,"say":"Search suggestions: '자연어처리 ...' → 강의, 책, 예제. 검색어에 대한 언어 모델"},{"x":0.061,"y":0.31,"w":0.864,"h":0.038,"say":"Speech recognition & translation: 비슷하게 들리는 후보 중 무엇이 더 그럴듯한지 언어 모델에게 묻기"},{"x":0.061,"y":0.364,"w":0.761,"h":0.039,"say":"ChatGPT & friends: 아주 큰 LM 이 다음 토큰을 거듭 뽑기, 'that's the whole trick'"},{"x":0.257,"y":0.86,"w":0.493,"h":0.038,"say":"LLM = Large Language Model, 가운데 글자가 오늘 주제"}]},{"kind":"prof","when":"3주차 월요일 2교시","lines":["음성 인식도 헷갈려요. '아'라고 했는지 '야'라고 했는지, 지금까지 나온 단어를 보고 더 그럴듯한 쪽을 고르는 데 언어 모델이 도움을 준다고 했어요.","번역에서도 더 자연스러운 토큰을 고르는 데 언어 모델이 역할을 한다고 했어요.","추론(inference)은 예측하고, 붙이고, 붙인 것에서 또 예측하고 붙이는 것. LLM 같은 거대한 트랜스포머도 여전히 다음 토큰 예측으로 학습된다고 했어요."]},{"kind":"points","head":"다시 말하면","items":["네 가지 모두 '앞 글을 보고 다음(또는 더 그럴듯한) 것 고르기'예요","ChatGPT 는 **샘플링(Sampling)**로 다음 **토큰(Token)**을 하나 뽑아 붙이고, 또 뽑아 붙여요","그래서 오늘 배우는 작은 언어 모델과 ChatGPT 는 같은 고리를 돌아요(p.40 에서 다시 봐요)"]},{"kind":"say","lines":["실습에서는 N3L p.15 의 generate 함수가 이 '뽑고 붙이기' 고리를 코드로 보여 줘요."]}],"pass4":[{"kind":"check","q":"음성 인식에서 언어 모델은 어떤 일을 돕나요?","choices":["비슷하게 들리는 후보 중 문맥상 더 그럴듯한 것을 고른다","소리의 크기를 키운다","말하는 사람의 이름을 맞힌다"],"a":0,"why":"슬라이드: choosing between similar-sounding outputs = asking a LM which is more plausible."},{"kind":"english","head":"답안에 쓸 문장","en":"ChatGPT 같은 대규모 언어 모델(LLM)도 앞의 토큰들을 보고 다음 토큰의 확률 분포를 낸 뒤 하나를 샘플링해 붙이는 일을 반복하는 언어 모델(LM)이다.","ko":"LLM 의 비결 = 다음 토큰 예측의 반복.","tip":"뽑고, 붙이고, 또 뽑기"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["검색어 추천, 자판 자동 완성은 '다른 기술'이 아니라 모두 **언어 모델(LM)**의 예예요.","LLM 이 크다고 원리가 다른 게 아니에요. 원리는 **다음 토큰 예측(Next Token Prediction)** 그대로예요."]}]},{"p":37,"title":"n-gram 언어 모델","terms":["n-gram","Markov Assumption","Corpus","Language Model (LM)","Conditional Probability","Next Token Prediction"],"pass1":[{"kind":"analogy","head":"바로 앞 몇 단어만 보고 맞히기","scene":"기억력이 짧은 친구가 끝말을 이어요. 이 친구는 바로 앞 세 단어만 기억하고 그 전은 잊어버려요. 그리고 '예전에 이 세 단어 뒤에 무엇이 몇 번 나왔더라?'를 떠올려 가장 많이 나온 것을 말해요.","map":[["바로 앞 세 단어만 기억","**마르코프 가정(Markov Assumption)**"],["세 단어 + 다음 단어 묶음","**n-gram(엔그램)** (여기서는 4-gram)"],["예전에 몇 번 나왔나 떠올리기","**말뭉치(Corpus)**에서 횟수 세기"]]},{"kind":"say","lines":["딥러닝 이전의 **언어 모델(LM)**이 바로 이 **n-gram(엔그램)** 모델이에요.","규칙은 딱 두 가지예요: 앞 몇 단어만 보고, 큰 글 모음에서 세어 본다."]}],"pass2":[{"kind":"compare","head":"영어 문장 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["**n-gram Language Models**","n-gram 언어 모델"],["The pre-deep-learning answer","딥러닝 이전의 답"],["n-gram = a chunk of n consecutive words","n-gram = 연달아 붙은 단어 n개 묶음"],["Markov assumption: the next word depends only on the previous n-1 words","마르코프 가정: 다음 단어는 앞 n-1 개 단어에만 달려 있다"],["Then just COUNT in a big corpus","그다음엔 큰 말뭉치에서 그냥 세요"]]},{"kind":"points","head":"용어 하나씩","items":["**n-gram(엔그램)**: 연달아 붙은 단어 n개 묶음. 2개면 bigram, 3개면 trigram, 4개면 4-gram","**마르코프 가정(Markov Assumption)**: 앞 n-1 개만 남기고 나머지 과거는 신경 쓰지 않기","**말뭉치(Corpus)**: 횟수를 세는 큰 글 모음","세기(COUNT): '앞 n-1 단어 + 다음 단어' 묶음 수 ÷ '앞 n-1 단어' 묶음 수"]},{"kind":"check","q":"4-gram 모델은 다음 단어를 맞힐 때 앞의 몇 단어를 보나요?","choices":["3단어","4단어","문장 전체"],"a":0,"why":"n-gram 은 앞 n-1 개를 봐요. 4-gram 이면 앞 3단어 + 맞힐 1단어 = 4단어 묶음이에요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.521,"h":0.038,"say":"'The pre-deep-learning answer': 딥러닝 이전의 답. n-gram = 연달은 n 단어 묶음"},{"x":0.061,"y":0.251,"w":0.554,"h":0.038,"say":"'Markov assumption': 다음 단어는 앞 n-1 개 단어에만 달려 있다고 쳐요"},{"x":0.196,"y":0.393,"w":0.529,"h":0.074,"say":"근사 식: 앞 단어 전부 대신 앞 n-1 개만 조건으로 남겨요"},{"x":0.371,"y":0.501,"w":0.393,"h":0.044,"say":"'keep only the last n-1 words': 마지막 n-1 단어만 남기기"},{"x":0.1,"y":0.666,"w":0.796,"h":0.131,"say":"세기: count(students opened their w) ÷ count(students opened their)"},{"x":0.282,"y":0.86,"w":0.439,"h":0.038,"say":"1주차 2막(통계 시대)의 실제 식이 이것이에요"}]},{"kind":"formula","head":"마르코프 가정: n-gram 근사","tex":"P\\left(x^{(t+1)} \\mid x^{(t)}, \\ldots, x^{(1)}\\right) \\approx P\\left(x^{(t+1)} \\mid x^{(t)}, \\ldots, x^{(t-n+2)}\\right)","parts":[{"sym":"x^{(t)}, \\ldots, x^{(1)}","say":"왼쪽: 지금까지 나온 모든 단어"},{"sym":"\\approx","say":"'거의 같다고 친다'. 가정으로 바꿔치기"},{"sym":"x^{(t)}, \\ldots, x^{(t-n+2)}","say":"오른쪽: 바로 앞 n-1 개 단어만 남긴 것"},{"sym":"n","say":"묶음 크기. 4-gram 이면 n = 4, 앞 3단어를 봐요"}],"whole":"먼 과거는 버리고 바로 앞 n-1 개 단어만 보고 다음 단어의 확률을 정한다는 가정이에요."},{"kind":"formula","head":"세어서 확률 구하기 (슬라이드 예)","tex":"P(w \\mid \\text{students opened their}) \\approx \\frac{\\mathrm{count}(\\text{students opened their } w)}{\\mathrm{count}(\\text{students opened their})}","parts":[{"sym":"w","say":"다음에 올 후보 단어 하나(books, exams, ...)"},{"sym":"\\mathrm{count}(\\text{students opened their } w)","say":"분자: 4단어 묶음이 말뭉치에 나온 횟수"},{"sym":"\\mathrm{count}(\\text{students opened their})","say":"분모: 앞 3단어 묶음이 나온 횟수"}],"whole":"'앞 3단어 뒤에 w 가 온 횟수'를 '앞 3단어가 나온 횟수'로 나누면 확률이에요. 학습이 아니라 세기예요."},{"kind":"steps","head":"n-1 이 맞는지 세어 보기","steps":["식의 오른쪽은 x^(t) 부터 x^(t-n+2) 까지예요","개수 = t - (t-n+2) + 1 = n - 1","n = 4 이면 x^(t), x^(t-1), x^(t-2) 의 3개","n = 2(bigram) 이면 바로 앞 1단어만"],"answer":"n-gram 은 앞 n-1 개 단어를 조건으로 봐요"},{"kind":"prof","when":"3주차 월요일 2교시","lines":["엔그램은 말 그대로 연속된 n 개의 단어 묶음이에요. students opened their books 4개면 4그램, books 를 떼면 3그램(트라이그램)이라고 했어요.","마르코프 과정은 과거는 신경 쓰지 않고 현재만 보겠다는 것, 그래서 내 엔그램만 보고 다음 단어를 예측한다고 했어요.","딥러닝 이전이라 카운팅 기법, 통계 기법이에요. 코퍼스에서 4개씩 묶어 다 모은 다음 개수를 구해요."]},{"kind":"bg","src":"기초 다지기 5단원 (확률 기초)","lines":["빈도로 확률 세기: 조건이 된 경우의 수 중에서 원하는 일이 일어난 비율이에요.","P(w | 앞 단어) = (앞 단어 뒤에 w 가 온 횟수) ÷ (앞 단어가 나온 횟수)."]}],"pass4":[{"kind":"check","q":"n-gram 언어 모델이 확률을 구하는 방법은?","choices":["말뭉치에서 단어 묶음이 나온 횟수를 세어 나눈다","경사 하강법으로 임베딩을 학습한다","사람이 확률을 직접 적어 넣는다"],"a":0,"why":"슬라이드: Then just COUNT in a big corpus. 학습이 아니라 세기예요."},{"kind":"english","head":"답안에 쓸 문장","en":"n-gram 언어 모델은 마르코프 가정(Markov Assumption)에 따라 다음 단어가 앞 n-1 개 단어에만 달려 있다고 보고, 말뭉치(Corpus)에서 n-gram 과 (n-1)-gram 의 횟수를 세어 그 비율로 조건부 확률을 구한다.","ko":"앞 n-1 개만 보기 + 세어서 나누기.","tip":"마르코프로 자르고, 세어서 나눈다"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["n-gram 의 n 은 '묶음 전체 크기'예요. 조건으로 보는 앞 단어는 n-1 개예요(4-gram → 앞 3단어).","분모는 '앞 n-1 단어 묶음'의 횟수예요. 전체 단어 수로 나누지 않아요."]}]},{"p":38,"title":"n-gram 예제: 시험 감독관 문장","terms":["n-gram","Markov Assumption","Corpus","Conditional Probability","Language Model (LM)","Recurrent Neural Network (RNN)"],"pass1":[{"kind":"say","lines":["'as the proctor started the clock, the students opened their ___'","proctor 는 시험 감독관이에요. 감독관이 시계를 켰으니 빈칸은 exams(시험지)가 어울려요.","그런데 4-gram 모델은 앞 3단어 'students opened their'만 봐요."]},{"kind":"figure","head":"앞 3단어만 남기고 나머지는 버려요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"30\" class=\"tb\" font-size=\"15\" text-anchor=\"middle\">4-gram: 앞 3단어만 보고 다음 단어 맞히기<\/text><rect x=\"10\" y=\"70\" width=\"70\" height=\"40\" rx=\"2\" class=\"n\"/><text x=\"45.0\" y=\"94.66666666666667\" class=\"tm\" font-size=\"14\" text-anchor=\"middle\">proctor<\/text><rect x=\"88\" y=\"70\" width=\"70\" height=\"40\" rx=\"2\" class=\"n\"/><text x=\"123.0\" y=\"94.66666666666667\" class=\"tm\" font-size=\"14\" text-anchor=\"middle\">clock<\/text><rect x=\"166\" y=\"70\" width=\"70\" height=\"40\" rx=\"2\" class=\"n2 b1\"/><text x=\"201.0\" y=\"94.66666666666667\" class=\"tl b1\" font-size=\"14\" text-anchor=\"middle\">students<\/text><rect x=\"244\" y=\"70\" width=\"70\" height=\"40\" rx=\"2\" class=\"n2 b1\"/><text x=\"279.0\" y=\"94.66666666666667\" class=\"tl b1\" font-size=\"14\" text-anchor=\"middle\">opened<\/text><rect x=\"322\" y=\"70\" width=\"70\" height=\"40\" rx=\"2\" class=\"n2 b1\"/><text x=\"357.0\" y=\"94.66666666666667\" class=\"tl b1\" font-size=\"14\" text-anchor=\"middle\">their<\/text><rect x=\"400\" y=\"70\" width=\"70\" height=\"40\" rx=\"2\" class=\"box2 b1\"/><text x=\"435.0\" y=\"95.33333333333333\" class=\"tb b1\" font-size=\"16\" text-anchor=\"middle\">?<\/text><text x=\"85\" y=\"140\" class=\"tm b2\" font-size=\"14\" text-anchor=\"middle\">버림 (Markov 가정)<\/text><line x1=\"10\" y1=\"150\" x2=\"158\" y2=\"150\" class=\"e b2\"/><text x=\"283\" y=\"140\" class=\"tb b1\" font-size=\"14\" text-anchor=\"middle\">이 3단어만 봐요<\/text><text x=\"240\" y=\"190\" class=\"t b2\" font-size=\"14\" text-anchor=\"middle\">count(students opened their books) = 400<\/text><text x=\"240\" y=\"215\" class=\"t b2\" font-size=\"14\" text-anchor=\"middle\">÷ count(students opened their) = 1000<\/text><text x=\"240\" y=\"250\" class=\"tb b2\" font-size=\"16\" text-anchor=\"middle\">P(books | ...) = 0.40<\/text><\/svg>","caption":"proctor, clock 은 버려지고, students opened their 뒤에 books 가 400/1000 = 0.40","builds":2}],"pass2":[{"kind":"compare","head":"영어 문장 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["**n-gram, a Worked Example**","n-gram 풀어 본 예제"],["4-gram model, so we keep the last 3 words and throw the rest away","4-gram 이라 마지막 3단어만 남기고 나머지는 버려요"],["discarded by the Markov assumption","마르코프 가정 때문에 버려진 부분"],["condition on these 3 words","이 3단어를 조건으로 봐요"],["that context was thrown away","그 문맥(proctor, clock)이 버려졌어요"],["The model is not wrong, it was FORCED to forget the words that mattered","모델이 틀린 게 아니라, 중요한 단어를 잊도록 강요당했어요"]]},{"kind":"steps","head":"무엇이 무엇으로 이어지나","steps":["**마르코프 가정(Markov Assumption)**: 4-gram 이니 앞 3단어 students opened their 만 남겨요","**말뭉치(Corpus)**에서 셉니다: students opened their 1,000번","그 뒤에 books 400번, exams 100번","books 0.40 > exams 0.10 → 모델은 books 를 골라요","하지만 버려진 proctor, clock 은 exams 를 가리켰어요"],"answer":"중요한 단서가 3단어 밖에 있으면 n-gram 은 볼 수 없어요"},{"kind":"check","q":"이 예제에서 n-gram 모델이 exams 대신 books 를 고르는 까닭은?","choices":["proctor, clock 같은 단서가 3단어 밖이라 버려졌기 때문","books 라는 단어가 어휘에 없어서","계산 실수 때문"],"a":0,"why":"슬라이드: 모델은 틀린 게 아니라 중요한 단어를 잊도록 강요당했어요(**마르코프 가정(Markov Assumption)**)."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.089,"y":0.362,"w":0.457,"h":0.067,"say":"회색 단어들: as the proctor started the clock, the. 마르코프 가정으로 버려져요"},{"x":0.546,"y":0.362,"w":0.246,"h":0.067,"say":"주황 상자 3개: students opened their. 이 3단어만 조건으로 봐요"},{"x":0.154,"y":0.508,"w":0.439,"h":0.041,"say":"count(students opened their) = 1,000"},{"x":0.154,"y":0.558,"w":0.579,"h":0.091,"say":"books 400 → P = 0.40, exams 100 → P = 0.10"},{"x":0.154,"y":0.683,"w":0.629,"h":0.038,"say":"하지만 proctor 와 clock 때문에 exams 가 더 나은 답이었어요, 그 문맥이 버려졌어요"}]},{"kind":"steps","head":"손계산: 슬라이드 숫자 그대로","steps":["분모: count(students opened their) = 1,000","P(books | students opened their) = 400 ÷ 1,000 = 0.40","P(exams | students opened their) = 100 ÷ 1,000 = 0.10","연습: 어떤 단어가 300번이었다면 300 ÷ 1,000 = 0.30"],"answer":"books 0.40, exams 0.10 → n-gram 은 books 를 더 그럴듯하다고 봐요","given":"4-gram, 앞 3단어 students opened their"},{"kind":"steps","head":"손계산: 한 번도 못 본 묶음이면 (예시)","steps":["예시로 students opened their laptops 가 말뭉치에 0번이라고 해요","P(laptops | students opened their) = 0 ÷ 1,000 = 0","글 전체 확률은 한 단어씩의 확률을 곱해요(p.35 연쇄 법칙)","곱 속에 0이 하나라도 있으면: 0.4 x 0.5 x 0 = 0","앞 3단어 자체가 0번이면 0 ÷ 0, 나눌 수가 없어요"],"answer":"분자 0 → 확률 0(문장 전체 0), 분모 0 → 계산 불가. 다음 쪽의 희소성 문제예요","given":"laptops 횟수와 0.4, 0.5 는 설명용 예시 숫자"},{"kind":"prof","when":"3주차 월요일 2교시","lines":["앞 문장에 proctor(시험 감독관)나 clock(시간) 같은 단서가 있으니 사실 books 보다 exams 가 나올 가능성이 더 높아야 한다고 했어요.","n-gram 통계 기반은 마르코프 가정 때문에 앞 정보를 전혀 보지 못해서, 필요한 정보가 멀리 있으면 강제로 잊어버린다고 했어요.","그래서 '앞 문맥을 버리지 않고 계속 기억하며 읽을 수 있을까?'가 뒤의 시퀀스 모델(**RNN(순환 신경망)**)로 이어진다고 했어요."]},{"kind":"bg","src":"기초 다지기 5단원 (확률 기초)","lines":["0을 곱하면 무엇이든 0이에요. 곱으로 만든 확률은 한 조각만 0이어도 전체가 0이 돼요.","0으로 나누기는 정의되지 않아요. 조건이 한 번도 없으면 조건부 확률을 셀 수 없어요."]}],"pass4":[{"kind":"check","q":"count(students opened their) = 1,000, count(students opened their exams) = 100 일 때 P(exams | students opened their) 는?","choices":["0.10","0.40","100"],"a":0,"why":"100 ÷ 1,000 = 0.10. 분모는 앞 3단어 묶음의 횟수예요."},{"kind":"english","head":"답안에 쓸 문장","en":"4-gram 모델은 마르코프 가정에 따라 앞 3단어만 조건으로 보기 때문에, 그보다 앞에 있는 중요한 문맥(예: proctor, clock)을 강제로 버리게 되어 books(0.40)를 exams(0.10)보다 높게 예측한다.","ko":"모델이 틀린 게 아니라 잊도록 강요당한 것.","tip":"400/1000 = 0.40, 100/1000 = 0.10"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["녹음에서는 books 확률이 '0.45'처럼 들리지만 슬라이드 계산은 400 ÷ 1,000 = 0.40 이에요. 시험에서는 계산대로 0.40.","n-gram 이 '틀렸다'가 아니라 마르코프 가정 때문에 '볼 수 없었다'가 슬라이드의 요점이에요."]}]},{"p":39,"title":"세기가 부딪히는 벽","terms":["Sparsity Problem","Smoothing","Back-off","n-gram","Corpus","One-hot Vector","Embedding","Markov Assumption","Language Model (LM)"],"pass1":[{"kind":"figure","head":"세기만으로는 넘기 힘든 세 개의 벽","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"26\" class=\"tb\" font-size=\"16\" text-anchor=\"middle\">세기(counting)가 부딪히는 벽<\/text><rect x=\"15\" y=\"60\" width=\"140\" height=\"110\" rx=\"2\" class=\"n4 b1\"/><text x=\"85.0\" y=\"119.66666666666667\" class=\"tl b1\" font-size=\"14\" text-anchor=\"middle\"><\/text><text x=\"85\" y=\"105\" class=\"tl b1\" font-size=\"16\" text-anchor=\"middle\">희소성<\/text><text x=\"85\" y=\"135\" class=\"tl b1\" font-size=\"13\" text-anchor=\"middle\">0번 → 확률 0<\/text><rect x=\"170\" y=\"60\" width=\"140\" height=\"110\" rx=\"2\" class=\"n4 b2\"/><text x=\"240.0\" y=\"119.66666666666667\" class=\"tl b2\" font-size=\"14\" text-anchor=\"middle\"><\/text><text x=\"240\" y=\"105\" class=\"tl b2\" font-size=\"16\" text-anchor=\"middle\">저장 공간<\/text><text x=\"240\" y=\"135\" class=\"tl b2\" font-size=\"13\" text-anchor=\"middle\">묶음마다 횟수<\/text><rect x=\"325\" y=\"60\" width=\"140\" height=\"110\" rx=\"2\" class=\"n4 b3\"/><text x=\"395.0\" y=\"119.66666666666667\" class=\"tl b3\" font-size=\"14\" text-anchor=\"middle\"><\/text><text x=\"395\" y=\"105\" class=\"tl b3\" font-size=\"16\" text-anchor=\"middle\">유사도 없음<\/text><text x=\"395\" y=\"135\" class=\"tl b3\" font-size=\"13\" text-anchor=\"middle\">their ≠ her<\/text><text x=\"240\" y=\"210\" class=\"tm b3\" font-size=\"15\" text-anchor=\"middle\">+ 앞 n-1 단어 밖은 안 보임<\/text><text x=\"240\" y=\"245\" class=\"tb b3\" font-size=\"15\" text-anchor=\"middle\">신경망 언어 모델이 벽을 허물어요<\/text><\/svg>","caption":"희소성, 저장 공간, 유사도 없음. 그리고 앞 n-1 단어 밖은 보이지 않아요","builds":3},{"kind":"say","lines":["**n-gram(엔그램)**은 세기만 하니 간단하지만, 벽이 세 개 있어요.","안 나온 건 0, 셀 게 너무 많고, 비슷한 단어를 몰라요.","4부의 **고정 윈도우 신경망 언어 모델(Fixed-window Neural LM)**이 **임베딩(Embedding)** 덕분에 이 벽을 허물어요."]}],"pass2":[{"kind":"compare","head":"영어 문장 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["**Where Counting Breaks**","세기가 부서지는 곳"],["Sparsity: numerator never seen → probability 0 (fix: smoothing)","희소성: 분자를 못 봤으면 확률 0 (고치기: 스무딩)"],["denominator never seen → cannot condition at all (fix: back off)","분모를 못 봤으면 조건을 걸 수조차 없음 (고치기: 더 짧은 문맥으로 백오프)"],["it gets WORSE as n grows, in practice n ≤ 5","n 이 커질수록 심해져서 실제로는 n ≤ 5"],["Storage: grows with corpus × n","저장: 말뭉치 크기와 n 에 따라 불어나요"],["Blindness: no notion of similarity","눈멂: 비슷함이라는 개념이 없어요"],["Discarded context: everything beyond n-1 words is invisible","버려진 문맥: n-1 단어 밖은 아무리 중요해도 안 보여요"]]},{"kind":"points","head":"용어 하나씩","items":["**희소성 문제(Sparsity Problem)**: 셀 묶음이 거의 안 나와서 0 투성이인 문제","**스무딩(Smoothing)**: 못 본 묶음에도 아주 작은 확률을 나눠 주기(분자 0 고치기)","**백오프(Back-off)**: 긴 문맥으로 못 세면 더 짧은 문맥으로 물러나기(분모 0 고치기)","저장(Storage): 본 적 있는 n-gram 마다 횟수를 적어 둬야 해요","유사도 없음: 'opened their'와 'opened her'는 횟수를 전혀 나누지 않아요. **원-핫 벡터(One-hot Vector)**과 같은 병"]},{"kind":"check","q":"분모(앞 문맥)가 말뭉치에 한 번도 없을 때 슬라이드가 말하는 고치기는?","choices":["더 짧은 문맥으로 물러나기(Back-off)","스무딩(Smoothing)","n 을 더 키우기"],"a":0,"why":"분자 0 → **스무딩(Smoothing)**, 분모 0 → **백오프(Back-off)**. n 을 키우면 오히려 더 나빠져요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.864,"h":0.08,"say":"Sparsity: 분자 0 → 확률 0(스무딩), 분모 0 → 조건 불가(더 짧은 문맥으로 백오프)"},{"x":0.114,"y":0.282,"w":0.318,"h":0.038,"say":"n 이 커질수록 나빠져요. 실제로는 n ≤ 5"},{"x":0.061,"y":0.336,"w":0.611,"h":0.042,"say":"Storage: 본 n-gram 마다 횟수 저장, 말뭉치 x n 으로 불어나요"},{"x":0.061,"y":0.393,"w":0.836,"h":0.041,"say":"Blindness: 'opened their'와 'opened her'가 횟수를 안 나눠요. 2주차의 그 병(비슷함 없음)"},{"x":0.061,"y":0.451,"w":0.607,"h":0.042,"say":"Discarded context: n-1 단어 밖은 아무리 중요해도 안 보여요"},{"x":0.196,"y":0.86,"w":0.614,"h":0.038,"say":"세 벽: 희소성, 저장, 유사도. 오늘 신경망 언어 모델이 둘을 허물어요"}]},{"kind":"steps","head":"왜 n 이 커질수록 나빠지나 (가능한 조합 수)","steps":["어휘가 1만 개라고 해요","앞 1단어 문맥의 종류: 1만 가지","2단어 묶음의 종류: 1만 x 1만 = 1억 가지","3단어 묶음의 종류: 1만^3 = 1조 가지","말뭉치가 아무리 커도 1조 가지를 다 보기는 어려워요 → 대부분 0번"],"answer":"n 이 1 늘 때마다 조합이 어휘 크기 배로 늘어요. 그래서 희소성이 심해지고 실제로는 n ≤ 5","given":"어휘 1만 개는 설명용 숫자"},{"kind":"prof","when":"3주차 월요일 2교시","lines":["스튜던츠 오픈드 데어라는 문장 자체도 많이 안 나오고, 그 뒤 단어도 개수가 많지 않아서 어휘 대부분에 대해 값이 거의 다 0이라고 했어요.","스무딩이나 더 짧은 문맥으로 가는 백오프로 개선할 수는 있지만 아주 좋은 방법은 아니라고 했어요.","opened their, opened her, opened his 는 의미상 똑같은데 n-gram 은 완전 별개 항목이라 정보를 공유하지 못한다, '말로 하면 입 아플 정도로 안 좋은 점이 많다'고 했어요."]},{"kind":"bg","src":"기초 다지기 1단원 (벡터, 원-핫 벡터 맛보기)","lines":["**원-핫 벡터(One-hot Vector)**끼리는 내적이 늘 0이라 비슷함을 모른다는 게 2주차의 병이었어요.","n-gram 이 their 와 her 를 남남으로 보는 것도 같은 병이에요. 해결책은 **임베딩(Embedding)**(단어의 지도 좌표)예요."]}],"pass4":[{"kind":"check","q":"슬라이드가 말하는 n-gram 의 세 벽이 아닌 것은?","choices":["학습 속도가 너무 빠르다","희소성(Sparsity)","저장 공간(Storage)","유사도 없음(Similarity)"],"a":0,"why":"세 벽은 sparsity, storage, similarity 예요. n-gram 은 학습이 아니라 세기라서 빠르기는 문제가 아니에요."},{"kind":"english","head":"답안에 쓸 문장","en":"n-gram 언어 모델에는 희소성 문제(Sparsity Problem), 저장 공간 문제, 유사도 없음의 세 벽과, n-1 단어 밖 문맥을 볼 수 없다는 한계가 있다.","ko":"벽 셋 + 버려진 문맥.","tip":"희소, 저장, 유사도 + 문맥"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["분자 0 → **스무딩(Smoothing)**, 분모 0 → **백오프(Back-off)**. 짝을 바꿔 외우지 마세요.","n 을 키우면 문맥은 길어지지만 희소성과 저장이 더 나빠져요. 그래서 실제로는 n ≤ 5 예요.","유사도 없음의 뿌리는 단어를 **원-핫 벡터(One-hot Vector)**처럼 남남으로 다루는 것, 해결은 **임베딩(Embedding)**이에요."]}]},{"p":40,"title":"n-gram 언어 모델로 글 쓰기","terms":["Language Model (LM)","Sampling","n-gram","Probability Distribution","Temperature","Large Language Model (LLM)","Recurrent Neural Network (RNN)","Softmax"],"pass1":[{"kind":"figure","head":"만들고, 뽑고, 붙이고, 되풀이","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect x=\"160\" y=\"20\" width=\"160\" height=\"44\" rx=\"2\" class=\"box2\"/><text x=\"240.0\" y=\"47.0\" class=\"tb\" font-size=\"15\" text-anchor=\"middle\">확률 분포 만들기<\/text><rect x=\"320\" y=\"150\" width=\"140\" height=\"44\" rx=\"2\" class=\"n3 b1\"/><text x=\"390.0\" y=\"177.0\" class=\"tl b1\" font-size=\"15\" text-anchor=\"middle\">하나 뽑기<\/text><rect x=\"20\" y=\"150\" width=\"140\" height=\"44\" rx=\"2\" class=\"n3 b2\"/><text x=\"90.0\" y=\"177.0\" class=\"tl b2\" font-size=\"15\" text-anchor=\"middle\">뒤에 붙이기<\/text><line x1=\"300\" y1=\"66\" x2=\"372.9\" y2=\"138.9\" class=\"e2 b1\"/><polygon points=\"380.0,146.0 369.4,142.5 376.5,135.4\" class=\"arrow b1\"/><line x1=\"318\" y1=\"172\" x2=\"174.0\" y2=\"172.0\" class=\"e2 b2\"/><polygon points=\"164.0,172.0 174.0,167.0 174.0,177.0\" class=\"arrow b2\"/><line x1=\"100\" y1=\"146\" x2=\"172.9\" y2=\"73.1\" class=\"e2 b3\"/><polygon points=\"180.0,66.0 176.5,76.6 169.4,69.5\" class=\"arrow b3\"/><text x=\"240\" y=\"120\" class=\"tb b3\" font-size=\"16\" text-anchor=\"middle\">되풀이<\/text><text x=\"240\" y=\"235\" class=\"t b3\" font-size=\"14\" text-anchor=\"middle\">today the → price → of → gold → is → shiny<\/text><text x=\"240\" y=\"260\" class=\"tm b3\" font-size=\"14\" text-anchor=\"middle\">ChatGPT 도 같은 고리, 모델 실력만 달라요<\/text><\/svg>","caption":"확률 분포에서 하나를 뽑아 뒤에 붙이고 다시 분포를 만들어요. ChatGPT 도 같은 고리예요","builds":3},{"kind":"analogy","head":"자판 추천 단어를 계속 누르기","scene":"휴대폰 자판에서 추천 단어 하나를 누르면 또 새 추천이 떠요. 그걸 또 누르고, 또 누르면 문장이 저절로 써져요. 다만 추천이 바로 앞 두 단어만 보고 뜬다면 문장이 점점 산으로 가요.","map":[["추천 단어 누르기","**샘플링(Sampling)** 후 붙이기"],["또 뜨는 새 추천","새 **확률 분포(Probability Distribution)**"],["앞 두 단어만 보는 추천","trigram **언어 모델(LM)**"]]}],"pass2":[{"kind":"compare","head":"영어 문장 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["**Generating with an n-gram LM**","n-gram 언어 모델로 글 생성하기"],["A LM is also a text generator: sample from the distribution, append, repeat","언어 모델은 글 생성기이기도 해요: 분포에서 뽑고, 붙이고, 반복"],["trigram LM: condition on the last 2 words","trigram 언어 모델: 마지막 2단어를 조건으로"],["locally grammatical but globally incoherent","가까이 보면 문법이 맞지만 전체로 보면 앞뒤가 안 맞아요"],["Same sampling loop as ChatGPT, the model quality is the only difference","ChatGPT 와 같은 뽑기 고리, 다른 건 모델 실력뿐"]]},{"kind":"steps","head":"생성 고리 한 바퀴씩","steps":["시작: today the","마지막 2단어 today the → 분포 {price 0.31, news 0.15, ...} → price 뽑기","the price → {of 0.62, ...} → of, price of → gold, of gold → is","gold is → {shiny 0.41, high 0.19, rising 0.12, ...} → shiny","결과: today the price of gold is \"shiny\""],"answer":"한 칸씩은 자연스럽지만 전체 문장은 어색해요"},{"kind":"points","head":"용어 하나씩","items":["**샘플링(Sampling)**: 분포에 따라 제비뽑기. 확률이 크면 자주 뽑히지만 늘 1등은 아니에요","locally grammatical: 이웃 단어끼리는 문법이 맞아요","globally incoherent: 문장 전체로는 앞뒤가 안 맞아요"]},{"kind":"check","q":"n-gram 언어 모델로 만든 글의 특징은?","choices":["가까이 보면 자연스럽지만 전체로는 앞뒤가 안 맞는다","문법이 늘 틀린다","항상 같은 문장만 나온다"],"a":0,"why":"슬라이드: locally grammatical but globally incoherent. 짧은 기억 때문이에요."}],"pass3":[{"kind":"look","head":"그림 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.536,"h":0.038,"say":"'A LM is also a text generator': 분포에서 뽑고, 붙이고, 반복"},{"x":0.218,"y":0.269,"w":0.486,"h":0.038,"say":"trigram LM: 마지막 2단어를 조건으로 → 다음 단어 뽑기 → 반복"},{"x":0.154,"y":0.34,"w":0.243,"h":0.254,"say":"today the → price 0.31, news 0.15 ... / the price → of 0.62, is 0.21 ..."},{"x":0.546,"y":0.34,"w":0.236,"h":0.254,"say":"of gold → is 0.34 ... / gold is → shiny 0.41, high 0.19 ..."},{"x":0.332,"y":0.624,"w":0.268,"h":0.042,"say":"결과: today the price of gold is \"shiny\""},{"x":0.061,"y":0.742,"w":0.582,"h":0.038,"say":"문법은 이웃끼리 맞지만 전체는 어색. 짧은 기억이 드러나요"}]},{"kind":"steps","head":"손계산: 이 경로가 뽑힐 확률 (슬라이드 숫자)","steps":["각 상자에서 뽑힌 단어의 확률: price 0.31, of 0.62, gold 0.57, is 0.34, shiny 0.41","연쇄 법칙대로 모두 곱해요: 0.31 x 0.62 = 0.1922","x 0.57 = 0.1096, x 0.34 = 0.0372, x 0.41 = 0.0153","재미있는 점: 다섯 번 모두 그 상자의 1등 후보가 뽑혔어요"],"answer":"'today the' 뒤에 이 다섯 단어가 이어질 확률 ≈ 0.0153 (약 1.5%)","given":"trigram, 시작 today the"},{"kind":"prof","when":"3주차 월요일 2교시","lines":["today the price of gold is 까지는 굉장히 자연스러운데, 앞이 price 였으니 gold is 다음에는 expected 같은 게 오면 좋겠죠.","그런데 gold is shiny 라는 trigram 자체는 어색하지 않아요. 금은 빛날 수 있죠. 하지만 전부 붙이면 이상해진다고 했어요.","로컬 플루언시는 챙길 수 있지만 롱 레인지 코히어런스(글로벌 플루언시)는 챙길 수 없다고 했어요. 이건 세기 기법과 상관없이 짧은 문맥의 문제예요."]},{"kind":"say","lines":["실습에서는 N3L p.15 generate 가 '분포 → 하나 뽑기(torch.multinomial) → 다시 넣기'를 되풀이해요.","N3L p.16 은 **샘플링 온도(Temperature)**를 0.5, 1.0, 1.5 로 바꿔 봐요. 낮으면 무난하고, 1.5 면 글자가 엉망이 돼요."]},{"kind":"bg","src":"기초 다지기 6단원 (소프트맥스와 교차 엔트로피)","lines":["실습의 온도는 점수(logits)를 온도로 나눈 뒤 **소프트맥스(Softmax)**를 해요.","온도가 작으면 1등 확률이 더 커지고, 크면 확률이 고르게 퍼져요."]}],"pass4":[{"kind":"check","q":"슬라이드의 trigram 예시에서 다음 단어를 정할 때 보는 것은?","choices":["바로 앞 2단어","바로 앞 3단어","문장 전체"],"a":0,"why":"trigram = 3단어 묶음이니 조건은 앞 2단어예요(today the → price)."},{"kind":"check","q":"샘플링 온도(Temperature)를 1.5 처럼 높이면?","choices":["엉뚱한 후보도 자주 뽑혀 글이 엉망이 되기 쉽다","늘 1등만 뽑힌다","모델이 다시 학습된다"],"a":0,"why":"실습 N3L p.16: 온도가 높을수록 확률이 고르게 퍼져 과감하게 뽑아요."},{"kind":"english","head":"답안에 쓸 문장","en":"언어 모델은 다음 단어의 확률 분포에서 하나를 샘플링(Sampling)해 붙이고 다시 예측하는 과정을 반복해 글을 생성한다. n-gram 은 앞 n-1 단어만 기억하므로 결과가 국소적으로는 문법적이지만 전체적으로는 일관성이 없다.","ko":"뽑고, 붙이고, 반복 + 짧은 기억의 한계.","tip":"locally grammatical, globally incoherent"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드 아래 줄은 'the 3-word memory shows'라고 하지만 그림은 trigram(앞 2단어 조건)이에요. trigram 은 묶음 3단어, 조건 2단어라고 기억해요.","샘플링은 1등만 고르는 게 아니에요. 이 예에서는 우연히 매번 1등이 뽑혔을 뿐이에요."]}]},{"p":41,"title":"언어 모델 재기: 퍼플렉서티","terms":["Perplexity (PPL)","Cross-Entropy","Loss Function","Geometric Mean","Vocabulary","Language Model (LM)","n-gram","Large Language Model (LLM)","Softmax"],"pass1":[{"kind":"analogy","head":"헷갈리는 후보가 평균 몇 개?","scene":"퀴즈에서 보기가 2개면 덜 헷갈리고, 100개면 많이 헷갈려요. 언어 모델이 다음 단어를 고를 때 '평균 몇 개 보기 사이에서 헷갈리는 정도인지'를 숫자 하나로 나타낸 게 퍼플렉서티예요.","map":[["퀴즈 보기 수","**퍼플렉서티(PPL)**"],["보기가 적을수록 쉬움","낮을수록 좋은 모델"],["보기 1개(정답만)","PPL = 1, 완벽한 모델"]]},{"kind":"say","lines":["**퍼플렉서티(PPL)**는 언어 모델의 성적표 숫자예요. 낮을수록 좋아요.","어휘 1만 개에 아무렇게나 찍으면 1만, 좋은 n-gram 은 100 쯤, 요즘 LLM 은 10 아래(예시)."]}],"pass2":[{"kind":"compare","head":"영어 문장 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["**Measuring LMs, Perplexity**","언어 모델 재기: 퍼플렉서티"],["Perplexity = exp(cross-entropy loss)","퍼플렉서티 = exp(교차 엔트로피 손실)"],["geometric-mean inverse probability","정답 확률의 역수를 기하 평균한 것"],["as confused as a fair choice among PPL words","PPL 개 단어 중에서 공평하게 찍는 것만큼 헷갈려요"],["uniform over 10k words → PPL 10,000","1만 단어에 똑같은 확률 → PPL 10,000"],["it drops out of the SAME cross-entropy loss we already train with","이미 학습에 쓰는 바로 그 교차 엔트로피 손실에서 나와요"]]},{"kind":"points","head":"용어 하나씩","items":["**퍼플렉서티(PPL)**: 다음 단어를 고를 때 헷갈리는 후보가 평균 몇 개인지. 낮을수록 좋아요","**교차 엔트로피(Cross-Entropy)**: 정답 단어 확률의 -log. 정답 확률이 클수록 작아요","**손실 함수(Loss Function)** J: 매 위치의 교차 엔트로피를 평균 낸 것","**기하 평균(Geometric Mean)**: 모두 곱하고 개수만큼 제곱근. 더해서 나누는 평균과 달라요"]},{"kind":"steps","head":"무엇이 무엇으로 이어지나","steps":["매 위치에서 정답 다음 단어에 모델이 준 확률 P 를 봐요","벌점 -log P 를 매겨요(**교차 엔트로피(Cross-Entropy)**)","위치마다의 벌점을 평균 내면 J","exp(J) 를 하면 **퍼플렉서티(PPL)**","학습도 같은 **손실 함수(Loss Function)** J 를 줄여요. 그래서 학습이 잘 되면 PPL 도 내려가요"],"answer":"PPL = exp(평균 교차 엔트로피)"},{"kind":"check","q":"퍼플렉서티(PPL)는 어느 쪽이 더 좋은 모델인가요?","choices":["낮을수록 좋다","높을수록 좋다","1000 에 가까울수록 좋다"],"a":0,"why":"슬라이드: lower is better. PPL 이 낮으면 헷갈리는 후보가 적다는 뜻이에요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.061,"y":0.197,"w":0.686,"h":0.038,"say":"'Perplexity = exp(cross-entropy loss)': 정답 확률 역수의 기하 평균"},{"x":0.175,"y":0.336,"w":0.429,"h":0.131,"say":"PPL = exp(J) = 각 위치 1/P 를 곱해 1/T 제곱"},{"x":0.639,"y":0.368,"w":0.186,"h":0.063,"say":"(lower is better): 낮을수록 좋아요"},{"x":0.061,"y":0.52,"w":0.621,"h":0.041,"say":"Intuition: 평균적으로 PPL 개 단어 중 공평하게 찍는 만큼 헷갈려요"},{"x":0.114,"y":0.566,"w":0.607,"h":0.038,"say":"1만 단어 균등 → 10,000, 좋은 n-gram ≈ 100, 요즘 LLM < 10 (예시)"},{"x":0.061,"y":0.617,"w":0.654,"h":0.041,"say":"이미 학습에 쓰는 같은 교차 엔트로피 손실에서 나와요"}]},{"kind":"formula","head":"퍼플렉서티 식","tex":"\\mathrm{PPL} = \\exp(J) = \\prod_{t=1}^{T} \\left( \\frac{1}{P\\left(x^{(t+1)} \\mid x^{(\\le t)}\\right)} \\right)^{1/T}","parts":[{"sym":"P(x^{(t+1)} \\mid x^{(\\le t)})","say":"t 번째까지 보고, 실제 정답 다음 단어에 모델이 준 확률"},{"sym":"\\frac{1}{P}","say":"그 확률의 역수. 확률 1/4 이면 4(후보 4개 중 찍는 느낌)"},{"sym":"\\prod_{t=1}^{T}","say":"T 개 위치 모두 곱하기"},{"sym":"(\\cdot)^{1/T}","say":"T 제곱근. 곱한 것의 평균(기하 평균)"},{"sym":"J","say":"교차 엔트로피 손실의 평균"}],"whole":"정답 확률의 역수를 기하 평균한 것이 퍼플렉서티이고, 이는 평균 교차 엔트로피 J 에 exp 를 씌운 것과 같아요."},{"kind":"formula","head":"J: 위치마다의 손실을 평균 내기","tex":"J = \\frac{1}{T} \\sum_{t=1}^{T} -\\log P\\left(x^{(t+1)} \\mid x^{(\\le t)}\\right)","parts":[{"sym":"-\\log P","say":"정답 단어 확률의 음의 로그. 한 위치의 교차 엔트로피 벌점"},{"sym":"\\sum_{t=1}^{T}","say":"T 개 위치의 벌점을 모두 더하기"},{"sym":"\\frac{1}{T}","say":"위치 수로 나눠 평균"},{"sym":"J","say":"평균 벌점. 학습이 줄이는 바로 그 손실"}],"whole":"학습 때 줄이는 손실 J 에 exp 만 씌우면 퍼플렉서티예요. 그래서 따로 계산할 게 거의 없어요."},{"kind":"steps","head":"손계산: 아무것도 모르는 모델","steps":["어휘 V = 10,000, 모든 단어에 똑같이 1/10,000","위치마다 벌점 -log(1/10,000) = log 10,000 ≈ 9.21","평균 J 도 9.21 (모든 위치가 같으니까)","PPL = exp(9.21) = 10,000"],"answer":"균등 분포면 PPL = 어휘 크기 V (슬라이드의 10,000)","given":"자연로그 사용"},{"kind":"prof","when":"3주차 월요일 2교시","lines":["소프트맥스에 음의 로그 우도(NLL)를 붙이면 크로스 엔트로피. 정답이 gold 일 때 gold 의 확률이 높을수록 로스가 떨어지고, 이상한 단어의 확률이 높으면 올라가요.","그 크로스 엔트로피 로스에 익스포넨셜을 취하면 바로 PPL 이라고 했어요.","PPL 이 100 이면 모델이 매 순간 대략 100 개 후보에서 하나를 고를 정도의 불확실성, 낮으면 낮을수록 좋다고 했어요."]},{"kind":"bg","src":"기초 다지기 4단원, 6단원 (로그와 지수, 교차 엔트로피)","lines":["exp 와 log 는 서로 되돌리는 짝이에요. exp(log 10,000) = 10,000.","로그는 곱을 합으로 바꿔요. 그래서 '곱의 T 제곱근'이 'log 합의 평균'의 exp 가 돼요."]},{"kind":"say","lines":["실습에서는 N3L p.17 에서 PPL = exp(평균 loss)를 직접 계산해요. 글자 모델은 25.92, 어휘 V = 1945 보다 훨씬 낮아요.","N3L p.12 학습 출력도 같아요: loss 3.254 → exp(3.254) ≈ 25.9."]}],"pass4":[{"kind":"check","q":"교차 엔트로피 손실 평균 J 와 퍼플렉서티의 관계는?","choices":["PPL = exp(J)","PPL = log(J)","PPL = 1/J"],"a":0,"why":"슬라이드: Perplexity = exp(cross-entropy loss)."},{"kind":"english","head":"답안에 쓸 문장","en":"퍼플렉서티(Perplexity)는 정답 다음 단어 확률의 역수를 기하 평균한 값으로, 평균 교차 엔트로피 손실 J 에 exp 를 씌운 것(PPL = exp(J))과 같다. 모델이 평균적으로 몇 개 후보 사이에서 헷갈리는지를 뜻하며 낮을수록 좋다.","ko":"PPL = exp(J), 곧 손실 함수(Loss Function) 평균의 exp. 낮을수록 좋음, 균등이면 V.","tip":"역수의 기하 평균 = exp(평균 -log P)"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["정확도(accuracy)는 높을수록 좋지만 **퍼플렉서티(PPL)**는 낮을수록 좋아요. 방향을 거꾸로 쓰지 마세요.","기하 평균이에요. 1/P 들을 더해서 나누는 산술 평균이 아니에요."]}]},{"p":42,"title":"퍼플렉서티 예제와 주의점","terms":["Perplexity (PPL)","Geometric Mean","Vocabulary","Tokenizer","Token","Cross-Entropy","Language Model (LM)"],"pass1":[{"kind":"figure","head":"PPL 1, 약 5.7, V","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"26\" class=\"tb\" font-size=\"15\" text-anchor=\"middle\">퍼플렉서티 = 헷갈리는 후보가 평균 몇 개?<\/text><rect x=\"30\" y=\"110\" width=\"60\" height=\"40\" rx=\"2\" class=\"n2 b1\"/><text x=\"60.0\" y=\"134.66666666666666\" class=\"tl b1\" font-size=\"14\" text-anchor=\"middle\">정답<\/text><text x=\"60\" y=\"200\" class=\"tb b1\" font-size=\"15\" text-anchor=\"middle\">PPL = 1<\/text><text x=\"60\" y=\"222\" class=\"tm b1\" font-size=\"13\" text-anchor=\"middle\">완벽한 모델<\/text><rect x=\"170\" y=\"90\" width=\"38\" height=\"38\" rx=\"2\" class=\"n3 b2\"/><rect x=\"215\" y=\"90\" width=\"38\" height=\"38\" rx=\"2\" class=\"n3 b2\"/><rect x=\"260\" y=\"90\" width=\"38\" height=\"38\" rx=\"2\" class=\"n3 b2\"/><rect x=\"170\" y=\"135\" width=\"38\" height=\"38\" rx=\"2\" class=\"n3 b2\"/><rect x=\"215\" y=\"135\" width=\"38\" height=\"38\" rx=\"2\" class=\"n3 b2\"/><rect x=\"260\" y=\"135\" width=\"38\" height=\"38\" rx=\"2\" class=\"n3 b2\"/><text x=\"236\" y=\"200\" class=\"tb b2\" font-size=\"15\" text-anchor=\"middle\">PPL ≈ 5.7<\/text><text x=\"236\" y=\"222\" class=\"tm b2\" font-size=\"13\" text-anchor=\"middle\">약 6개 중 고르기<\/text><rect x=\"330\" y=\"80\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"352\" y=\"80\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"374\" y=\"80\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"396\" y=\"80\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"418\" y=\"80\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"440\" y=\"80\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"330\" y=\"102\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"352\" y=\"102\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"374\" y=\"102\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"396\" y=\"102\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"418\" y=\"102\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"440\" y=\"102\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"330\" y=\"124\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"352\" y=\"124\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"374\" y=\"124\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"396\" y=\"124\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"418\" y=\"124\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"440\" y=\"124\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"330\" y=\"146\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"352\" y=\"146\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"374\" y=\"146\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"396\" y=\"146\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"418\" y=\"146\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"440\" y=\"146\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"330\" y=\"168\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"352\" y=\"168\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"374\" y=\"168\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"396\" y=\"168\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"418\" y=\"168\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><rect x=\"440\" y=\"168\" width=\"18\" height=\"18\" rx=\"2\" class=\"n b3\"/><text x=\"395\" y=\"200\" class=\"tb b3\" font-size=\"15\" text-anchor=\"middle\">PPL = V<\/text><text x=\"395\" y=\"222\" class=\"tm b3\" font-size=\"13\" text-anchor=\"middle\">모두 같은 확률<\/text><text x=\"240\" y=\"258\" class=\"tb b3\" font-size=\"15\" text-anchor=\"middle\">낮을수록 좋아요<\/text><\/svg>","caption":"완벽하면 1, 이 예제는 약 6개 중 고르는 정도(5.7), 아무것도 모르면 어휘 크기 V","builds":3},{"kind":"say","lines":["모델이 the, cat, sat, down 에 1/2, 1/4, 1/8, 1/16 확률을 줬어요.","계산하면 **퍼플렉서티(PPL)** ≈ 5.7, '약 6개 중에서 찍는 만큼 헷갈린다'예요.","단, 같은 **토크나이저(Tokenizer)**를 쓴 모델끼리만 비교할 수 있어요."]}],"pass2":[{"kind":"compare","head":"영어 문장 → 우리말 뜻","cols":["슬라이드 영어","우리말 뜻"],"rows":[["**Perplexity, a Worked Example**","퍼플렉서티 풀어 본 예제"],["assigns these probabilities to the TRUE next words","실제 정답 다음 단어에 이런 확률을 줬어요"],["as confused as guessing uniformly among ~6 words","약 6개 단어 중 공평하게 찍는 만큼 헷갈려요"],["Sanity anchors","상식 기준점(말이 되는지 확인하는 값)"],["uniform over V words → PPL = V, perfect model → PPL = 1, PPL < 1 is impossible","균등이면 V, 완벽하면 1, 1 보다 작을 수는 없어요"],["only comparable across models that share the SAME vocabulary & tokenizer","같은 어휘와 같은 토크나이저를 쓴 모델끼리만 비교할 수 있어요"]]},{"kind":"points","head":"기준점 세 개","items":["모든 단어에 똑같은 확률(균등) → PPL = 어휘 크기 V","정답에 늘 확률 1 → PPL = 1 (가장 낮은 값)","PPL < 1 은 불가능: 확률은 1 을 넘을 수 없으니 1/P ≥ 1"]},{"kind":"check","q":"완벽한 모델(정답에 늘 확률 1)의 퍼플렉서티는?","choices":["1","0","어휘 크기 V"],"a":0,"why":"1/1 = 1 을 몇 번 곱해도 1 이에요. 그래서 PPL 의 최솟값은 1 이에요."}],"pass3":[{"kind":"look","head":"슬라이드 짚어 읽기","boxes":[{"x":0.161,"y":0.247,"w":0.543,"h":0.038,"say":"모델이 4단어 문장의 실제 정답 단어들에 준 확률"},{"x":0.214,"y":0.332,"w":0.5,"h":0.122,"say":"the 1/2, cat 1/4, sat 1/8, down 1/16"},{"x":0.161,"y":0.47,"w":0.418,"h":0.048,"say":"PPL = (2 x 4 x 8 x 16)^(1/4) = 1024^(1/4) = 2^2.5 ≈ 5.7"},{"x":0.161,"y":0.546,"w":0.457,"h":0.036,"say":"'평균적으로 약 6개 중 공평하게 찍는 만큼 헷갈려요'"},{"x":0.061,"y":0.619,"w":0.761,"h":0.043,"say":"기준점: 균등이면 V, 완벽하면 1, 1 미만은 불가능"},{"x":0.061,"y":0.675,"w":0.743,"h":0.042,"say":"주의: 같은 어휘, 같은 토크나이저를 쓴 모델끼리만 비교 가능"}]},{"kind":"steps","head":"손계산: 슬라이드 예제 (역수의 기하 평균)","steps":["정답 확률의 역수: 1/(1/2) = 2, 4, 8, 16","모두 곱하기: 2 x 4 x 8 x 16 = 1024","단어가 4개라 1/4 제곱(네제곱근): 1024^(1/4)","1024 = 2^10 이므로 (2^10)^(1/4) = 2^2.5","2^2.5 = 4 x √2 ≈ 5.66 ≈ 5.7"],"answer":"PPL ≈ 5.7 → 약 6개 후보 중에서 고르는 정도로 헷갈려요","given":"the 1/2, cat 1/4, sat 1/8, down 1/16"},{"kind":"steps","head":"같은 답을 exp(J) 로 (p.41 식)","steps":["위치마다 벌점 -log P: log 2, log 4, log 8, log 16","합 = log(2 x 4 x 8 x 16) = log 1024 = 10 log 2","평균 J = 10 log 2 ÷ 4 = 2.5 log 2 ≈ 1.733","PPL = exp(1.733) ≈ 5.66"],"answer":"두 길이 같은 답(≈ 5.7)을 줘요: 로그가 곱을 합으로 바꾸기 때문","given":"자연로그 사용"},{"kind":"prof","when":"3주차 월요일 2교시","lines":["퍼플렉서티는 정답 확률들의 역수를 곱한 다음 단어 수만큼 제곱근을 취하면 된다고 했어요.","5.7 이면 모델이 평균적으로 매 순간 5개나 6개 후보 중에서 토큰을 하나 고르는 정도의 불확실성이라고 했어요.","가장 낮은 값은 1, 퍼플렉서티는 1 보다 작을 수 없고 낮을수록 좋다고 했어요."]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["퍼플렉서티 비교가 의미 있으려면 같은 평가 데이터, 같은 어휘(vocab), 같은 토크나이저여야 한다고 했어요.","한 모델은 글자 단위, 다른 모델은 서브워드 단위로 자르면 PPL 숫자를 그대로 비교해 '이게 더 나쁘다'고 볼 수 없다고 했어요."]},{"kind":"points","head":"실습에서 직접 보는 함정 (N3L p.18~26)","items":["N3L p.19: 같은 말뭉치 727,466 글자 → 서브워드 390,136 토큰, 예측 한 번이 평균 1.9 글자","N3L p.25: 글자 모델 PPL 27.48 (글자당), 서브워드 모델 PPL 299.07 (토큰당). 겉보기엔 글자 모델 압승","같은 자로 재면(bits per character) 글자 4.78, 서브워드 4.30 → 오히려 서브워드가 더 좋아요","N3L p.26 교훈: PPL 은 '예측 단위 하나당'이라, 논문의 PPL 을 볼 때 '어떤 단위, 어떤 토크나이저?'부터 물어요"]},{"kind":"bg","src":"기초 다지기 4단원 (로그와 지수)","lines":["2^10 = 1024, 그 네제곱근은 2^(10/4) = 2^2.5 예요. 지수끼리 곱하고 나누면 돼요.","log(a x b) = log a + log b. 그래서 역수의 곱이 벌점의 합으로 바뀌어요."]}],"pass4":[{"kind":"check","q":"정답 확률이 1/2, 1/2 인 2단어 문장의 퍼플렉서티는?","choices":["2","4","1"],"a":0,"why":"역수 2 x 2 = 4, 두 단어라 제곱근 → √4 = 2. 늘 두 후보 중 찍는 만큼 헷갈려요."},{"kind":"check","q":"정답 확률이 네 번 모두 1/4 이면 퍼플렉서티는?","choices":["4","16","256"],"a":0,"why":"(4 x 4 x 4 x 4)^(1/4) = 4. 모든 위치 확률이 같으면 PPL 은 그 역수예요."},{"kind":"english","head":"답안에 쓸 문장","en":"퍼플렉서티는 1 이상이며(완벽한 모델이면 1, 균등 분포면 어휘 크기 V), 같은 평가 데이터, 같은 어휘, 같은 토크나이저를 쓴 모델끼리만 비교할 수 있다.","ko":"기준점 1과 V, 그리고 비교 조건.","tip":"1 ≤ PPL ≤ (균등이면 V), 같은 데이터, 어휘, 토크나이저"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["PPL 은 '예측 단위(토큰) 하나당' 값이에요. 글자 모델의 PPL 27 이 서브워드 모델의 PPL 299 보다 좋다는 뜻이 아니에요(실습 N3L p.25).","(2 x 4 x 8 x 16) 을 4로 나누지 말고 네제곱근을 해요. 산술 평균 (2+4+8+16)/4 = 7.5 는 틀린 답이에요."]}]},{"p":43,"title":"4부 구분: 신경망 언어 모델과 RNN","terms":["Fixed-window Neural LM","Recurrent Neural Network (RNN)","Hidden State","Language Model (LM)","n-gram"],"pass1":[{"kind":"say","lines":["4부 **신경망 언어 모델과 RNN** 이 시작돼요. 부제는 '언어 모델에게 기억을 주기'예요.","먼저 **고정 윈도우 신경망 언어 모델(Fixed-window Neural LM)**으로 n-gram 의 벽을 허물고,","다음으로 **RNN(순환 신경망)**이 한 단어씩 읽으며 **은닉 상태(Hidden State)**(메모장)를 고쳐 써요.","짧은 기억 때문에 생긴 p.38 의 exams 문제를 기억해 두세요."]},{"kind":"points","head":"4부에서 만날 것","items":["**고정 윈도우 신경망 언어 모델(Fixed-window Neural LM)**: 앞 몇 단어를 **임베딩(Embedding)**으로 바꿔 신경망에 넣기","**RNN(순환 신경망)**: 같은 가중치로 한 단어씩, **은닉 상태(Hidden State)**에 요약을 이어 적기","RNN 의 약점(기울기 소실)과 그 처방(클리핑, 게이트, 어텐션 예고)"]}],"pass2":[],"pass3":[],"pass4":[]},{"p":44,"title":"고정 윈도우 신경망 언어 모델","terms":["Fixed-window Neural LM","Embedding","Softmax","Vocabulary","n-gram","Language Model (LM)","Next Token Prediction"],"pass1":[{"kind":"say","lines":["**n-gram(엔그램)** 의 벽을 신경망으로 넘어 보는 쪽이에요.","1부에서 배운 창(윈도우) 분류기를 그대로 쓰되, 이번에는 어휘 전체를 놓고 고르게 해요.","앞 네 단어를 **임베딩(Embedding)** 으로 바꿔 잇고, **소프트맥스(Softmax)** 로 **다음 토큰 예측(Next Token Prediction)** 을 해요."]},{"kind":"analogy","head":"네 칸짜리 창문으로 내다보기","scene":"창문 네 칸으로 밖을 보고 다음에 무슨 일이 일어날지 맞히는 것과 같아요. 창문 밖의 일은 아예 보이지 않아요.","map":[["창문 네 칸","고정된 윈도우"],["창밖 풍경","**임베딩(Embedding)** 으로 바꾼 앞 단어들"],["내 짐작","다음 단어의 확률 분포"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["reuse the window classifier = 창 분류기를 다시 쓴다","but classify over the whole vocabulary = 다만 어휘 전체를 놓고 분류한다","Embeddings give it what n-grams never had = 임베딩이 n-gram 에 없던 것을 준다","similar words share fate = 비슷한 단어는 운명을 함께한다"]},{"kind":"points","head":"무엇이 좋아졌나요","items":["**n-gram(엔그램)** 은 단어를 이름표로만 봐서 their 와 her 가 아무 상관이 없었어요.","**임베딩(Embedding)** 을 쓰면 비슷한 단어가 가까운 좌표를 가져서 정보를 나눠 가져요.","그래서 한 번도 못 본 조합에도 그럴듯한 확률이 나와요. **희소성 문제(Sparsity Problem)** 가 줄어요.","하는 일 자체는 **n-gram(엔그램)** 때와 같은 **다음 토큰 예측(Next Token Prediction)** 이에요."]}],"pass3":[{"kind":"formula","head":"이 쪽의 세 식","tex":"e = [e_1; e_2; e_3; e_4], \\quad h = f(We + b), \\quad \\hat{y} = \\mathrm{softmax}(Uh)","parts":[{"sym":"e_1 \\dots e_4","say":"앞 네 단어의 **임베딩(Embedding)** 벡터"},{"sym":"[\\; ; \\;]","say":"이어 붙이기(concatenate)"},{"sym":"W, b","say":"은닉층의 가중치와 편향 항(bias term)"},{"sym":"f","say":"**렐루(ReLU)** 같은 활성화 함수"},{"sym":"U","say":"은닉층을 어휘 크기로 펴 주는 행렬"},{"sym":"\\hat{y}","say":"**어휘(Vocabulary)** 크기만큼의 확률 분포"}],"whole":"1부의 창 분류기와 똑같고, 마지막 출력만 **어휘(Vocabulary)** 전체로 커졌어요."},{"kind":"steps","head":"벡터 크기를 세어 봐요","given":"임베딩 50칸, 창 4칸, 은닉 100칸","steps":["**임베딩(Embedding)** 한 개가 50칸이라고 해 봐요","창이 네 칸이므로 이어 붙이면 4 곱하기 50 = 200칸이에요","은닉층이 100칸이면 W 는 100 곱하기 200 = 20,000개예요","U 는 100 곱하기 **어휘(Vocabulary)** 크기예요"],"answer":"이어 붙인 벡터는 200칸. 창을 넓히면 W 가 그만큼 커져요."},{"kind":"figure","head":"고정 윈도우 신경망 언어 모델","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 280\"><text x=\"240\" y=\"20\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">고정 윈도우 신경망 언어 모델<\/text><rect x=\"16\" y=\"208\" width=\"96\" height=\"26\" rx=\"2\" class=\"n b1\"/><text x=\"64.0\" y=\"225.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">the<\/text><rect x=\"130\" y=\"208\" width=\"96\" height=\"26\" rx=\"2\" class=\"n b1\"/><text x=\"178.0\" y=\"225.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">kids<\/text><rect x=\"244\" y=\"208\" width=\"96\" height=\"26\" rx=\"2\" class=\"n b1\"/><text x=\"292.0\" y=\"225.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">opened<\/text><rect x=\"358\" y=\"208\" width=\"96\" height=\"26\" rx=\"2\" class=\"n b1\"/><text x=\"406.0\" y=\"225.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">their<\/text><line x1=\"64\" y1=\"206\" x2=\"64.0\" y2=\"192.4\" class=\"e2 b2\"/><polygon points=\"64,186 60.0,194.0 68.0,194.0\" class=\"arrow b2\"/><line x1=\"178\" y1=\"206\" x2=\"178.0\" y2=\"192.4\" class=\"e2 b2\"/><polygon points=\"178,186 174.0,194.0 182.0,194.0\" class=\"arrow b2\"/><line x1=\"292\" y1=\"206\" x2=\"292.0\" y2=\"192.4\" class=\"e2 b2\"/><polygon points=\"292,186 288.0,194.0 296.0,194.0\" class=\"arrow b2\"/><line x1=\"406\" y1=\"206\" x2=\"406.0\" y2=\"192.4\" class=\"e2 b2\"/><polygon points=\"406,186 402.0,194.0 410.0,194.0\" class=\"arrow b2\"/><rect x=\"16\" y=\"154\" width=\"96\" height=\"26\" rx=\"2\" class=\"box b2\"/><text x=\"64.0\" y=\"171.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b2\">e1<\/text><rect x=\"130\" y=\"154\" width=\"96\" height=\"26\" rx=\"2\" class=\"box b2\"/><text x=\"178.0\" y=\"171.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b2\">e2<\/text><rect x=\"244\" y=\"154\" width=\"96\" height=\"26\" rx=\"2\" class=\"box b2\"/><text x=\"292.0\" y=\"171.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b2\">e3<\/text><rect x=\"358\" y=\"154\" width=\"96\" height=\"26\" rx=\"2\" class=\"box b2\"/><text x=\"406.0\" y=\"171.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b2\">e4<\/text><line x1=\"64\" y1=\"152\" x2=\"193.7\" y2=\"127.2\" class=\"e2 b3\"/><polygon points=\"200,126 191.4,123.6 192.9,131.4\" class=\"arrow b3\"/><line x1=\"178\" y1=\"152\" x2=\"222.3\" y2=\"129.0\" class=\"e2 b3\"/><polygon points=\"228,126 219.1,126.1 222.7,133.2\" class=\"arrow b3\"/><line x1=\"292\" y1=\"152\" x2=\"261.2\" y2=\"129.7\" class=\"e2 b3\"/><polygon points=\"256,126 260.1,133.9 264.8,127.4\" class=\"arrow b3\"/><line x1=\"406\" y1=\"152\" x2=\"290.3\" y2=\"127.3\" class=\"e2 b3\"/><polygon points=\"284,126 291.0,131.6 292.7,123.8\" class=\"arrow b3\"/><rect x=\"120\" y=\"96\" width=\"240\" height=\"28\" rx=\"2\" class=\"box2 b3\"/><text x=\"240.0\" y=\"114.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b3\">이어 붙인 벡터 e (200칸)<\/text><line x1=\"240\" y1=\"94\" x2=\"240.0\" y2=\"80.4\" class=\"e2 b4\"/><polygon points=\"240,74 236.0,82.0 244.0,82.0\" class=\"arrow b4\"/><rect x=\"120\" y=\"44\" width=\"240\" height=\"28\" rx=\"2\" class=\"box2 b4\"/><text x=\"240.0\" y=\"62.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b4\">h = f(We + b), y = softmax(Uh)<\/text><text x=\"240\" y=\"258\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">books 0.42, presents 0.21, laptops 0.09<\/text><\/svg>","caption":"아래에서 위로 단어, 임베딩, 이어 붙이기, 예측이에요.","builds":4},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"맨 위 한 줄: 창 분류기를 다시 쓰되 어휘 전체를 놓고 분류한다."},{"x":0.28,"y":0.63,"w":0.44,"h":0.09,"say":"맨 아래 회색 상자가 the kids opened their 예요."},{"x":0.28,"y":0.55,"w":0.44,"h":0.08,"say":"그 위 파란 상자 e1 ... e4 가 단어 임베딩이에요."},{"x":0.41,"y":0.48,"w":0.18,"h":0.07,"say":"이어 붙인 벡터 e = [e1; e2; e3; e4] 예요."},{"x":0.41,"y":0.32,"w":0.18,"h":0.09,"say":"위쪽 초록 상자가 softmax(Uh) 로 낸 확률이에요."},{"x":0.67,"y":0.29,"w":0.12,"h":0.06,"say":"오른쪽 books 0.42, presents 0.21, laptops 0.09 가 예측 결과예요."}]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님: 랭귀지 모델이기 때문에 다음 토큰을 예측하고 하나 선택하고 또 붙이고 다시 그걸 입력으로 넣는 식이에요.","교수님: **임베딩(Embedding)** 으로 표현하기 때문에 비슷한 정보도 다 공유할 수 있어요."]},{"kind":"bg","src":"기초 다지기 3단원","lines":["이어 붙이기(concatenate)는 벡터 여러 개를 한 줄로 길게 잇는 것이에요.","50칸짜리 네 개를 이으면 200칸짜리 하나가 돼요."]}],"pass4":[{"kind":"check","q":"고정 윈도우 신경망 언어 모델이 n-gram 보다 나은 점은?","choices":["**임베딩(Embedding)** 덕분에 비슷한 단어가 정보를 나눈다","문맥을 무제한으로 본다","계산이 훨씬 빠르다","학습이 필요 없다"],"a":0,"why":"창 크기는 여전히 고정이에요. 나아진 것은 **희소성 문제(Sparsity Problem)** 와 유사도 부분이에요."},{"kind":"english","head":"시험 답안 문장","en":"고정 윈도우 신경망 언어 모델은 앞의 정해진 몇 단어를 임베딩으로 바꿔 이어 붙이고, 신경망과 소프트맥스로 어휘 전체에 대한 확률을 낸다.","ko":"임베딩, 이어 붙이기, 소프트맥스 세 낱말을 꼭 넣어요.","tip":"창 분류기에서 출력만 어휘 전체로 바꾼 것이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["창 안의 단어만 봐요. 창 밖의 정보는 아무리 중요해도 버려져요."]}]},{"p":45,"title":"고정 윈도우의 성적표","terms":["Fixed-window Neural LM","Sparsity Problem","Embedding","Parameter","Recurrent Neural Network (RNN)","n-gram"],"pass1":[{"kind":"say","lines":["고쳐진 것과 아직 남은 것을 정리하는 쪽이에요.","**희소성 문제(Sparsity Problem)** 와 거대한 횟수 표는 사라졌어요.","하지만 창은 여전히 고정이고, 자리마다 가중치가 따로예요.","두 벽이 무너지고 하나가 남았어요. 남은 하나를 **RNN(순환 신경망)** 이 무너뜨려요."]},{"kind":"analogy","head":"창문은 넓혔지만 여전히 창문","scene":"창문을 크게 만들면 더 많이 보이지만, 창문 밖은 여전히 안 보여요. 창을 없애야 밖이 다 보여요.","map":[["창문 크기","윈도우 크기"],["창문 밖","버려지는 먼 문맥"],["창문을 없애기","**RNN(순환 신경망)**"]]}],"pass2":[{"kind":"compare","head":"고쳐진 것과 남은 것","cols":["구분","내용"],"rows":[["고쳐짐","**희소성 문제(Sparsity Problem)** 가 없어요. 못 본 조합에도 그럴듯한 확률이 나와요"],["고쳐짐","거대한 횟수 표가 필요 없어요"],["고쳐짐","**임베딩(Embedding)** 덕분에 유사도가 들어 있어요"],["남음","창이 여전히 고정이라 그 밖은 버려요"],["남음","자리마다 W 의 조각이 따로라 the 가 1번 자리와 3번 자리에서 따로 배워요"]]},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["no sparsity = 희소성 문제가 없다","no giant count tables = 거대한 횟수 표가 없다","the window is still FIXED = 창이 여전히 고정이다","each position has its OWN weights in W = 자리마다 W 안의 가중치가 따로다","no sharing of what a word means across positions = 단어의 뜻을 자리끼리 나누지 못한다","Wanted: any length, shared processing = 원하는 것은 임의 길이와 자리 간 공유"]}],"pass3":[{"kind":"steps","head":"자리마다 가중치가 따로라는 게 무슨 뜻일까요","given":"창 4칸, 임베딩 50칸","steps":["창이 네 칸이면 이어 붙인 벡터가 [e1; e2; e3; e4] 예요","W 는 이 200칸을 한 번에 받는데, 앞 50칸은 1번 자리 전용이에요","그다음 50칸은 2번 자리 전용이고, 이렇게 자리마다 구역이 나뉘어요","the 가 1번 자리에 오면 첫 구역이, 3번 자리에 오면 셋째 구역이 배워요","같은 단어인데 자리가 다르면 배운 것을 나눠 쓰지 못해요"],"answer":"같은 것을 네 번 따로 배우는 셈이에요. 낭비이고 크게 만들 수도 없어요."},{"kind":"steps","head":"창을 넓히면 얼마나 커질까요","given":"창 4칸 vs 8칸","steps":["은닉 100칸, 임베딩 50칸이라고 해요","창이 4칸이면 W 는 100 곱하기 200 = 20,000개예요","창을 8칸으로 늘리면 100 곱하기 400 = 40,000개예요","창 크기에 비례해서 정확히 두 배가 됐어요"],"answer":"모델 크기가 창 크기를 따라 커져요. 이것도 **RNN(순환 신경망)** 이 고쳐요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.09,"say":"Fixed 줄: 희소성 없음, 거대한 표 없음, 임베딩으로 유사도 내장."},{"x":0.05,"y":0.3,"w":0.9,"h":0.05,"say":"Broken 줄: 창이 여전히 고정이고 그 밖은 버려진다."},{"x":0.05,"y":0.36,"w":0.9,"h":0.09,"say":"Broken 줄: 자리마다 W 가 따로라 자리끼리 공유가 없다."},{"x":0.05,"y":0.48,"w":0.9,"h":0.06,"say":"Wanted 줄: 임의 길이와 자리 간 공유, 그래서 순환(recurrence)."}]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님: 구조를 계속 반복해서 사용하기 때문에 모든 타임 스텝에서 같은 가중치를 공유할 수 있어요.","교수님: 이게 다음에 나올 RNN 의 핵심이에요."]}],"pass4":[{"kind":"check","q":"고정 윈도우 신경망 언어 모델에 아직 남아 있는 문제는?","choices":["희소성 문제","거대한 횟수 표","창 밖의 문맥을 버리는 것","유사도를 못 쓰는 것"],"a":2,"why":"앞의 셋은 신경망이 이미 고쳤어요. 남은 것은 고정된 창과 자리별 가중치예요."},{"kind":"english","head":"시험 답안 문장","en":"고정 윈도우 신경망 언어 모델은 희소성과 유사도 문제를 해결했지만, 창 크기가 고정이고 자리마다 가중치가 달라 임의 길이와 가중치 공유를 얻지 못한다.","ko":"고친 것 두 가지와 남은 것 두 가지를 짝지어 적어요.","tip":"두 벽은 무너지고 하나가 남았다, 라고 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["창을 키우면 문맥은 늘지만 모델도 그만큼 커져요. 공짜가 아니에요."]}]},{"p":46,"title":"RNN 이라는 생각","terms":["Recurrent Neural Network (RNN)","Hidden State","Parameter","Fixed-window Neural LM","Token"],"pass1":[{"kind":"say","lines":["**RNN(순환 신경망)** 의 한 줄 생각이에요. 매 걸음마다 **같은** 가중치를 쓰는 거예요.","그리고 지금까지 읽은 것을 요약한 **은닉 상태(Hidden State)** 를 들고 다녀요.","가중치가 하나뿐이니 문장이 아무리 길어도 모델 크기가 그대로예요."]},{"kind":"analogy","head":"메모장을 든 독자","scene":"책을 한 줄씩 읽으면서 작은 메모장에 요약을 고쳐 적는 사람을 떠올려요. 메모장은 늘 같은 크기이고, 고쳐 쓰는 방식도 늘 같아요.","map":[["한 줄씩 읽기","**토큰(Token)** 을 하나씩 넣기"],["메모장","**은닉 상태(Hidden State)**"],["늘 같은 고쳐쓰기 방식","모든 걸음이 함께 쓰는 가중치"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Apply the SAME weights at every step = 매 걸음마다 같은 가중치를 쓴다","carrying a hidden state = 은닉 상태를 들고 다니면서","a running summary of everything read so far = 지금까지 읽은 모든 것의 진행형 요약","One set of weights, any sentence length = 가중치 한 벌로 어떤 길이의 문장이든","the reader with a memory = 기억을 가진 독자","RECURRENCE = 순환"]},{"kind":"compare","head":"고정 윈도우와 무엇이 다른가요","cols":["보는 점","**고정 윈도우 신경망 언어 모델(Fixed-window Neural LM)**","**RNN(순환 신경망)**"],"rows":[["볼 수 있는 범위","창 안쪽만","원칙적으로 처음부터 전부"],["가중치","자리마다 따로","모든 걸음이 같은 것"],["모델 크기","창 크기를 따라 커짐","문장 길이와 무관"]]}],"pass3":[{"kind":"steps","head":"파라미터 수를 세어 봐요","given":"은닉 100칸, 임베딩 50칸","steps":["은닉 100칸, 임베딩 50칸이라고 해요","W_h 는 은닉에서 은닉이라 100 곱하기 100 = 10,000개예요","W_e 는 임베딩에서 은닉이라 100 곱하기 50 = 5,000개예요","합쳐서 15,000개이고, 문장이 10단어든 1000단어든 이 수는 같아요","고정 윈도우는 창 8칸이면 W 만 40,000개였어요"],"answer":"**RNN(순환 신경망)** 은 **파라미터(Parameter)** 수가 문장 길이와 상관없어요. 이게 가중치 공유의 힘이에요."},{"kind":"figure","head":"같은 가중치를 매 걸음 되풀이해요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"20\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">같은 가중치를 매 걸음 되풀이해요<\/text><rect x=\"20\" y=\"196\" width=\"92\" height=\"26\" rx=\"2\" class=\"n b1\"/><text x=\"66.0\" y=\"213.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">the<\/text><rect x=\"132\" y=\"196\" width=\"92\" height=\"26\" rx=\"2\" class=\"n b1\"/><text x=\"178.0\" y=\"213.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">kids<\/text><rect x=\"244\" y=\"196\" width=\"92\" height=\"26\" rx=\"2\" class=\"n b1\"/><text x=\"290.0\" y=\"213.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">opened<\/text><rect x=\"356\" y=\"196\" width=\"92\" height=\"26\" rx=\"2\" class=\"n b1\"/><text x=\"402.0\" y=\"213.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">their<\/text><line x1=\"66\" y1=\"194\" x2=\"66.0\" y2=\"178.4\" class=\"e2 b2\"/><polygon points=\"66,172 62.0,180.0 70.0,180.0\" class=\"arrow b2\"/><line x1=\"178\" y1=\"194\" x2=\"178.0\" y2=\"178.4\" class=\"e2 b2\"/><polygon points=\"178,172 174.0,180.0 182.0,180.0\" class=\"arrow b2\"/><line x1=\"290\" y1=\"194\" x2=\"290.0\" y2=\"178.4\" class=\"e2 b2\"/><polygon points=\"290,172 286.0,180.0 294.0,180.0\" class=\"arrow b2\"/><line x1=\"402\" y1=\"194\" x2=\"402.0\" y2=\"178.4\" class=\"e2 b2\"/><polygon points=\"402,172 398.0,180.0 406.0,180.0\" class=\"arrow b2\"/><rect x=\"20\" y=\"140\" width=\"92\" height=\"30\" rx=\"2\" class=\"box2 b2\"/><text x=\"66.0\" y=\"159.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">h1<\/text><rect x=\"132\" y=\"140\" width=\"92\" height=\"30\" rx=\"2\" class=\"box2 b2\"/><text x=\"178.0\" y=\"159.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">h2<\/text><rect x=\"244\" y=\"140\" width=\"92\" height=\"30\" rx=\"2\" class=\"box2 b2\"/><text x=\"290.0\" y=\"159.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">h3<\/text><rect x=\"356\" y=\"140\" width=\"92\" height=\"30\" rx=\"2\" class=\"box2 b2\"/><text x=\"402.0\" y=\"159.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">h4<\/text><line x1=\"112\" y1=\"155\" x2=\"121.6\" y2=\"155.0\" class=\"e2 b3\"/><polygon points=\"128,155 120.0,151.0 120.0,159.0\" class=\"arrow b3\"/><line x1=\"224\" y1=\"155\" x2=\"233.6\" y2=\"155.0\" class=\"e2 b3\"/><polygon points=\"240,155 232.0,151.0 232.0,159.0\" class=\"arrow b3\"/><line x1=\"336\" y1=\"155\" x2=\"345.6\" y2=\"155.0\" class=\"e2 b3\"/><polygon points=\"352,155 344.0,151.0 344.0,159.0\" class=\"arrow b3\"/><text x=\"66\" y=\"128\" font-size=\"11\" text-anchor=\"middle\" class=\"tm b3\">W_h<\/text><text x=\"178\" y=\"128\" font-size=\"11\" text-anchor=\"middle\" class=\"tm b3\">W_h<\/text><text x=\"290\" y=\"128\" font-size=\"11\" text-anchor=\"middle\" class=\"tm b3\">W_h<\/text><line x1=\"66\" y1=\"138\" x2=\"66.0\" y2=\"122.4\" class=\"e2 b4\"/><polygon points=\"66,116 62.0,124.0 70.0,124.0\" class=\"arrow b4\"/><line x1=\"178\" y1=\"138\" x2=\"178.0\" y2=\"122.4\" class=\"e2 b4\"/><polygon points=\"178,116 174.0,124.0 182.0,124.0\" class=\"arrow b4\"/><line x1=\"290\" y1=\"138\" x2=\"290.0\" y2=\"122.4\" class=\"e2 b4\"/><polygon points=\"290,116 286.0,124.0 294.0,124.0\" class=\"arrow b4\"/><line x1=\"402\" y1=\"138\" x2=\"402.0\" y2=\"122.4\" class=\"e2 b4\"/><polygon points=\"402,116 398.0,124.0 406.0,124.0\" class=\"arrow b4\"/><rect x=\"20\" y=\"84\" width=\"92\" height=\"26\" rx=\"2\" class=\"box b4\"/><text x=\"66.0\" y=\"101.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b4\">예측<\/text><rect x=\"132\" y=\"84\" width=\"92\" height=\"26\" rx=\"2\" class=\"box b4\"/><text x=\"178.0\" y=\"101.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b4\">예측<\/text><rect x=\"244\" y=\"84\" width=\"92\" height=\"26\" rx=\"2\" class=\"box b4\"/><text x=\"290.0\" y=\"101.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b4\">예측<\/text><rect x=\"356\" y=\"84\" width=\"92\" height=\"26\" rx=\"2\" class=\"box b4\"/><text x=\"402.0\" y=\"101.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b4\">예측<\/text><text x=\"240\" y=\"60\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b4\">W_h, W_e, U 는 네 걸음 모두 같은 것이에요<\/text><text x=\"240\" y=\"250\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">그래서 문장이 길어져도 파라미터가 안 늘어요<\/text><\/svg>","caption":"네 걸음이 모두 같은 W_h, W_e, U 를 써요.","builds":4},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.07,"say":"첫 점: 매 걸음 같은 가중치를 쓰고 은닉 상태를 들고 다닌다."},{"x":0.05,"y":0.27,"w":0.9,"h":0.05,"say":"a running summary 는 지금까지 읽은 것의 진행형 요약이라는 뜻이에요."},{"x":0.2,"y":0.85,"w":0.6,"h":0.05,"say":"맨 아래 한 줄: 가중치 한 벌로 어떤 길이든, 기억을 가진 독자."}]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님: 같은 웨이트를 고정해 놓고 반복해서 은닉 상태를 계속 넘겨주는 거예요.","교수님: 그래서 타임 스텝마다 고정된 윈도우 없이 시퀀스를 처리할 수 있어요.","교수님: 50 단어든 500 단어든 이 가중치 행렬은 타임 스텝에 상관없이 재활용해요."]}],"pass4":[{"kind":"check","q":"RNN 의 파라미터 수는 문장 길이에 따라 어떻게 되나요?","choices":["길이에 비례해 늘어난다","길이의 제곱으로 늘어난다","길이와 상관없이 그대로다","길이가 길수록 줄어든다"],"a":2,"why":"모든 걸음이 같은 W_h, W_e, U 를 쓰기 때문이에요. 교수님이 특히 강조한 부분이에요."},{"kind":"english","head":"시험 답안 문장","en":"RNN 은 모든 시점에 같은 가중치를 되풀이해 적용하고 은닉 상태로 지금까지 읽은 내용을 전달하므로, 임의 길이를 처리하면서도 파라미터 수가 문장 길이와 무관하다.","ko":"같은 가중치, 은닉 상태, 길이 무관 세 가지를 넣어요.","tip":"가중치 한 벌, 어떤 길이든. 이 한 줄이 요약이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**은닉 상태(Hidden State)** 는 학습되는 값이 아니에요. 문장마다 새로 계산되는 중간 결과예요."]}]},{"p":47,"title":"RNN 을 두 식으로","terms":["Recurrent Neural Network (RNN)","Hidden State","tanh","Softmax","Vocabulary","Embedding","Parameter"],"pass1":[{"kind":"say","lines":["오늘 외워야 할 두 줄이에요.","새 메모 = 옛 메모와 지금 단어를 섞어 **하이퍼볼릭 탄젠트(tanh)** 로 누른 것이에요.","예측 = 그 메모를 어휘 크기로 펴서 **소프트맥스(Softmax)** 를 씌운 것이에요."]},{"kind":"analogy","head":"메모를 고쳐 쓰기","scene":"메모장에 이미 적힌 요약과 방금 읽은 문장을 함께 보고, 메모를 새로 고쳐 써요. 너무 길어지지 않게 늘 같은 칸 안에 눌러 담아요.","map":[["이미 적힌 요약","h(t-1)"],["방금 읽은 문장","e(t)"],["칸 안에 눌러 담기","**하이퍼볼릭 탄젠트(tanh)**"]]}],"pass2":[{"kind":"formula","head":"RNN 의 두 식","tex":"h^{(t)} = \\tanh\\!\\left(W_h h^{(t-1)} + W_e e^{(t)} + b\\right), \\qquad \\hat{y}^{(t)} = \\mathrm{softmax}\\!\\left(U h^{(t)}\\right)","parts":[{"sym":"h^{(t-1)}","say":"바로 앞 걸음의 메모"},{"sym":"W_h","say":"메모를 앞으로 실어 나르는 법"},{"sym":"e^{(t)}","say":"지금 단어의 **임베딩(Embedding)**"},{"sym":"W_e","say":"새 단어를 받아들이는 법"},{"sym":"\\tanh","say":"값이 너무 커지지 않게 -1 과 1 사이로 누르기"},{"sym":"U","say":"메모를 **어휘(Vocabulary)** 크기로 펴 주는 행렬"},{"sym":"\\hat{y}^{(t)}","say":"다음 단어의 확률 분포"}],"whole":"W_h, W_e, U 셋을 모든 걸음이 함께 써요. 그게 바로 순환(recurrence)이에요."},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["New memory = a learned blend of old memory and the current word = 새 메모는 옛 메모와 지금 단어를 학습된 방식으로 섞은 것","how to carry memory forward = 메모를 앞으로 실어 나르는 법(W_h)","how to absorb a new word = 새 단어를 받아들이는 법(W_e)","squash to keep values sane = 값이 미치지 않게 눌러 주기(tanh)","the same at every timestep, that is the recurrence = 매 시점 같은 것, 그것이 순환이다"]}],"pass3":[{"kind":"steps","head":"RNN 한 걸음을 손으로 계산해 봐요","given":"W_h, W_e, h0, e1","steps":["은닉 2칸, 임베딩 2칸짜리 아주 작은 예를 써요","W_h = [[0.5, 0], [0, 0.5]], W_e = [[1, 0], [0, -1]], b = (0, 0) 이에요","h0 = (0, 0) 이고 첫 단어의 임베딩 e1 = (1, 1) 이에요","W_h h0 = (0, 0), W_e e1 = (1, -1) 이므로 안쪽 값은 (1, -1) 이에요","tanh(1) = 0.7616, tanh(-1) = -0.7616 이에요"],"answer":"h1 = (0.7616, -0.7616). 첫 칸은 밀어 올리고 둘째 칸은 눌러 내린 방향이에요."},{"kind":"steps","head":"한 걸음 더 가 봐요","given":"h1 과 e2","steps":["같은 단어를 한 번 더 넣어요. e2 = (1, 1) 이에요","W_h h1 = (0.5 x 0.7616, 0.5 x -0.7616) = (0.3808, -0.3808) 이에요","W_e e2 = (1, -1) 이에요","더하면 (1.3808, -1.3808) 이에요","tanh 를 씌우면 (0.8811, -0.8811) 이에요"],"answer":"h2 = (0.8811, -0.8811). 같은 방향으로 조금 더 진해졌어요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: 새 메모는 옛 메모와 지금 단어를 학습된 방식으로 섞은 것."},{"x":0.1,"y":0.33,"w":0.8,"h":0.09,"say":"가운데 큰 두 식이 오늘 외울 식이에요."},{"x":0.07,"y":0.47,"w":0.83,"h":0.05,"say":"그 아래 W_h, W_e, tanh 의 역할 설명이에요."},{"x":0.07,"y":0.53,"w":0.6,"h":0.05,"say":"같은 (W_h, W_e, U) 를 매 시점에 쓴다, 그것이 순환이다."},{"x":0.6,"y":0.55,"w":0.28,"h":0.3,"say":"오른쪽 그림에서 h 로 돌아오는 고리가 W_h 예요."}]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님: h(t) 를 계산하려면 h(t-1) 이 필요하고, h(t-1) 을 계산하려면 h(t-2) 가 필요해요.","교수님: 그래서 계산이 순차적이에요. 시퀀셜은 컴퓨터 공학에서 굉장히 나쁜 단어입니다."]},{"kind":"bg","src":"기초 다지기 9단원","lines":["**하이퍼볼릭 탄젠트(tanh)** 는 어떤 수든 -1 과 1 사이로 눌러 주는 S자 함수예요.","0 근처에서는 거의 그대로 두고, 값이 커질수록 1 에 가까워지며 완만해져요."]}],"pass4":[{"kind":"check","q":"RNN 의 세 가중치 W_h, W_e, U 는 시점마다 어떻게 되나요?","choices":["시점마다 새로 만든다","모든 시점이 같은 것을 쓴다","짝수 시점만 공유한다","첫 시점만 학습한다"],"a":1,"why":"이것이 순환의 정의예요. 그래서 파라미터 수가 문장 길이와 무관해요."},{"kind":"english","head":"시험 답안 문장","en":"RNN 은 h(t) = tanh(W_h h(t-1) + W_e e(t) + b) 로 은닉 상태를 갱신하고 y(t) = softmax(U h(t)) 로 다음 단어를 예측하며, 세 행렬을 모든 시점이 공유한다.","ko":"두 식과 공유를 함께 적어요.","tip":"섞고, 누르고, 펴고. 세 동작으로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["W_h 와 W_e 는 서로 다른 행렬이에요. 하나는 메모용, 하나는 새 단어용이에요.","**하이퍼볼릭 탄젠트(tanh)** 는 **소프트맥스(Softmax)** 가 아니에요. 확률을 만드는 것은 마지막 줄의 소프트맥스예요."]}]},{"p":48,"title":"고정 윈도우와 RNN 나란히 보기","terms":["Fixed-window Neural LM","Recurrent Neural Network (RNN)","Parameter","Parallelization","Hidden State"],"pass1":[{"kind":"say","lines":["두 모델을 다섯 가지 기준으로 비교하는 표예요.","RNN 이 길이와 공유를 얻는 대신 속도와 기억 유지에서 값을 치러요.","표의 다섯 줄을 그대로 외우면 시험에 바로 써요."]},{"kind":"analogy","head":"자전거와 버스","scene":"자전거는 언제든 바로 출발하지만 멀리 못 가요. 버스는 멀리 가지만 앞차가 가야 갈 수 있어요.","map":[["자전거","**고정 윈도우 신경망 언어 모델(Fixed-window Neural LM)**, 한 번에 병렬로"],["버스","**RNN(순환 신경망)**, 앞 걸음을 기다려야"],["멀리 가기","긴 문맥 처리"]]}],"pass2":[{"kind":"compare","head":"슬라이드 표 다섯 줄","cols":["기준","**고정 윈도우 신경망 언어 모델(Fixed-window Neural LM)**","**RNN(순환 신경망)**"],"rows":[["문맥 길이","고정 (창에 들어가는 만큼)","임의 길이, 원칙적으로 무제한"],["가중치","자리마다 W 의 조각이 따로","W_h, W_e 하나를 모든 걸음이 공유"],["모델 크기","창 크기를 따라 커짐","시퀀스 길이와 무관"],["계산","한 번에, 완전 병렬","순차적, t 는 t-1 을 기다림"],["실제로는","설계상 잊어버림","기울기가 희미해져 잊어버림"]]},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["any length, in principle unbounded = 임의 길이, 원칙적으로 무제한","ONE W_h, W_e shared by all steps = 하나의 W_h, W_e 를 모든 걸음이 공유","independent of sequence length = 시퀀스 길이와 무관","sequential, step t waits for t-1 = 순차적, t 걸음은 t-1 을 기다린다","forgets by design = 설계상 잊는다","forgets by gradient decay = 기울기가 줄어들어 잊는다"]}],"pass3":[{"kind":"steps","head":"모델 크기를 숫자로 비교해 봐요","given":"은닉 100칸, 임베딩 50칸","steps":["은닉 100칸, 임베딩 50칸으로 맞춰요","고정 윈도우 창 4칸: W 는 100 곱하기 200 = 20,000개","고정 윈도우 창 8칸: W 는 100 곱하기 400 = 40,000개","RNN: W_h 10,000 더하기 W_e 5,000 = 15,000개","RNN 의 15,000개는 문장이 아무리 길어도 그대로예요"],"answer":"RNN 이 더 작고, 길이에 흔들리지 않아요. 대신 순차 계산이라 느려요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.08,"y":0.25,"w":0.85,"h":0.06,"say":"표 머리글: fixed-window neural LM 과 RNN-LM."},{"x":0.08,"y":0.33,"w":0.85,"h":0.07,"say":"context length 줄: 고정 vs 임의 길이."},{"x":0.08,"y":0.41,"w":0.85,"h":0.07,"say":"weights 줄: 자리마다 따로 vs 모든 걸음 공유."},{"x":0.08,"y":0.49,"w":0.85,"h":0.07,"say":"model size 줄: 창을 따라 커짐 vs 길이와 무관."},{"x":0.08,"y":0.57,"w":0.85,"h":0.07,"say":"computation 줄: 완전 병렬 vs 순차적."},{"x":0.2,"y":0.8,"w":0.6,"h":0.05,"say":"맨 아래: 순환은 길이와 공유를 사고, 속도와 기억으로 값을 치른다."}]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님: 우리는 시퀀스별로 각 단어를 병렬적으로 쳐내기를 원하는데 RNN 은 t-1 까지 포워드가 끝나기를 기다려야 해요.","교수님: 백프로퍼게이션도 마찬가지예요. 계산이 시퀀셜하다는 게 아주 좋지 않죠.","교수님: 더 중요한 문제로, 이론상 모든 과거를 담지만 실제로는 멀리 있는 정보를 유지하기가 어려워요."]}],"pass4":[{"kind":"check","q":"RNN 이 고정 윈도우보다 불리한 점은?","choices":["모델이 더 크다","순차 계산이라 병렬화가 안 된다","희소성 문제가 있다","임베딩을 못 쓴다"],"a":1,"why":"**병렬화(Parallelization)** 가 안 되는 것이 RNN 의 대표적인 약점이에요. 4주차에서 이것을 고쳐요."},{"kind":"english","head":"시험 답안 문장","en":"RNN 은 임의 길이 문맥과 가중치 공유를 얻어 모델 크기가 길이와 무관하지만, 계산이 순차적이라 병렬화가 불가능하고 기울기가 줄어 먼 정보를 잊는다.","ko":"얻은 것 두 가지와 치른 값 두 가지를 짝지어요.","tip":"길이와 공유를 사고, 속도와 기억을 지불한다."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["RNN 이 이론상 무제한 문맥을 본다는 것과 실제로 잘 기억한다는 것은 다른 말이에요."]}]},{"p":49,"title":"RNN 언어 모델 학습하기","terms":["Recurrent Neural Network (RNN)","Language Model (LM)","Cross-Entropy","Loss Function","Teacher Forcing","Softmax","Token"],"pass1":[{"kind":"say","lines":["말뭉치를 넣고 매 걸음마다 다음 단어를 맞히게 해요.","틀린 만큼 **교차 엔트로피(Cross-Entropy)** 벌점을 매기고, 그 평균이 **손실 함수(Loss Function)** J 가 돼요.","학습할 때는 항상 진짜 정답 앞부분을 조건으로 줘요. 이것이 **교사 강요(Teacher Forcing)** 예요."]},{"kind":"analogy","head":"옆에서 답을 알려 주는 선생님","scene":"받아쓰기를 하는데 한 칸 쓸 때마다 선생님이 정답을 알려 줘요. 그러면 앞에서 틀려도 뒤가 엉키지 않아요.","map":[["한 칸","한 시점"],["선생님이 알려 주는 정답","진짜 다음 단어"],["틀린 만큼 받는 감점","**교차 엔트로피(Cross-Entropy)**"]]}],"pass2":[{"kind":"formula","head":"손실 식","tex":"J(\\theta) = \\frac{1}{T}\\sum_{t=1}^{T} J^{(t)}(\\theta), \\qquad J^{(t)} = -\\log \\hat{y}^{(t)}\\!\\left[x^{(t+1)}\\right]","parts":[{"sym":"T","say":"문장의 토큰 개수"},{"sym":"J^{(t)}","say":"t 번째 걸음의 벌점"},{"sym":"\\hat{y}^{(t)}","say":"t 번째 걸음에서 낸 확률 분포"},{"sym":"x^{(t+1)}","say":"진짜 다음 단어"},{"sym":"-\\log","say":"정답 확률이 작을수록 벌점이 커져요"},{"sym":"\\frac{1}{T}\\sum","say":"모든 걸음의 벌점을 평균 내요"}],"whole":"3부에서 배운 **교차 엔트로피(Cross-Entropy)** 를 시점마다 한 번씩 매기고 평균 내는 것뿐이에요."},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Feed a corpus = 말뭉치를 넣어 준다","at every step predict the next word = 매 걸음마다 다음 단어를 예측한다","pay cross-entropy for the truth = 정답에 대해 교차 엔트로피를 치른다","we always condition on the TRUE prefix during training = 학습 중에는 항상 진짜 앞부분을 조건으로 삼는다"]}],"pass3":[{"kind":"steps","head":"벌점이 어떻게 붙는지 따라가 봐요","given":"토큰 5개짜리 문장","steps":["문장이 the kids opened their books 라고 해요","the 를 넣고 다음이 kids 일 확률을 내요. 벌점은 -log y[kids] 예요","the kids 를 넣고 다음이 opened 일 확률을 내요. 벌점은 -log y[opened] 예요","같은 식으로 their, books 까지 벌점을 매겨요","네 벌점을 더해서 4 로 나눈 것이 **손실 함수(Loss Function)** J 예요"],"answer":"매 걸음이 문제 하나예요. 문장 하나에서 문제 T 개가 나와요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: 말뭉치를 넣고 매 걸음 다음 단어를 예측해 교차 엔트로피를 치른다."},{"x":0.18,"y":0.32,"w":0.64,"h":0.07,"say":"빨간 상자 J = -log y[kids] 등이 걸음마다의 벌점이에요."},{"x":0.18,"y":0.52,"w":0.64,"h":0.08,"say":"주황 h 상자가 옆으로 이어지는 것이 은닉 상태 전달이에요."},{"x":0.82,"y":0.53,"w":0.14,"h":0.05,"say":"오른쪽 J = 시그마 J_t / T 가 전체 손실이에요."},{"x":0.35,"y":0.86,"w":0.45,"h":0.04,"say":"맨 아래: 학습 중에는 항상 진짜 앞부분을 조건으로 삼는다."}]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님: 티처가 각 스텝마다 알려주는 거예요. 이번 스텝의 정답은 뭐였어 하고요.","교수님: 그래서 이걸 티처 포싱이라고 해요.","교수님: 실제 정답 문장의 바로 다음 단어를 라벨로 활용하는 게 티처 포싱이에요."]},{"kind":"bg","src":"기초 다지기 6단원","lines":["**교차 엔트로피(Cross-Entropy)** 는 정답에 준 확률의 -log 예요.","확률이 1 이면 벌점 0, 확률이 작아질수록 벌점이 커져요."]}],"pass4":[{"kind":"check","q":"RNN 언어 모델의 손실은 어떻게 만드나요?","choices":["마지막 단어의 벌점만 쓴다","모든 시점의 교차 엔트로피를 평균 낸다","은닉 상태의 크기를 벌점으로 쓴다","정답 문장의 길이를 벌점으로 쓴다"],"a":1,"why":"매 시점이 문제 하나예요. 그 벌점들을 평균 내요."},{"kind":"english","head":"시험 답안 문장","en":"RNN 언어 모델은 매 시점에서 다음 토큰의 확률 분포를 내고 정답 토큰에 대한 교차 엔트로피를 벌점으로 매기며, 모든 시점의 벌점을 평균한 값을 손실로 쓴다.","ko":"시점마다, 교차 엔트로피, 평균 세 낱말을 넣어요.","tip":"교사 강요라는 말도 한 번 붙여 주면 좋아요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**교사 강요(Teacher Forcing)** 는 학습에서만 써요. 실제로 글을 만들 때는 자기 출력을 다시 넣어요."]}]},{"p":50,"title":"시간 역전파(BPTT)","terms":["Backpropagation Through Time (BPTT)","Backpropagation","Chain Rule","Computation Graph","Gradient","Parameter","Recurrent Neural Network (RNN)"],"pass1":[{"kind":"say","lines":["이름은 거창하지만 새 미분법이 아니에요. 2부의 **역전파(Backpropagation)** 그대로예요.","RNN 을 시간 축으로 쫙 펼치면 그냥 긴 신경망 하나가 돼요.","다만 같은 W_h 가 여러 자리에 쓰이므로, 그 자리들의 **기울기(Gradient)** 를 모두 **더해요**."]},{"kind":"analogy","head":"여러 교실에서 일한 한 선생님","scene":"한 선생님이 네 교실에서 같은 수업을 했어요. 성적이 나쁘면 네 교실의 책임을 모두 합쳐서 그 선생님에게 전해요.","map":[["한 선생님","공유된 W_h"],["네 교실","네 시점"],["책임을 합치기","기울기를 더하기"]]}],"pass2":[{"kind":"formula","head":"BPTT 의 한 줄","tex":"\\frac{\\partial J^{(t)}}{\\partial W_h} = \\sum_{i=1}^{t} \\left.\\frac{\\partial J^{(t)}}{\\partial W_h}\\right|_{(i)}","parts":[{"sym":"J^{(t)}","say":"t 번째 걸음의 손실"},{"sym":"W_h","say":"모든 걸음이 함께 쓰는 행렬"},{"sym":"\\sum_{i=1}^{t}","say":"W_h 가 쓰인 모든 자리에 대해"},{"sym":"\\big|_{(i)}","say":"i 번째 자리에서 나온 기울기만 따로 본 것"}],"whole":"2부의 '갈래에서는 **기울기(Gradient)** 를 더한다' 규칙을 시간 축에 그대로 쓴 것이에요."},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Wh appears at EVERY timestep = W_h 는 모든 시점에 등장한다","the gradient sums over all its appearances = 기울기는 등장한 모든 자리에 대해 더해진다","ordinary backprop on the unrolled graph = 펼친 그래프 위에서의 보통 역전파","accumulating into the shared W = 공유된 W 에 쌓아 올린다","nothing new was invented = 새로 발명된 것은 없다"]}],"pass3":[{"kind":"steps","head":"왜 더하는지 다시 짚어 봐요","given":"네 걸음짜리 RNN","steps":["2부에서 배운 규칙이 있어요. **계산 그래프(Computation Graph)** 에서 한 값이 여러 갈래로 쓰이면","역방향에서는 그 갈래들의 기울기를 모두 더해요","RNN 을 펼치면 W_h 가 1번, 2번, 3번, 4번 걸음에 모두 나와요","그러니 네 자리에서 온 기울기를 모두 더해서 W_h 를 한 번 고쳐요","이것이 **시간 역전파(Backpropagation Through Time (BPTT))** 이고, **연쇄 법칙(Chain Rule)** 은 그대로예요"],"answer":"새로운 것은 없어요. 갈래가 시간 축으로 펼쳐져 있을 뿐이에요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: W_h 가 모든 시점에 나오므로 기울기가 모든 등장에 대해 더해진다."},{"x":0.14,"y":0.31,"w":0.35,"h":0.11,"say":"가운데 식이 등장 자리마다의 기울기를 더한다는 뜻이에요."},{"x":0.05,"y":0.47,"w":0.9,"h":0.07,"say":"mechanically 줄: 펼친 그래프 위 보통 역전파를 공유 W 에 쌓는다."},{"x":0.05,"y":0.57,"w":0.9,"h":0.05,"say":"괄호 줄: 2부의 갈래에서 더한다 규칙 그대로, 새로 만든 것은 없다."}]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님: 이름이 좀 거창한데 새로운 미분법은 아니에요.","교수님: 시간에 따라 로스가 전파되기 때문에 BPTT 라고 합니다.","교수님: 포워드에서 한 값이 여러 갈래로 쓰이면 백워드에서는 기울기를 합한다고 했죠.","교수님: RNN 을 시간 축으로 쫙 펼친 다음 일반적인 역전파를 한다고 보시면 돼요."]},{"kind":"bg","src":"기초 다지기 7단원","lines":["**연쇄 법칙(Chain Rule)** 은 맞물린 톱니바퀴처럼 미분을 곱해 이어 붙이는 규칙이에요.","같은 값이 여러 곳에 쓰이면 그 영향들을 모두 더해야 해요."]}],"pass4":[{"kind":"check","q":"BPTT 에서 공유된 W_h 의 기울기는?","choices":["마지막 시점 것만 쓴다","첫 시점 것만 쓴다","모든 시점 것을 더한다","시점마다 따로 저장한다"],"a":2,"why":"2부의 갈래 규칙 그대로예요. 교수님이 새 미분법이 아니라고 강조했어요."},{"kind":"exam","src":"N3 Check Yourself","q":"Q3 (Parts 3 & 4). In an RNN, how many DIFFERENT weight matrices are applied over a 50-word sentence?","qko":"50 단어짜리 문장에서 RNN 이 쓰는 서로 다른 가중치 행렬은 몇 개인가요?","solve":["RNN 은 모든 시점에 같은 행렬을 되풀이해서 써요","쓰이는 행렬은 W_h, W_e, U 세 가지예요","50 단어든 500 단어든 이 세 가지가 반복될 뿐이에요","그래서 답은 50 개가 아니라 3 개예요"],"answer":"세 개예요. 문장 길이와 상관없이 W_h, W_e, U 를 재사용해요."},{"kind":"english","head":"시험 답안 문장","en":"BPTT 는 RNN 을 시간 축으로 펼쳐 보통의 역전파를 수행하되, 공유된 가중치가 등장하는 모든 시점의 기울기를 더해 한 번에 갱신하는 것이다.","ko":"펼치기와 더하기 두 낱말이 핵심이에요.","tip":"새 미분법이 아니라 연쇄 법칙에 덧셈 하나를 더한 것."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**시간 역전파(Backpropagation Through Time (BPTT))** 는 시점마다 다른 W 를 만드는 게 아니에요. 하나의 W 에 기울기를 모아요."]}]},{"p":51,"title":"생성과 성적표","terms":["Recurrent Neural Network (RNN)","Sampling","Hidden State","Embedding","Parallelization","n-gram","Language Model (LM)","Parameter"],"pass1":[{"kind":"say","lines":["**n-gram(엔그램)** 때와 똑같이 뽑고, 붙이고, 다시 넣기를 반복하면 글이 써져요.","다른 점은 **은닉 상태(Hidden State)** 덕분에 창 크기에 묶이지 않는다는 것이에요.","실습에서는 문자 단위 RNN 을 학습시켜 글을 쓰게 해 봐요.","그리고 얻은 것과 치른 값을 정리해요."]},{"kind":"analogy","head":"계속 이어 말하기 놀이","scene":"앞사람이 한 말을 듣고 다음 한 마디를 보태고, 그 말을 다시 들려주고 또 보태요. 메모장 덕분에 처음 한 말도 어느 정도 기억해요.","map":[["한 마디 보태기","**샘플링(Sampling)**"],["다시 들려주기","만든 토큰을 다시 입력으로"],["메모장","**은닉 상태(Hidden State)**"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Generate exactly like the n-gram loop = n-gram 때와 똑같은 반복으로 생성한다","sample, feed back in, repeat = 뽑고, 다시 넣고, 반복한다","but now with unbounded memory = 다만 이제 기억에 한계가 없다","a character-level RNN = 문자 단위 RNN","Wins / Prices = 얻은 것 / 치른 값"]},{"kind":"compare","head":"얻은 것과 치른 값","cols":["구분","내용"],"rows":[["얻음","임의 길이 문맥"],["얻음","모든 걸음이 같은 가중치를 공유"],["얻음","**임베딩(Embedding)** 덕분에 비슷한 단어가 정보를 공유"],["얻음","모델 크기가 문맥 길이와 무관 (**파라미터(Parameter)** 수가 고정)"],["치름","순차적이라 느리고 **병렬화(Parallelization)** 가 안 돼요"],["치름","실제로는 기억이 희미해져 먼 과거를 쓰기 어려워요"]]}],"pass3":[{"kind":"steps","head":"생성 고리를 한 바퀴 돌려 봐요","given":"시작 토큰 하나","steps":["시작 토큰을 넣고 다음 토큰의 확률 분포를 받아요","그 분포에서 **샘플링(Sampling)** 으로 토큰 하나를 뽑아요","뽑은 토큰을 결과에 붙이고 다음 입력으로 넣어요","은닉 상태는 계속 이어지니 앞 내용을 어느 정도 기억해요","끝 토큰이 나올 때까지 **다음 토큰 예측(Next Token Prediction)** 을 반복해요"],"answer":"n-gram 생성 고리와 모양이 똑같아요. 기억만 길어졌어요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 점: n-gram 고리와 똑같이 뽑고 다시 넣고 반복하되 기억이 무제한."},{"x":0.08,"y":0.26,"w":0.86,"h":0.05,"say":"실습 줄: 문자 단위 RNN 을 아무 글에나 학습시켜 그 문체로 쓰게 한다."},{"x":0.05,"y":0.33,"w":0.9,"h":0.06,"say":"Wins 줄: 임의 길이, 가중치 공유, 임베딩 유사도, 크기 무관."},{"x":0.05,"y":0.41,"w":0.9,"h":0.06,"say":"Prices 줄: 순차적이라 느리고 병렬화가 안 된다."},{"x":0.05,"y":0.48,"w":0.9,"h":0.06,"say":"Prices 줄: 실제로는 기억이 희미해진다. 왜 그런지가 다음 쪽이에요."}]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님: 생성 자체는 n-gram 과 크게 다르지 않아요. 다음 토큰을 예측하고 하나 선택하고 붙이고 반복해요.","교수님: 다만 RNN 은 은닉 상태로 읽은 정보를 계속 전달하기 때문에 고정된 윈도우 크기에 묶이지 않아요.","교수님: 이론적으로는 긴 문맥을 처리할 수 있는데 실제로는 먼 거리 의존을 배우기 어려워요."]}],"pass4":[{"kind":"check","q":"RNN 이 실제로 먼 과거를 잘 기억하지 못하는 이유는?","choices":["은닉 상태의 칸 수가 부족해서","기울기가 거꾸로 갈수록 희미해져서","소프트맥스가 포화되어서","임베딩이 없어서"],"a":1,"why":"**기울기 소실(Vanishing Gradient)** 때문이에요. 바로 다음 쪽에서 자세히 봐요."},{"kind":"english","head":"시험 답안 문장","en":"RNN 언어 모델은 확률 분포에서 토큰을 뽑아 다시 입력으로 넣는 고리로 문장을 생성하며, 은닉 상태 덕분에 고정된 창에 묶이지 않는다.","ko":"뽑고, 붙이고, 다시 넣기 고리를 적어요.","tip":"n-gram 생성과 모양은 같고 기억만 길다."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["이론상 무제한 기억과 실제 기억은 달라요. 슬라이드도 in PRACTICE 를 대문자로 썼어요."]}]},{"p":52,"title":"기울기 소실","terms":["Vanishing Gradient","Gradient","Jacobian","Backpropagation Through Time (BPTT)","Chain Rule","Hidden State","Recurrent Neural Network (RNN)"],"pass1":[{"kind":"say","lines":["먼 과거로 가는 **기울기(Gradient)** 는 걸음마다의 **야코비안(Jacobian)** 를 **곱한 것**이에요.","펼친 **계산 그래프(Computation Graph)** 를 거꾸로 걸으며 1 보다 조금 작은 수를 여러 번 곱해요.","그래서 멀리서 오는 학습 신호가 죽어요. 이것이 **기울기 소실(Vanishing Gradient)** 이에요."]},{"kind":"analogy","head":"귓속말 전달 게임","scene":"스무 명이 줄지어 귓속말을 전달하면 마지막 사람에게는 말이 거의 남지 않아요. 한 사람을 지날 때마다 조금씩 흐려지기 때문이에요.","map":[["한 사람을 지나기","한 시점의 야코비안을 곱하기"],["점점 흐려지는 말","**기울기(Gradient)**"],["마지막 사람이 못 알아듣기","**기울기 소실(Vanishing Gradient)**"]]}],"pass2":[{"kind":"formula","head":"기울기가 곱으로 쌓여요","tex":"\\frac{\\partial h^{(t)}}{\\partial h^{(1)}} = \\prod_{i=2}^{t} \\frac{\\partial h^{(i)}}{\\partial h^{(i-1)}}","parts":[{"sym":"h^{(t)}","say":"t 번째 걸음의 은닉 상태"},{"sym":"h^{(1)}","say":"첫 걸음의 은닉 상태"},{"sym":"\\prod","say":"더하기가 아니라 곱하기예요"},{"sym":"\\frac{\\partial h^{(i)}}{\\partial h^{(i-1)}}","say":"한 걸음짜리 야코비안"}],"whole":"작은 수를 여러 번 곱하면 0 으로, 큰 수를 여러 번 곱하면 무한대로 가요."},{"kind":"steps","head":"실제로 얼마나 작아지는지 계산해 봐요","given":"한 걸음 영향 0.9, 0.5, 1.1","steps":["한 걸음의 영향이 0.9 라고 해 봐요","20 걸음이면 0.9 의 20제곱 = 0.1216 이에요. 이미 8분의 1 수준이에요","50 걸음이면 0.9 의 50제곱 = 0.0052 예요. 거의 0 이에요","0.5 라면 20 걸음 만에 100만분의 1 보다 작아져요","반대로 1.1 이면 50 걸음에 117.39 로 커져요"],"answer":"곱셈이라 걸음 수에 따라 지수로 변해요. 그래서 아주 빠르게 죽거나 터져요."},{"kind":"figure","head":"뒤로 갈수록 신호가 희미해져요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 250\"><text x=\"240\" y=\"22\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">뒤로 갈수록 신호가 희미해져요<\/text><rect x=\"14\" y=\"60\" width=\"78\" height=\"30\" rx=\"2\" class=\"n b1\"/><text x=\"53.0\" y=\"79.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">h1<\/text><rect x=\"108\" y=\"60\" width=\"78\" height=\"30\" rx=\"2\" class=\"n b1\"/><text x=\"147.0\" y=\"79.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">h2<\/text><rect x=\"202\" y=\"60\" width=\"78\" height=\"30\" rx=\"2\" class=\"n b1\"/><text x=\"241.0\" y=\"79.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">h3<\/text><rect x=\"296\" y=\"60\" width=\"78\" height=\"30\" rx=\"2\" class=\"n b1\"/><text x=\"335.0\" y=\"79.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">h4<\/text><rect x=\"390\" y=\"60\" width=\"78\" height=\"30\" rx=\"2\" class=\"n b1\"/><text x=\"429.0\" y=\"79.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">h5<\/text><line x1=\"92\" y1=\"75\" x2=\"99.6\" y2=\"75.0\" class=\"e b1\"/><polygon points=\"106,75 98.0,71.0 98.0,79.0\" class=\"arrow b1\"/><line x1=\"186\" y1=\"75\" x2=\"193.6\" y2=\"75.0\" class=\"e b1\"/><polygon points=\"200,75 192.0,71.0 192.0,79.0\" class=\"arrow b1\"/><line x1=\"280\" y1=\"75\" x2=\"287.6\" y2=\"75.0\" class=\"e b1\"/><polygon points=\"294,75 286.0,71.0 286.0,79.0\" class=\"arrow b1\"/><line x1=\"374\" y1=\"75\" x2=\"381.6\" y2=\"75.0\" class=\"e b1\"/><polygon points=\"388,75 380.0,71.0 380.0,79.0\" class=\"arrow b1\"/><text x=\"240\" y=\"112\" font-size=\"13\" text-anchor=\"middle\" class=\"t b1\">앞으로 읽을 때는 한 걸음씩 잘 흘러요<\/text><line x1=\"106\" y1=\"146\" x2=\"98.4\" y2=\"146.0\" class=\"e2 b2\"/><polygon points=\"92,146 100.0,150.0 100.0,142.0\" class=\"arrow b2\"/><line x1=\"200\" y1=\"146\" x2=\"192.4\" y2=\"146.0\" class=\"e2 b2\"/><polygon points=\"186,146 194.0,150.0 194.0,142.0\" class=\"arrow b2\"/><line x1=\"294\" y1=\"146\" x2=\"286.4\" y2=\"146.0\" class=\"e2 b2\"/><polygon points=\"280,146 288.0,150.0 288.0,142.0\" class=\"arrow b2\"/><line x1=\"388\" y1=\"146\" x2=\"380.4\" y2=\"146.0\" class=\"e2 b2\"/><polygon points=\"374,146 382.0,150.0 382.0,142.0\" class=\"arrow b2\"/><text x=\"53\" y=\"172\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b3\">크게<\/text><text x=\"147\" y=\"172\" font-size=\"12\" text-anchor=\"middle\" class=\"t b3\">조금<\/text><text x=\"241\" y=\"172\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b3\">더 작게<\/text><text x=\"335\" y=\"172\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b3\">거의 0<\/text><text x=\"429\" y=\"172\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b3\">0<\/text><text x=\"240\" y=\"204\" font-size=\"13\" text-anchor=\"middle\" class=\"t b3\">거꾸로 갈 때는 걸음마다 작은 수를 곱해요<\/text><text x=\"240\" y=\"232\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b4\">0.9 를 20번 곱하면 0.1216, 50번이면 0.0052 예요<\/text><\/svg>","caption":"거꾸로 갈 때마다 작은 수가 곱해져요.","builds":4},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["The gradient from step t to step 1 is a PRODUCT of per-step Jacobians = t 에서 1 로 가는 기울기는 걸음마다의 야코비안의 곱이다","many small factors goes to 0 = 작은 인자가 많으면 0 으로 간다","many large goes to infinity = 큰 인자가 많으면 무한대로 간다","Long products of smallish factors = 조금 작은 인자들의 긴 곱","the learning signal from far away dies = 먼 곳에서 오는 학습 신호가 죽는다"]},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: t 에서 1 로 가는 기울기는 걸음마다 야코비안의 곱이다."},{"x":0.15,"y":0.31,"w":0.35,"h":0.11,"say":"가운데 식의 기호가 곱하기(파이)라는 점이 핵심이에요."},{"x":0.38,"y":0.33,"w":0.45,"h":0.07,"say":"괄호 안: 작은 인자가 많으면 0, 큰 인자가 많으면 무한대."},{"x":0.22,"y":0.53,"w":0.56,"h":0.1,"say":"그림에서 h1 부터 h5 까지 상자가 이어져요."},{"x":0.22,"y":0.61,"w":0.56,"h":0.07,"say":"빨간 화살표가 뒤로 갈수록 가늘어지는 것이 기울기가 줄어드는 모습이에요."}]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님: 로컬 그레디언트 곱하기 로컬 그레디언트 곱하기, 이렇게 계속 가는 거예요.","교수님: 각 단계의 영향이 0.9 라면 0.9 가 계속 곱해져서 왼쪽으로 갈수록 0 에 가까워져요.","교수님: 그래서 왼쪽에서는 업데이트가 안 되는 거죠."]},{"kind":"bg","src":"기초 다지기 4단원","lines":["0.9 를 20번 곱하는 것은 0.9의 20제곱이에요.","1 보다 작은 수는 곱할수록 작아지고, 1 보다 큰 수는 곱할수록 커져요."]}],"pass3":[{"kind":"check","q":"기울기 소실의 직접적인 원인은?","choices":["기울기를 계속 더해서","기울기를 계속 곱해서","소프트맥스를 써서","임베딩이 커서"],"a":1,"why":"곱셈이 원인이에요. 1 보다 작은 수를 여러 번 곱하면 지수로 작아져요."},{"kind":"english","head":"시험 답안 문장","en":"RNN 에서 먼 시점으로 가는 기울기는 시점마다의 야코비안을 곱한 값이므로, 인자가 1 보다 작으면 지수적으로 작아져 먼 과거의 학습 신호가 사라진다.","ko":"곱이라는 말과 지수적이라는 말을 꼭 넣어요.","tip":"귓속말 게임을 떠올리면 문장이 바로 나와요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**기울기 소실(Vanishing Gradient)** 은 기울기가 0 이 되는 게 아니라 0 에 아주 가까워지는 것이에요.","BPTT 에서 더하는 것은 공유 가중치의 기울기이고, 여기서 곱하는 것은 시점 사이의 야코비안이에요."]}],"pass4":[]},{"p":53,"title":"왜 문제인가, 그리고 거울 문제","terms":["Vanishing Gradient","Exploding Gradient","Gradient Clipping","Gradient","Stochastic Gradient Descent (SGD)","Learning Rate"],"pass1":[{"kind":"say","lines":["She bought extra toner for the ____ 에서 답 printer 는 20 단어 앞에 있었어요.","20 걸음 앞의 **기울기(Gradient)** 가 거의 0 이면 모델은 그 관계를 못 배워요. 가까운 단어만 보고 찍어요.","거울 문제도 있어요. 인자가 1 보다 조금 크면 **기울기 폭발(Exploding Gradient)** 이 나고 **확률적 경사 하강법(SGD)** 한 걸음이 튀어요.","폭발은 **기울기 클리핑(Gradient Clipping)** 으로 막을 수 있어요. 소실은 구조를 바꿔야 해요."]},{"kind":"analogy","head":"고무줄 늘리기","scene":"고무줄을 조금씩 줄이면 금세 안 보이게 작아지고, 조금씩 늘리면 어느 순간 끊어질 만큼 길어져요. 끊어지는 건 붙잡아 자르면 되지만, 사라진 건 되살릴 수 없어요.","map":[["줄어드는 쪽","**기울기 소실(Vanishing Gradient)**"],["늘어나는 쪽","**기울기 폭발(Exploding Gradient)**"],["붙잡아 자르기","**기울기 클리핑(Gradient Clipping)**"]]}],"pass2":[{"kind":"formula","head":"기울기 클리핑","tex":"\\text{if } \\lVert g \\rVert > \\tau : \\quad g \\leftarrow \\tau \\frac{g}{\\lVert g \\rVert}","parts":[{"sym":"g","say":"기울기 벡터"},{"sym":"\\lVert g \\rVert","say":"그 벡터의 길이(노름)"},{"sym":"\\tau","say":"정해 둔 최대 길이(임계값)"},{"sym":"g / \\lVert g \\rVert","say":"길이를 1 로 만든 방향만 남긴 벡터"}],"whole":"방향은 그대로 두고 길이만 임계값으로 줄여요."},{"kind":"steps","head":"클리핑을 손으로 해 봐요","given":"g = (3, 4), 임계값 1 과 2","steps":["기울기가 g = (3, 4) 라고 해요","길이는 루트(9 + 16) = 5 예요","임계값이 1 이면 5 가 1 보다 크니 잘라요","g 나누기 5 = (0.6, 0.8) 이 방향만 남긴 벡터예요","여기에 1 을 곱하면 (0.6, 0.8) 이에요","임계값이 2 라면 (1.2, 1.6) 이고 길이가 정확히 2 예요"],"answer":"방향은 그대로, 길이만 임계값이 돼요."},{"kind":"figure","head":"방향은 두고 길이만 잘라요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 250\"><text x=\"240\" y=\"22\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">방향은 두고 길이만 잘라요<\/text><line x1=\"40\" y1=\"190\" x2=\"40\" y2=\"50\" class=\"e b1\"/><line x1=\"40\" y1=\"190\" x2=\"220\" y2=\"190\" class=\"e b1\"/><line x1=\"40\" y1=\"190\" x2=\"142.7\" y2=\"121.6\" class=\"e2 b2\"/><polygon points=\"148,118 139.1,119.1 143.6,125.8\" class=\"arrow b2\"/><text x=\"150\" y=\"108\" font-size=\"12\" text-anchor=\"middle\" class=\"t b2\">기울기 (3, 4), 길이 5<\/text><line x1=\"260\" y1=\"190\" x2=\"260\" y2=\"50\" class=\"e b3\"/><line x1=\"260\" y1=\"190\" x2=\"440\" y2=\"190\" class=\"e b3\"/><line x1=\"260\" y1=\"190\" x2=\"276.6\" y2=\"179.4\" class=\"e2 b3\"/><polygon points=\"282,176 273.1,176.9 277.4,183.7\" class=\"arrow b3\"/><text x=\"340\" y=\"150\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b4\">자른 뒤 (0.6, 0.8)<\/text><text x=\"340\" y=\"172\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">길이 1, 방향은 그대로<\/text><text x=\"240\" y=\"226\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b4\">기울기 폭발은 막지만 기울기 소실은 못 고쳐요<\/text><\/svg>","caption":"왼쪽은 자르기 전, 오른쪽은 자른 뒤예요.","builds":4},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["the answer (printer) was 20 words ago = 답인 printer 는 20 단어 앞에 있었다","it guesses from recent words instead = 대신 최근 단어들로 찍는다","Mirror image, exploding gradients = 거울 문제, 기울기 폭발","factors slightly greater than 1 = 1 보다 조금 큰 인자들","one insane SGD step (or Inf/NaN) = 말도 안 되는 SGD 한 걸음 (또는 Inf, NaN)","keep the direction, cap the size = 방향은 유지하고 크기만 제한한다","vanishing needs a better ARCHITECTURE = 소실은 더 나은 구조가 필요하다"]},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: 답 printer 가 20 단어 앞에 있는 예문."},{"x":0.08,"y":0.24,"w":0.86,"h":0.05,"say":"들여쓴 줄: 20 걸음 앞 기울기가 0 이면 그 관계를 배울 수 없다."},{"x":0.05,"y":0.29,"w":0.9,"h":0.05,"say":"둘째 점: 거울 문제인 기울기 폭발과 Inf, NaN."},{"x":0.05,"y":0.35,"w":0.9,"h":0.05,"say":"셋째 점: 표준 응급처치는 기울기 클리핑."},{"x":0.37,"y":0.58,"w":0.26,"h":0.08,"say":"가운데 식이 클리핑 공식이에요."},{"x":0.35,"y":0.69,"w":0.3,"h":0.13,"say":"아래 두 그림이 자르기 전과 후의 한 걸음이에요."}]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님: 그레디언트가 너무 폭발하면 같은 학습률에도 **확률적 경사 하강법(SGD)** 가 확 업데이트가 돼 버려요.","교수님: 심하면 값이 NaN 이 뜨는데, 한 번 NaN 에 빠지면 복구 불능이에요. **확률적 경사 하강법(SGD)** 가 망가지는 거죠.","교수님: 클리핑으로 익스플로딩 그레디언트는 해결할 수 있는데 베니싱 그레디언트는 해결이 어렵습니다.","교수님: 작은 기울기는 임계값을 넘지 않기 때문에 클리핑이 아무것도 해 주지 못해요."]},{"kind":"bg","src":"기초 다지기 2단원","lines":["벡터의 길이(노름)는 각 칸을 제곱해 더한 뒤 제곱근을 씌운 값이에요.","(3, 4) 는 3의 제곱 9 더하기 4의 제곱 16 = 25, 제곱근은 5 예요."]}],"pass3":[{"kind":"check","q":"기울기 클리핑이 고치지 못하는 것은?","choices":["**기울기 폭발(Exploding Gradient)**","**기울기 소실(Vanishing Gradient)**","NaN 발생","너무 큰 한 걸음"],"a":1,"why":"작은 기울기는 임계값을 넘지 않아서 클리핑이 손댈 일이 없어요. 교수님이 직접 설명한 부분이에요."},{"kind":"exam","src":"N3 Check Yourself","q":"Q4 (Parts 3 & 4). Gradient clipping fixes exploding gradients. Why does it NOT fix vanishing ones?","qko":"기울기 클리핑은 폭발을 고치는데, 왜 소실은 못 고치나요?","solve":["클리핑은 기울기가 임계값보다 클 때 크기를 줄이는 방식이에요","기울기 소실은 반대로 기울기가 이미 너무 작아진 상태예요","작은 기울기는 임계값을 넘지 않으니 클리핑이 손대지 않아요","소실을 고치려면 구조를 바꿔야 해요. 게이트나 어텐션이 그것이에요"],"answer":"클리핑은 큰 기울기만 줄이기 때문이에요. 작은 기울기는 그대로 작게 남아요."},{"kind":"english","head":"시험 답안 문장","en":"기울기 클리핑은 기울기의 길이가 임계값을 넘을 때 방향은 유지하고 크기만 줄이므로 기울기 폭발을 막지만, 이미 작아진 기울기에는 작동하지 않아 기울기 소실은 해결하지 못한다.","ko":"방향 유지, 크기 제한, 그리고 작은 것에는 작동 안 함을 적어요.","tip":"큰 것만 자르는 가위라고 생각해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**기울기 클리핑(Gradient Clipping)** 은 **학습률(Learning Rate)** 을 줄이는 것과 달라요. 학습률은 모든 걸음에 영향을 주고, 클리핑은 너무 큰 걸음만 손봐요."]}],"pass4":[]},{"p":54,"title":"처방 미리 보기: 게이트, 그다음 어텐션","terms":["LSTM","Gate","Attention","Vanishing Gradient","Hidden State","Gradient","Recurrent Neural Network (RNN)"],"pass1":[{"kind":"say","lines":["**기울기 소실(Vanishing Gradient)** 을 고치려면 구조를 바꿔야 해요.","**LSTM(장단기 메모리)** 과 GRU 는 장기 기억용 고속도로(셀 상태)와 **게이트(Gate)** 를 더해요.","**기울기(Gradient)** 가 그 고속도로를 타고 흘러서 먼 거리 의존을 배울 수 있어요.","더 큰 처방은 다음 주에 나와요. 과거를 벡터 하나에 욱여넣지 말자는 **어텐션(Attention)** 이에요."]},{"kind":"analogy","head":"고속도로와 국도","scene":"마을마다 서는 국도로 가면 시간이 오래 걸리고 짐도 상해요. 중간에 안 서는 고속도로를 하나 깔면 짐이 그대로 도착해요.","map":[["국도","은닉 상태를 매번 곱해서 지나가기"],["고속도로","셀 상태(cell state)"],["짐","**기울기(Gradient)**"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["add a cell state highway = 셀 상태라는 고속도로를 더한다","learned gates that decide what to keep, write, and reveal = 무엇을 지키고, 쓰고, 드러낼지 정하는 학습된 문들","gradients ride the highway = 기울기가 고속도로를 탄다","long dependencies become learnable = 먼 거리 의존을 배울 수 있게 된다","the standard RNN unit for a decade = 10년간 표준 RNN 단위였다","stop squeezing history through one vector = 과거를 벡터 하나에 욱여넣지 마라","let every step attend to every other = 모든 걸음이 서로를 바라보게 하라"]},{"kind":"compare","head":"세 가지 게이트","cols":["게이트","하는 일"],"rows":[["잊기(forget)","셀 상태에서 무엇을 버릴지 정해요"],["쓰기(input)","새 정보를 얼마나 적어 넣을지 정해요"],["내보내기(output)","셀 상태에서 무엇을 은닉 상태로 드러낼지 정해요"]]}],"pass3":[{"kind":"figure","head":"장기 기억 고속도로","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 250\"><text x=\"240\" y=\"22\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">장기 기억 고속도로<\/text><line x1=\"20\" y1=\"70\" x2=\"460\" y2=\"70\" class=\"e2 b1\"/><text x=\"240\" y=\"56\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b1\">셀 상태 c: 곱셈 없이 쭉 지나가요<\/text><rect x=\"140\" y=\"96\" width=\"200\" height=\"78\" rx=\"2\" class=\"box b2\"/><text x=\"240\" y=\"116\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">LSTM 셀<\/text><rect x=\"150\" y=\"128\" width=\"56\" height=\"30\" rx=\"2\" class=\"box2 b3\"/><text x=\"178.0\" y=\"146.85\" font-size=\"11\" text-anchor=\"middle\" class=\"tl b3\">잊기<\/text><rect x=\"212\" y=\"128\" width=\"56\" height=\"30\" rx=\"2\" class=\"box2 b3\"/><text x=\"240.0\" y=\"146.85\" font-size=\"11\" text-anchor=\"middle\" class=\"tl b3\">쓰기<\/text><rect x=\"274\" y=\"128\" width=\"56\" height=\"30\" rx=\"2\" class=\"box2 b3\"/><text x=\"302.0\" y=\"146.85\" font-size=\"11\" text-anchor=\"middle\" class=\"tl b3\">내보내기<\/text><line x1=\"20\" y1=\"200\" x2=\"140\" y2=\"200\" class=\"e b4\"/><line x1=\"340\" y1=\"200\" x2=\"460\" y2=\"200\" class=\"e b4\"/><text x=\"80\" y=\"190\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">h, x<\/text><text x=\"400\" y=\"190\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">새 h<\/text><text x=\"240\" y=\"232\" font-size=\"13\" text-anchor=\"middle\" class=\"t b4\">게이트가 무엇을 남길지 스스로 배워요<\/text><\/svg>","caption":"셀 상태는 곱셈 없이 지나가고, 게이트가 무엇을 남길지 정해요.","builds":4},{"kind":"points","head":"LSTM 이 기울기 소실을 줄이는 이유","items":["보통 **RNN(순환 신경망)** 은 **은닉 상태(Hidden State)** 하나에 모든 정보를 욱여넣고 매 걸음 곱셈을 지나요.","LSTM 은 셀 상태를 따로 두고 비선형 변환을 거치지 않고 거의 그대로 통과시켜요.","그래서 **기울기(Gradient)** 가 긴 곱셈을 피해 먼 과거까지 닿아요."]},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: LSTM, GRU 는 셀 상태 고속도로와 학습된 게이트를 더한다."},{"x":0.2,"y":0.28,"w":0.6,"h":0.05,"say":"그림 제목: LSTM 셀, 차세대 RNN 단위."},{"x":0.35,"y":0.4,"w":0.3,"h":0.07,"say":"가운데 세 동그라미가 잊기, 쓰기, 내보내기 게이트예요."},{"x":0.05,"y":0.66,"w":0.9,"h":0.05,"say":"둘째 점: 기울기가 고속도로를 타서 먼 의존을 배울 수 있다."},{"x":0.05,"y":0.71,"w":0.9,"h":0.05,"say":"셋째 점: 더 큰 처방은 다음 주의 어텐션이다."}]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님: 모든 정보를 은닉 상태 하나에 억지로 저장하는 대신 장기 기억 셀을 하나 만들어요.","교수님: 그 셀은 h 와 곱해지는 것 없이 하이웨이 고속도로처럼 쭉 통과를 시키는 거죠.","교수님: 게이트까지 수업하자면 너무 어려워지니, 어떤 정보는 기억하고 어떤 정보는 새로 쓰는 것을 모델이 스스로 배운다고 보시면 돼요.","교수님: LSTM 과 GRU 가 트랜스포머 나오기 전까지 시퀀스 모델링의 표준 구조였죠."]}],"pass4":[{"kind":"check","q":"LSTM 의 셀 상태가 기울기 소실을 줄이는 이유는?","choices":["곱셈과 비선형을 거의 거치지 않고 지나가서","은닉 상태보다 칸이 많아서","소프트맥스를 쓰지 않아서","학습률을 자동으로 조절해서"],"a":0,"why":"고속도로처럼 거의 그대로 통과해서 긴 곱셈을 피해요."},{"kind":"english","head":"시험 답안 문장","en":"LSTM 과 GRU 는 셀 상태라는 경로와 잊기, 쓰기, 내보내기 게이트를 두어 기울기가 긴 곱셈을 거치지 않고 흐르게 하므로 먼 거리 의존을 학습할 수 있다.","ko":"셀 상태, 게이트 세 개, 기울기가 흐른다를 넣어요.","tip":"고속도로 비유를 그대로 쓰면 돼요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**LSTM(장단기 메모리)** 도 여전히 순차 계산이에요. 앞 시점을 기다려야 해서 병렬화는 안 돼요."]}]},{"p":55,"title":"또 하나의 예고: seq2seq","terms":["seq2seq","Encoder","Decoder","Machine Translation (MT)","Language Model (LM)","Recurrent Neural Network (RNN)","Attention"],"pass1":[{"kind":"say","lines":["**RNN(순환 신경망)** 이 새로운 모양의 문제를 열었어요. 시퀀스가 들어와서 시퀀스가 나가는 문제예요.","**인코더(Encoder)** RNN 이 원문을 끝까지 읽어 요약을 만들고, **디코더(Decoder)** RNN 이 답 문장을 한 토큰씩 만들어요.","**디코더(Decoder)** 는 사실 조건이 붙은 **언어 모델(LM)** 이에요. 오늘 배운 것을 그대로 다시 쓰는 거예요.","4주차의 출발점이에요."]},{"kind":"analogy","head":"통역사 두 사람","scene":"한 사람이 한국어를 끝까지 듣고 머릿속에 정리해요. 그 정리를 받아 다른 사람이 영어로 한 마디씩 말해요.","map":[["듣는 사람","**인코더(Encoder)**"],["머릿속 정리","벡터 하나"],["말하는 사람","**디코더(Decoder)**"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["sequence in, sequence out = 시퀀스가 들어오고 시퀀스가 나간다","the decoder is literally a conditional language model = 디코더는 말 그대로 조건부 언어 모델이다","everything from today, reused = 오늘 배운 것을 그대로 다시 쓴다","machine translation, summarization, dialogue = **기계 번역(Machine Translation (MT))**, 요약, 대화","one architecture, week 4's starting point = 하나의 구조, 4주차의 출발점"]},{"kind":"compare","head":"어떤 과제에 쓰나요","cols":["과제","들어오는 것","나가는 것"],"rows":[["**기계 번역(Machine Translation (MT))**","한국어 문장","영어 문장"],["요약","긴 글","짧은 요약"],["대화","상대의 말","내 대답"]]}],"pass3":[{"kind":"figure","head":"줄줄이 들어와 줄줄이 나가요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 250\"><text x=\"240\" y=\"22\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">줄줄이 들어와 줄줄이 나가요<\/text><rect x=\"16\" y=\"60\" width=\"62\" height=\"28\" rx=\"2\" class=\"n b1\"/><text x=\"47.0\" y=\"78.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">나는<\/text><rect x=\"90\" y=\"60\" width=\"62\" height=\"28\" rx=\"2\" class=\"n b1\"/><text x=\"121.0\" y=\"78.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">학생<\/text><rect x=\"164\" y=\"60\" width=\"62\" height=\"28\" rx=\"2\" class=\"n b1\"/><text x=\"195.0\" y=\"78.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">이다<\/text><line x1=\"240\" y1=\"74\" x2=\"261.6\" y2=\"74.0\" class=\"e2 b2\"/><polygon points=\"268,74 260.0,70.0 260.0,78.0\" class=\"arrow b2\"/><rect x=\"270\" y=\"58\" width=\"90\" height=\"32\" rx=\"2\" class=\"n4 b2\"/><text x=\"315.0\" y=\"78.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b2\">벡터 하나<\/text><line x1=\"362\" y1=\"74\" x2=\"385.6\" y2=\"74.0\" class=\"e2 b3\"/><polygon points=\"392,74 384.0,70.0 384.0,78.0\" class=\"arrow b3\"/><rect x=\"394\" y=\"58\" width=\"74\" height=\"32\" rx=\"2\" class=\"box2 b3\"/><text x=\"431.0\" y=\"78.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b3\">디코더<\/text><rect x=\"16\" y=\"140\" width=\"92\" height=\"28\" rx=\"2\" class=\"box b4\"/><text x=\"62.0\" y=\"158.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b4\">I<\/text><rect x=\"126\" y=\"140\" width=\"92\" height=\"28\" rx=\"2\" class=\"box b4\"/><text x=\"172.0\" y=\"158.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b4\">am<\/text><rect x=\"236\" y=\"140\" width=\"92\" height=\"28\" rx=\"2\" class=\"box b4\"/><text x=\"282.0\" y=\"158.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b4\">a<\/text><rect x=\"346\" y=\"140\" width=\"92\" height=\"28\" rx=\"2\" class=\"box b4\"/><text x=\"392.0\" y=\"158.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b4\">student<\/text><text x=\"240\" y=\"196\" font-size=\"13\" text-anchor=\"middle\" class=\"t b4\">인코더 RNN 이 읽고 디코더 RNN 이 써요<\/text><text x=\"240\" y=\"224\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">긴 문장이면 벡터 하나가 좁아요. 그게 다음 주 이야기예요<\/text><\/svg>","caption":"인코더가 읽고, 벡터 하나를 거쳐, 디코더가 써요.","builds":4},{"kind":"steps","head":"번역 한 문장을 따라가 봐요","given":"나는 학생이다","steps":["인코더 RNN 이 나는, 학생, 이다 를 차례로 읽어요","마지막 은닉 상태에 문장 전체의 정보가 모여요","디코더 RNN 이 그 벡터를 받아 I 를 만들어요","I 를 다시 넣어 am 을 만들고, 이렇게 끝까지 이어가요","문장이 길어지면 벡터 하나에 다 담기가 어려워져요"],"answer":"마지막 줄의 어려움이 바로 4주차에 **어텐션(Attention)** 이 나오는 이유예요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: RNN 이 시퀀스 입력, 시퀀스 출력이라는 새 문제 모양을 열었다."},{"x":0.08,"y":0.25,"w":0.86,"h":0.05,"say":"들여쓴 줄: 디코더는 말 그대로 조건부 언어 모델이다."},{"x":0.05,"y":0.31,"w":0.9,"h":0.05,"say":"셋째 점: 번역, 요약, 대화. 하나의 구조, 4주차의 출발점."},{"x":0.2,"y":0.85,"w":0.6,"h":0.05,"say":"맨 아래: 오늘의 언어 모델이 모든 seq2seq 시스템 속 엔진이다."}]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님: 인코더 RNN 이 원문을 처음부터 끝까지 읽으면서 하나의 은닉 상태에 다 모아요.","교수님: 그 정보를 기반으로 디코더 RNN 이 하나씩 하나씩 생성해 나가는 거예요.","교수님: 굉장히 긴 문장을 은닉 상태 하나에 다 저장해야 하니 좀 안 좋다는 거죠.","교수님: 그래서 지금 스텝에서 어디를 봐야 할지 결정하는 게 어텐션이라는 기법이고, 다음 시간에 배워요."]}],"pass4":[{"kind":"check","q":"seq2seq 의 디코더는 무엇인가요?","choices":["분류기","조건이 붙은 언어 모델","토크나이저","임베딩 표"],"a":1,"why":"슬라이드가 literally a conditional language model 이라고 썼어요. 오늘 배운 것을 그대로 써요."},{"kind":"english","head":"시험 답안 문장","en":"seq2seq 는 인코더 RNN 이 입력 시퀀스를 읽어 벡터로 요약하고 디코더 RNN 이 그 벡터를 조건으로 출력 시퀀스를 생성하는 구조이며, 디코더는 조건부 언어 모델이다.","ko":"인코더, 디코더, 조건부 언어 모델 세 낱말이 핵심이에요.","tip":"통역사 두 사람 비유로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["인코더와 디코더는 서로 다른 RNN 이에요. 가중치를 공유하지 않아요."]}]},{"p":56,"title":"확인 문제 2 (3부와 4부)","terms":["n-gram","Sparsity Problem","Perplexity (PPL)","Tokenizer","Vocabulary","Recurrent Neural Network (RNN)","Parameter","Gradient Clipping","Exploding Gradient","Vanishing Gradient"],"pass1":[{"kind":"say","lines":["교수님이 직접 낸 확인 문제 네 개예요. 수업에서 답까지 말해 주었어요.","슬라이드가 '이 네 문제가 바로 시험 단답형의 맛' 이라고 적어 놨어요.","시험 대비 1순위예요. 답을 말로 할 수 있을 때까지 읽어요."]}],"pass2":[{"kind":"points","head":"네 문제를 우리말로","items":["Q1. 5-gram 언어 모델이 학습 때 한 번도 못 본 5-gram 을 만나면 확률이 얼마이고, 어떻게 하나요?","Q2. 퍼플렉서티 40 과 25 중 어느 쪽이 좋고, 언제 이 비교가 의미가 없어지나요?","Q3. RNN 이 50 단어 문장에서 쓰는 서로 다른 가중치 행렬은 몇 개인가요?","Q4. 기울기 클리핑은 폭발을 고치는데, 왜 소실은 못 고치나요?"]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.09,"say":"Q1: 못 본 5-gram 에 어떤 확률을 주고 무엇을 하는가."},{"x":0.05,"y":0.3,"w":0.9,"h":0.05,"say":"Q2: 퍼플렉서티 40 과 25, 언제 비교가 무의미한가."},{"x":0.05,"y":0.37,"w":0.9,"h":0.05,"say":"Q3: 50 단어 문장에서 서로 다른 가중치 행렬은 몇 개인가."},{"x":0.05,"y":0.44,"w":0.9,"h":0.05,"say":"Q4: 클리핑이 소실을 못 고치는 이유."},{"x":0.2,"y":0.85,"w":0.6,"h":0.05,"say":"맨 아래: 이 네 문제가 정확히 시험 단답형의 맛이다."}]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님(Q1): 카운팅 방식에서는 그 5-gram 의 확률이 0 이 되고, 문장 전체 확률도 0 이 돼요.","교수님(Q1): 그래서 스무딩을 주거나 작은 확률을 주거나 윈도우를 줄여서 백오프를 해요.","교수님(Q2): 퍼플렉서티는 낮을수록 좋으니 25 가 40 보다 좋아요.","교수님(Q2): 다만 같은 평가 데이터, 같은 어휘, 같은 토크나이저여야 비교가 의미 있어요."]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님(Q3): 50 단어든 500 단어든 가중치 행렬은 타임 스텝에 상관없이 재활용해요.","교수님(Q3): 각 타임 스텝에서 똑같은 행렬을 반복해서 사용한다는 게 RNN 의 핵심이죠.","교수님(Q4): 클리핑은 기울기가 너무 클 때 크기를 일정 한도까지 줄여 주는 방식이에요.","교수님(Q4): 작은 기울기는 임계값을 넘지 않기 때문에 클리핑이 아무것도 해 주지 못해요."]}],"pass4":[{"kind":"exam","src":"N3 Check Yourself","q":"Q1. A 5-gram LM sees a test sentence whose 5-gram never occurred in training. What probability does it assign, and what do we do about it?","qko":"학습 때 못 본 5-gram 을 만나면 확률이 얼마이고, 무엇을 하나요?","solve":["세기 방식이라 그 **n-gram(엔그램)** 의 횟수가 0 이에요","확률이 0 이 되고, 곱하기 때문에 문장 전체 확률도 0 이 돼요","고치는 방법 1: 스무딩으로 아주 작은 확률을 나눠 줘요","고치는 방법 2: 백오프로 더 짧은 문맥으로 물러나 세요"],"answer":"확률 0 이 되고, 스무딩이나 백오프로 고쳐요. 이것이 **희소성 문제(Sparsity Problem)** 예요."},{"kind":"exam","src":"N3 Check Yourself","q":"Q2. Two LMs report perplexity 40 and 25. Which is better, and when is that comparison meaningless?","qko":"퍼플렉서티 40 과 25 중 어느 쪽이 좋고, 언제 비교가 무의미한가요?","solve":["**퍼플렉서티(PPL)** 는 낮을수록 좋으니 25 가 더 좋아요","40 나누기 25 = 1.6 배 차이예요","단, 같은 평가 데이터, 같은 **어휘(Vocabulary)**, 같은 **토크나이저(Tokenizer)** 여야 해요","예를 들어 한쪽은 문자 단위, 다른 쪽은 서브워드 단위면 숫자를 그대로 비교할 수 없어요"],"answer":"25 가 좋아요. 데이터, 어휘, 토크나이저가 다르면 비교가 무의미해요."},{"kind":"check","q":"퍼플렉서티를 비교할 때 반드시 같아야 하는 것이 아닌 것은?","choices":["평가 데이터","어휘","토크나이저","모델의 층 수"],"a":3,"why":"층 수는 달라도 돼요. 같아야 하는 것은 평가 조건 세 가지예요."},{"kind":"english","head":"시험 답안 문장","en":"퍼플렉서티는 낮을수록 좋지만, 같은 평가 데이터와 같은 어휘, 같은 토크나이저를 쓴 모델끼리만 숫자를 직접 비교할 수 있다.","ko":"낮을수록 좋다와 세 가지 조건을 함께 적어요.","tip":"교수님이 변인 통제라는 말로 강조한 부분이에요."},{"kind":"warn","head":"시험에 나올 만한 곳","items":["이 네 문제는 교수님이 직접 낸 확인 문제예요. 형태 그대로 시험에 나올 가능성이 가장 높아요."]}]},{"p":57,"title":"마무리: 요약, 실습, 과제 2","terms":["Nonlinearity","Multi-Layer Perceptron (MLP)","Convolutional Neural Network (CNN)","Chain Rule","Backpropagation","Language Model (LM)","n-gram","Perplexity (PPL)","Recurrent Neural Network (RNN)","Backpropagation Through Time (BPTT)","Vanishing Gradient","Gradient Clipping","Attention","word2vec","Skip-gram"],"pass1":[{"kind":"say","lines":["3주차 전체를 네 줄로 묶는 쪽이에요.","신경망, 학습, 언어 모델, RNN 순서예요.","실습과 과제 2 안내도 여기 있어요."]},{"kind":"points","head":"네 줄 요약","items":["신경망: 뉴런은 선형 더하기 구부림. 구부림은 **렐루(ReLU)** 같은 활성화 함수예요","깊이에는 **비선형성(Nonlinearity)** 이 필요해서 층을 쌓아 **MLP(다층 퍼셉트론)** 를 만들었어요","**CNN(합성곱 신경망)** 은 n-gram 탐지기를 병렬로 돌리는 것이었어요","**MLP(다층 퍼셉트론)** 와 **CNN(합성곱 신경망)** 은 모두 1부에서 배운 신경망 모양이에요","학습: **야코비안(Jacobian)** 를 쓰는 **연쇄 법칙(Chain Rule)**, 델타 재사용, **역전파(Backpropagation)** 는 순전파 한 번 값으로 그래프를 거슬러 걷기","**언어 모델(LM)**: 다음 단어 맞히기. **n-gram(엔그램)** 은 세다가 벽을 만나고, **퍼플렉서티(PPL)** 는 exp(손실)","**RNN(순환 신경망)**: 공유 가중치와 **은닉 상태(Hidden State)**, **시간 역전파(Backpropagation Through Time (BPTT))**, 소실과 폭발 그리고 클리핑, 게이트, **어텐션(Attention)**"]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["neuron = linear + bend = 뉴런은 선형 변환에 구부림 하나","depth needs nonlinearity = 깊이에는 비선형이 필요하다","CNN = parallel n-gram detectors = CNN 은 병렬 n-gram 탐지기","chain rule with Jacobians = 야코비안을 쓰는 연쇄 법칙","backprop = graph walk at the cost of one forward pass = 역전파는 순전파 한 번 값으로 그래프를 걷는 것","perplexity = exp(loss) = 퍼플렉서티는 손실의 exp","shared weights + hidden state = 공유 가중치 더하기 은닉 상태"]},{"kind":"compare","head":"실습과 과제","cols":["무엇","내용"],"rows":[["실습(1시간)","PyTorch 텐서와 autograd, 문자 단위 RNN 언어 모델 만들고 학습, 글 생성, 퍼플렉서티 재기"],["1부 복습","**MLP(다층 퍼셉트론)** 와 **렐루(ReLU)**, 그리고 **CNN(합성곱 신경망)** 이 여기서 나왔어요"],["과제 2","**word2vec(워드투벡)** 기울기를 **손으로** 구하기 + **스킵그램(Skip-gram)** 구현"],["배점과 기한","슬라이드 표기 15%, due W7 10/12 (녹음에서는 10월 7일까지라고 말했어요)"]]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"Networks 줄: 뉴런, 깊이와 비선형, CNN."},{"x":0.05,"y":0.25,"w":0.9,"h":0.05,"say":"Learning 줄: 연쇄 법칙, 델타 재사용, 역전파."},{"x":0.05,"y":0.31,"w":0.9,"h":0.05,"say":"Language models 줄: 다음 단어 예측, n-gram 의 벽, 퍼플렉서티."},{"x":0.05,"y":0.37,"w":0.9,"h":0.05,"say":"RNNs 줄: 공유 가중치, BPTT, 소실과 폭발, 클리핑과 게이트와 어텐션."},{"x":0.05,"y":0.43,"w":0.9,"h":0.05,"say":"Lab 줄: PyTorch 텐서와 autograd, 문자 RNN 언어 모델."},{"x":0.05,"y":0.49,"w":0.9,"h":0.05,"say":"Assignment 2 줄: word2vec 기울기 손계산과 skip-gram 구현."}]},{"kind":"prof","when":"3주차 월요일 3교시","lines":["교수님: 선형 변환만 쌓아서는 충분하지 않아서 중간중간에 비선형을 넣어 MLP 를 구성했다는 걸 배웠어요.","교수님: 역전파에서 핵심은 체인 룰이었죠. 로컬 기울기만 구하면 연쇄 법칙으로 전달만 하면 돼요.","교수님: 언어 모델링은 앞 문맥을 보고 다음 토큰의 확률 분포를 예측하는 게 핵심이었고요.","교수님: RNN 은 같은 가중치를 고정해 놓고 반복해서 은닉 상태를 넘겨주는 것이었죠."]}],"pass4":[{"kind":"check","q":"3주차에서 다음 주(4주차)로 이어지는 개념은?","choices":["토큰화","원-핫 벡터","**어텐션(Attention)**","지프의 법칙"],"a":2,"why":"기울기 소실을 구조로 고치는 더 큰 처방이 어텐션이에요. 4주차의 주인공이에요."},{"kind":"english","head":"시험 답안 문장","en":"3주차는 뉴런과 비선형, 연쇄 법칙과 역전파, 언어 모델과 퍼플렉서티, 그리고 공유 가중치와 은닉 상태를 쓰는 RNN 과 그 기울기 문제를 다루었다.","ko":"네 덩이를 순서대로 한 문장에 담아요.","tip":"신경망, 학습, 언어 모델, RNN. 네 낱말로 외워요."},{"kind":"warn","head":"과제와 이어지는 부분","items":["과제 2 는 2주차의 **word2vec(워드투벡)** 기울기를 손으로 구하고 **스킵그램(Skip-gram)** 을 구현하는 것이에요.","3주차의 연쇄 법칙과 야코비안이 바로 그 손계산에 쓰여요. 오늘 배운 것을 바로 쓰는 과제예요.","기한은 슬라이드와 녹음이 다르게 말하니 공지를 확인하세요."]}]}]};
